insert into volumes (id, title_ml) values (1, 'വാല്യം 1') on conflict (id) do nothing;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 1, 'ആമുഖമായി', '33', '35');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'ഖുർആനും ഹദീസുമാണ് ഇസ്ലാമിന്റെ അടിസ്ഥാനങ്ങൾ എന്നു മനസ്സിലാക്കിയശേഷം ഓരോ പ്രശ്നം വരുമ്പോഴും അതിനെക്കുറിച്ച് ഖുർആൻ എന്തു പറയുന്നു എന്നു നോക്കാൻ ഈ ഗ്രന്ഥകാരൻ ശ്രമിക്കാറുണ്ടായിരുന്നു. ഖുർആൻ പരിഭാഷകളും ഖുർആൻ ഇൻഡക്സുകളും നോക്കി ഖുർആനിൽ ആ വിഷയകമായി വന്ന വാക്യങ്ങൾ കണ്ടെത്തൽ എളുപ്പമായിരുന്നു. എന്നാൽ ഹദീസിന്റെ സ്ഥിതി അങ്ങനെയല്ല. മുസ്ലിം ലോകം അംഗീകരിച്ച ഹദീസുകളുടെ ശേഖരമായ അസ്സിഹാഹുസ്സിത്ത മുപ്പതിലധികം വാല്യങ്ങളിലായാണുള്ളത്. അവയിൽ നിന്ന് ഒരു വിഷയത്തെക്കുറിച്ച് ഹദീസുകൾ കണ്ടെത്താൻ പ്രയാസമാണ്. എല്ലാ കിതാബുകളും ഒന്നിച്ച് ഒരിടത്ത് ഉണ്ടാവുക എന്നതും അപൂർവ്വം. ഉണ്ടെങ്കിൽ തന്നെ അതിൽ നിന്ന് വിഷയത്തോടു ബന്ധപ്പെട്ട ഹദീസുകൾ കണ്ടെത്തുക എന്നതും പ്രയാസകരം. ഒരേ ഹദീസ് തന്നെ റാവികൾ (റിപ്പോർട്ടർമാർ) വ്യത്യസ്തമായാൽ വ്യത്യസ്ത ഹദീസായിട്ടായിരിക്കും ഗ്രന്ഥങ്ങളിൽ ഉണ്ടാവുക. കൂടാതെ, ഒരു ഗ്രന്ഥത്തിൽ വന്ന ഹദീസ് മറ്റു ഗ്രന്ഥങ്ങളിലും ആവർത്തിച്ചിരിക്കും. പണ്ഡിതന്മാർക്കു പോലും ഈ ഹദീസ് ഗ്രന്ഥങ്ങളിൽ നിന്ന് ആവശ്യമുള്ള ഹദീസുകൾ കണ്ടെത്തുക എന്നത് ദുഷ്കരമാണ്.', null, '33' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'ഈ സാഹചര്യത്തിലാണ് ഹദീസ് എൻസൈക്ലോപീഡിയ (ഹദീസ് വിജ്ഞാന കോശം) എന്ന ആശയമുണ്ടായത്. കാലിക്കറ്റ് യൂണിവേഴ്സിറ്റിയിൽ ഓറിയന്റൽ ഫാക്കൽറ്റി ഡീനായിരുന്ന ശൈഖ് മുഹമ്മദ് മൗലവി, അറിയപ്പെടുന്ന ഒരു ഹദീസ് പണ്ഡിതനായിരുന്നു. ഹദീസു സംബന്ധമായ സംശയങ്ങൾക്ക് പലരും അദ്ദേഹത്തെയാണ് സമീപിച്ചിരുന്നത്. അദ്ദേഹം മരിച്ചപ്പോൾ ഒരു സ്മരണിക പ്രസിദ്ധീകരിക്കാൻ തീരുമാനിച്ചു. അതിലേക്ക് ഒരു ലേഖനം ആവശ്യപ്പെട്ടു. ആ സ്മരണികയിൽ ''ഹദീസ് എൻസൈക്ലോപീഡിയയുടെ ആവശ്യകത'' എന്ന തലക്കെട്ടിൽ ഞാൻ ഒരു ലേഖനമെഴുതി. പലരുമായും, ഈ വിഷയവുമായി ബന്ധപ്പെട്ടുവെങ്കിലും പ്രായോഗികമായി പുരോഗതി ഉണ്ടായില്ല. നല്ല ആശയമാണെന്ന് പറഞ്ഞെങ്കിലും അതിലെ ബുദ്ധിമുട്ടുകളാണ് പലരും ചൂണ്ടിക്കാണിച്ചത്. ഹദീസുകൾ പുനഃക്രോഡീകരിക്കാനും, തർജ്ജമ ചെയ്യാനും പ്രയാസമാണെന്നു പറഞ്ഞ് ചിലർ നിരുത്സാഹപ്പെടുത്തി. ഹദീസുകൾ സമൂഹ മധ്യത്തിൽ പ്രചരിപ്പിച്ചാൽ സമൂഹത്തിൽ പ്രശ്നങ്ങളുണ്ടാവുമെന്ന് ചിലർ പറഞ്ഞു.', null, '33' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'അറബി ഭാഷയിൽ നൈപുണ്യമുള്ളവർ വളരെ പേരുണ്ടെങ്കിലും ഹദീസുകളുടെ സാങ്കേതിക ഭാഷ പരിചയമുള്ളവരും മുഷിഞ്ഞിരുന്ന് ഹദീസുകൾ ക്രോഡീകരിക്കുക, തർജ്ജമ ചെയ്യുക തുടങ്ങിയ ജോലികൾ ഏറ്റെടുക്കാൻ തയ്യാറുള്ളവരും കുറവായിരുന്നു. ഹദീസുകൾ ക്രോഡീകരിക്കുവാനുള്ള ഒരു രീതി കണ്ടെത്തുക എന്നതായിരുന്നു മറ്റൊരു പ്രശ്നം. ഏതാണ്ട് ഇരുപത് കൊല്ലം മുമ്പ് മുതൽ അതിൽ ഗവേഷണം ആരംഭിച്ചു. അന്നു ലഭ്യമായിരുന്ന, ബോംബെയിൽ നിന്ന് പ്രസിദ്ധീകരിക്കുന്ന വലിയ ഗ്രന്ഥങ്ങൾ ഉപയോഗിച്ച് ഹദീസുകൾ ക്രോഡീകരിക്കാൻ ശ്രമമാരംഭിച്ചു. എന്നാൽ അത് വളരെ പ്രയാസകരമായി. പിന്നീടാണ് അറബ് രാജ്യങ്ങളിൽ നിന്നും പ്രസിദ്ധീകരിക്കുന്ന ഗ്രന്ഥങ്ങളുപയോഗിച്ച് ഹദീസ് വിജ്ഞാനകോശം തയ്യാറാക്കാനുള്ള ശ്രമമാരംഭിച്ചത്. കമ്പ്യൂട്ടറുപയോഗിച്ചും ഹദീസിന്റെ ഇൻഡക്സ് ഉപയോഗിച്ചും ഗ്രന്ഥം തയ്യാറാക്കാനുള്ള ശ്രമങ്ങളും പരീക്ഷിച്ചു നോക്കി. അങ്ങനെ കുറച്ചു മുന്നോട്ടു പോയപ്പോഴാണ് ബുഖാരി, മുസ്ലിം, ഇബ്നുമാജഃ, തുർമുദി, നസാഈ, അബൂദാവൂദ് എന്നീ ഗ്രന്ഥങ്ങളുടെ മുഖ്തസർ (സംഗ്രഹം) ലഭ്യമായത്. പിന്നീട് അവ ഉപയോഗിച്ചാണ് മുന്നോട്ടു പോയത്. ഒന്നാം വാല്യം തയ്യാറായെങ്കിലും അത് പ്രസ്സിൽ കൊടുക്കാനുള്ള രൂപത്തിലാക്കാൻ പ്രയാസമായിരുന്നു. അറബിയും മലയാളവും ഡി.ടി.പി ചെയ്തുണ്ടാക്കാൻ പ്രാപ്തരായവരെ കിട്ടാത്തതായിരുന്നു പ്രശ്നം.', null, '33' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'സാധാരണ പരിചിതമായ നിസ്കാരം, നോമ്പ്, സക്കാത്ത്, ഹജ്ജ് തുടങ്ങിയ വിഷയങ്ങൾക്കു മുമ്പായി മറ്റു വിഷയങ്ങളിലുള്ള ഹദീസുകൾ ആദ്യം ക്രോഡീകരിച്ച് തർജ്ജമ സഹിതം പ്രസിദ്ധീകരിക്കാം എന്നാണ് കരുതിയത്. അതനുസരിച്ച് കച്ചവടം, വസിയ്യത്ത് തുടങ്ങിയ വിഷയങ്ങളിലുള്ള ഹദീസുകൾ ക്രോഡീകരിച്ചു. പിന്നീട്, പലരുടെയും അഭിപ്രായം പരിഗണിച്ച് ബുഖാരി, മുസ്ലിം തുടങ്ങിയ പണ്ഡിതന്മാർ സ്വീകരിച്ച മുൻഗണനാക്രമം തന്നെ (വഹ്‌യ്, ഈമാൻ, നിസ്കാരം, നോമ്പ്, സക്കാത്ത്, ഹജ്ജ് തുടങ്ങിയവ) സ്വീകരിക്കാമെന്നു വെച്ചു. അങ്ങനെയാണ് ഈ ആദ്യ വാല്യം തയ്യാറാക്കിയത്. ഈ വാല്യത്തിൽ വഹ്‌യിന്റെ ആരംഭം, ശുദ്ധി, ഈമാൻ, നിസ്കാരം, മയ്യിത്ത് സംസ്കരണം എന്നിവയാണ് ഉൾപ്പെടുത്തിയിട്ടുള്ളത്. ബുഖാരി, മുസ്ലിം, ഇബ്നുമാജഃ, തുർമുദി, നസാഈ, അബൂദാവൂദ് (അസ്സിഹാഹുസ്സിത്തഃ) എന്ന ആറു ഗ്രന്ഥങ്ങളിൽ ഒരു വിഷയത്തെ കുറിച്ച് വന്ന ഹദീസുകൾ വിഷയക്രമത്തിൽ ക്രോഡീകരിച്ച് മലയാളതർജ്ജുമ അടക്കം തയ്യാറാക്കിയിരിക്കുകയാണ് ചെയ്തിട്ടുള്ളത്. അവ ഏതെല്ലാം ഗ്രന്ഥങ്ങളിൽ വന്നിരിക്കുന്നു എന്ന് ഓരോ ഹദീസിന്റെയും ശേഷം ബ്രാക്കറ്റിൽ കാണിച്ചിരിക്കുന്നു. ഒരേ ഹദീസ് തന്നെ വിവിധ റിപ്പോർട്ടുകളിൽ, ചില വാക്കുകളിൽ പ്രകടമായ വ്യത്യാസമുണ്ടെങ്കിൽ അവ വേറെ തന്നെ കൊടുക്കുന്നതു കൊണ്ട് ചെറിയ തോതിൽ ആവർത്തനമുണ്ടാവും. അതുപോലെ, ഒരു ഹദീസിൽ തന്നെ വിവിധ വിഷയങ്ങൾ പരാമർശിക്കുന്നുണ്ടെങ്കിൽ ആ വിഷയങ്ങളുടെ തലക്കെട്ടിനു കീഴിൽ അവ ആവർത്തിക്കേണ്ടിവരും. അത് ആവർത്തിക്കുക എന്ന രീതിയാണ് അവലംബിച്ചിരിക്കുന്നത്. കാരണം, ആ വിഷയം മാത്രം നോക്കുന്നവരുടെ ശ്രദ്ധയിൽ ആ ഹദീസ് പെടാതെ പോകരുതല്ലോ.', null, '33' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'ഹദീസ് വിജ്ഞാന കോശത്തിന്റെ രണ്ടാം വാല്യവും പുറത്തിറങ്ങിയിട്ടുണ്ട്. മൂന്നാം വാല്യത്തിന്റെയും നാലാം വാല്യത്തിന്റെയും ജോലികൾ വേഗത്തിൽ നടന്നുകൊണ്ടിരിക്കുന്നു. ഇൻശാഅല്ലാഹ്, ഈ സദുദ്യമം പൂർത്തീകരിക്കാൻ അല്ലാഹു അനുഗ്രഹിക്കുമെന്ന് പ്രതീക്ഷിക്കുന്നു.', null, '34' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ഇത് ഹദീസ് വിജ്ഞാനകോശം ഒന്നാം വാല്യത്തിന്റെ രണ്ടാം എഡിഷനാണ്. ഒന്നാം എഡിഷനിൽ വന്ന പിഴവുകളും മറ്റും പരമാവധി തിരുത്താൻ ശ്രമിച്ചിട്ടുണ്ട്. രണ്ടാം എഡിഷനുവേണ്ടി ഗ്രന്ഥം എഡിറ്റു ചെയ്യുകയും സെറ്റു ചെയ്യുകയും ചെയ്ത ഉസ്മാൻ മഹ്ബൂബി വേങ്ങൂർ, മൻസൂർ മഹ്ബൂബി ചാപ്പനങ്ങാടി, ഖുബൈബ് മഹ്ബൂബി മാരിയാട്, അബ്ദുർറഹ്മാൻ മുസ്ലിയാർ പാണ്ടിക്കാട് എന്നിവരെ ഇവിടെ സ്മരിക്കുന്നതോടൊപ്പം അവർക്ക് അല്ലാഹു അർഹമായ പ്രതിഫലം നൽകട്ടെ എന്ന് പ്രാർത്ഥിക്കുകയും ചെയ്യുന്നു.', null, '34' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'രോഗ ബാധിതനായിട്ടുപോലും പി.എം.കെ. ഫൈസി ഈ ഗ്രന്ഥം പരിശോധന നടത്തി. ഈ സംരംഭത്തിന് എല്ലാവിധ പ്രോത്സാഹനവും നൽകിയ അദ്ദേഹത്തിന് അല്ലാഹു ദീർഘായുസ്സും, ആരോഗ്യവും, പരലോക മോക്ഷവും പ്രദാനം ചെയ്യട്ടെ എന്ന് ആത്മാർത്ഥമായി പ്രാർത്ഥിക്കുന്നു. എം.സി അബ്ദുല്ല മൗലവിയും ഈ ഗ്രന്ഥത്തിന്റെ പരിശോധനക്കു വേണ്ടി വളരെ നാളുകൾ ചിലവഴിച്ചു. ഗ്രന്ഥം തയ്യാറാക്കാൻ സഹായിച്ച പലരെയും ഈ അവസരത്തിൽ ഓർക്കേണ്ടതുണ്ട്:', null, '34' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'പ്രൊഫ: വി. മുഹമ്മദ് സാഹിബ്, എ. അബ്ദുസ്സലാം സാഹിബ്, ഡോ: അഹ്മദ് ഇസ്മാഈൽ ലബ്ബ, പ്രൊഫ: കെ. ഹബീബ പാഷ, ഡോ: കെ മുഹമ്മദ് ബഷീർ, മുഹമ്മദ് മുജീബ് കാളിയാർ, മുഹമ്മദ് ശരീഫ് വി.പി, ഇ.എം ശരീഫ് മുതുതല, എം.കെ ഹസ്സൻ കോട്ടുമല, വി.എ.എം ഇസ്ഹാഖ് നദ്‌വി, അബൂബക്കർ പി.കെ, ഉമർ കെ.പി, ഇബ്രാഹീം നദ്‌വി, എൻ.കെ. ഹുസൈൻ, ഷംസുദ്ദീൻ വെളിയംകോട്, അമാനുല്ല എ.കെ, മുഹമ്മദ് അഷ്റഫ് മൗലവി, പ്രൊഫ: മുഹമ്മദ് കുട്ടശ്ശേരി, ഫാറൂഖ് അബ്ദുല്ല നാദാപുരം, ഇ. അബ്ദുൽ ലത്തീഫ്, എം.പി മുഹമ്മദ് ഫൈസൽ അഹ്സനി, അബ്ദുൽ ഖാദർ അഹ്സനി, ഹാരിസ് എം. ഹുദവി, മുഹമ്മദ് അലി ഹുദവി, അൻവർ എ.പി, ശുക്കൂർ.ടി മേലണ്ണം, കബീർ അഞ്ചച്ചവിടി, ഇസ്മാഈൽ എടക്കുളം, റഫീഖ് കെ മമ്പറം, അബ്ദുൽ മജീദ് എൻ.കെ, ഉമൈർ സി.കെ, എം.എ. ആരിഫ, ശുക്കൂർ വള്ളിക്കുന്ന്, സഈദ് കൊട്ടപ്പുറം, ശഫീഖ് സി.പി, റാഷിദ് സി.കെ, മൈമൂന സി.കെ, ആരിഫ പി.പി, സൽമ, വി.എം. കുട്ടി മൗലവി, അബൂബക്കർ താളിയംകുണ്ട്, യൂനുസ്.കെ പേങ്ങാട് എന്നിവർ ഈ സംരംഭത്തിൽ സഹകരിച്ചവരാണ്.', null, '34' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ആദ്യം മുതലേ ഈ സംരഭത്തിൽ അതീവ താൽപര്യം കാണിച്ച വ്യക്തിയാണ് വൈലത്തൂർ പി. അബ്ദുറഹിമാൻ (അൽ അമാൻ ബുക് സ്റ്റാൾ) സാഹിബ്. സിഹാഹുസ്സിത്തയിലെ ഹദീസ് ഗ്രന്ഥങ്ങൾ ലഭ്യമല്ലാതിരുന്ന അവസരത്തിൽ ബോംബെയിൽ നിന്നും കല്ലച്ചിലടിച്ച ഗ്രന്ഥങ്ങൾ അദ്ദേഹം ശേഖരിച്ചുതന്നു.', null, '34' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'വർഷങ്ങളായി നടന്ന ഒരു സംരംഭമായതുകൊണ്ട് ചിലരുടെ പേരുകൾ വിട്ടു പോവാനിടയുണ്ട്. ആരുടെയെങ്കിലും പേരുകൾ വിട്ടുപോയിട്ടുണ്ടെങ്കിൽ ക്ഷമിക്കണമെന്ന് അഭ്യർത്ഥിക്കുന്നു. ഈ സംരംഭവുമായി സഹകരിച്ച എല്ലാവർക്കും അല്ലാഹു മതിയായ പ്രതിഫലം നൽകട്ടെ എന്ന് പ്രാർത്ഥിക്കുന്നു. അല്ലാഹു ഇത് സ്വാലിഹായ ഒരു അമലായി (സൽകർമ്മമായി) സ്വീകരിക്കട്ടെ. ഇതിൽ വല്ല തെറ്റുകളും വന്നിട്ടുണ്ടെങ്കിൽ അല്ലാഹു പൊറുത്തു തരട്ടെ. ആമീൻ.', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'subheading', 'ഈഗ്രന്ഥത്തിൽ ഉപയോഗിച്ച ചുരുക്കരുപങ്ങൾ താഴെ പറയും വിധമാണ്:', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'ബു: ബുഖാരി, മു: മുസ്ലിം, ദ: അൂദാവൂദ്, തു: തുർമുദി, ന: നസാഈ, ജ: ഇബ്നു മാജഃ, ഹ.ശ: ഹദീസ് ശരീഫ്, ഹ: ഹസ്റത്ത്, മ: മീലാദി(ക്രിസുത വർഷം), (ഹി): ഹിജ്റ വർഷം, (റ): റളിയള്ളാഹു അൻഹു/അൻഹാ/അൻഹുമാ/അൻഹും,(അല്ലാഹു അദ്ദേഹത്തെ/അവരെ തൃപ്തിപ്പെടട്ടെ), (റ): റഹിമഹുള്ളാ(അല്ലാഹു അദ്ദേഹത്തിന് കരുണ ചെയ്യട്ടെ), (സ): സ്വല്ലല്ലാഹു അലൈഹി വസല്ലമ (അല്ലാഹു രക്ഷയും അനുഗ്രഹവും തിരുമേനിക്ക് മേൽ ചൊരിയട്ടെ), (അ): അലൈഹിസ്സലാം (അല്ലാഹുവിന്റെ രക്ഷയുണ്ടാവട്ടെ).', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'മുഖ്തസറു സ്വഹീഹിൽ ബുഖാരി (ഇമാം സൈനുദ്ധീൻ അഹ്മദ്)', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'മുഖ്തസ്വറു സ്വഹീഹി മുസ്ലിം (ഹാഫിള് സക്കീയുദ്ദീൻ അബ്ദുൽ അളീം)', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'മുഖ്തസറു സുനനി തിർമിദീ (ഡോ: മുസ്തഫദൈബ് അൽബഗാ)', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'മുഖ്തസറു സുനനുന്നസാഈ (ഡോ: മുസ്തഫ ദൈബ് അൽബഗാ)', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'മുഖ്തസറു സുനനി അബീ ദാവൂദ് (ഡോ: മുസ്തഫ ദൈബ് അൽബഗാ)', null, '35' from articles where volume_id=1 and section_no=1;
