insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 19, 'paragraph', 'അന്നിഹായ ഫീ ഗരീബിൽ ഹദീസി വൽ അഥർ (ഇബ്നുൽ അഥീർ) എന്നീഗ്രന്ഥങ്ങളാണ് ഈ ഗ്രന്ഥം തയ്യാറാക്കാൻ പ്രധാനമായും അവലംബമാക്കിയത്.', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 20, 'paragraph', 'ഈ ഗ്രന്ഥത്തിൽ എന്തെങ്കിലും തെറ്റുകൾ ആരുടെയെങ്കിലും ശ്രദ്ധയിൽ പെടുകയാണെങ്കിൽ അവ എഴുതി അറിയിക്കണമെന്ന് സവിനയം അഭ്യർത്ഥിക്കുന്നു.', null, '35' from articles where volume_id=1 and section_no=1;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 21, 'paragraph', 'ഡോ: മുസ്തഫാ കമാൽ പാഷ', null, '35' from articles where volume_id=1 and section_no=1;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 2, 'അവതാരിക', '37', '38');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'അല്ലാഹുവിന് സ്തുതി.', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'പ്രവാചക പ്രഭുവിലും അനുചരരിലും അല്ലാഹുവിന്റെ രക്ഷയും കരുണയും സദാ വർഷിക്കുമാറാവട്ടെ...', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', '"ഈ ഖുർആൻ നാം താങ്കൾക്ക് അവതരിപ്പിച്ചു തന്നിരിക്കുന്നു. ജനങ്ങൾക്കായി അവതീർണ്ണമായതിനെ താങ്കൾ അവർക്കു വിശദീകരിച്ചു കൊടുക്കുവാനും അവർ ചിന്തിച്ചു ഗ്രഹിക്കാനുമാണിത്." (അന്നഹ്ൽ: 44)', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'വിശുദ്ധ ഖുർആൻ അല്ലാഹുവിന്റെ വചനങ്ങളാകുന്നു. അതിന്റെ പ്രഖ്യാപനമാണ് തിരുസുന്നത്ത്. സുന്നത്തു തന്നെയാണ് ഹദീസ്. അശ്റഫുൽ ഖൽഖിന്റെ വാക്കുകളും പ്രവൃത്തികളുമാണത്. തിരുദൂതരുടെ അറിവോടെ പറയുകയോ പ്രവൃത്തിക്കുകയോ ചെയ്ത കാര്യങ്ങളെക്കുറിച്ച് അവിടുന്ന് മൗനം പാലിച്ചാൽ അതും സുന്നത്തിൽ പെടുന്നു. തിരുനബിയുടെ വിശദീകരണവും വ്യാഖ്യാനവുമില്ലാതെ ഖുർആൻ തനിയെ മാർഗ്ഗദർശനത്തിന് മതിയായതല്ലെന്ന് മേൽപ്പറഞ്ഞ ആയത്തടക്കം നിരവധി വാക്യങ്ങളിലൂടെ അല്ലാഹു വ്യക്തമാക്കിയിരിക്കുന്നു. ഹദീസിന്റെ ആവശ്യകതയും പ്രാധാന്യവും മഹത്വവുമാണ് ഇതിൽ നിന്നും നമുക്ക് മനസ്സിലാവുന്നത്..', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'ഖുർആൻ, മലക്കുകളിലൂടെ അല്ലാഹുവിന് ജനങ്ങളിലേക്കെത്തിക്കാമായിരുന്നു. അല്ലെങ്കിൽ ഓരോ വ്യക്തിക്കും ഓരോ ഗ്രന്ഥമെന്ന തോതിൽ നൽകാമായിരുന്നു. എന്നാൽ സർവ്വശക്തന്റെ താൽപര്യമതായിരുന്നില്ല. മിറച്ച് നബി(സ)യിലൂടെ ഖുർആൻ ജനങ്ങളിലേക്കെത്തിക്കുകയും അവിടുന്ന് അത് ജനങ്ങൾക്ക് വിവരിച്ചു കൊടുക്കുകയും അവരുടെ സംശയങ്ങളും അവർ അഭിമുഖീകരിക്കുന്ന പ്രശ്നങ്ങളും പരിഹരിച്ചു കൊടുക്കുകയും ചെയ്യലായിരുന്നു പരമകാരുണികന്റെ ലക്ഷ്യം.', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'അപ്പോൾ, സത്യവിശ്വാസികൾക്ക് അവരുടെ ജീവിതത്തിന് മാർഗ്ഗ ദർശനം നൽകാനായി നബിതിരുമേനി നൽകിയ ഓരോ നിർദ്ദേശങ്ങളും വിധിവിലക്കുകളും അല്ലാഹുവിന്റെ ഇഷ്ടാനുസരണമായിരുന്നുവെന്നു വ്യക്തമായി. ഖുർആനിന്റെ അവതരണ ലക്ഷ്യത്തിന് നബി(സ)യുടെ വിശദീകരണം അനിവാര്യമാക്കിയതു മുഖേന ഹദീസിനെ നിഷേധിക്കുന്നവൻ ഖുർആൻ അംഗീകരിക്കാത്തവനാണെന്ന് അല്ലാഹു സ്ഥാപിക്കുന്നു. കാരണം അല്ലാഹു പ്രവാചകനിലൂടെ ഖുർആൻ ഇറക്കിയതു മുഖേന വെറുതെ ഒരാവശ്യവുമില്ലാത്ത കാര്യം - അല്ലാഹുവിൽ അഭയം - ചെയ്തുവെന്നാണല്ലോ അവരുടെ വാദത്തിൽ നിന്നും തെളിയുക.', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'നബി(സ) അരുളി: "ജനങ്ങളേ, രണ്ടു കാര്യങ്ങൾ നിങ്ങളിൽ അവശേഷിപ്പിച്ചാണ് ഞാൻ പോവുന്നത്. അവ രണ്ടും മുറുകെ പിടിക്കുന്നപക്ഷം ഒരുകാലത്തും നിങ്ങൾക്ക് പിഴവു സംഭവിക്കില്ല. ഒന്ന്; അല്ലാഹുവിന്റെ ഗ്രന്ഥം, രണ്ട്; തിരുസുന്നത്ത്. അണപ്പല്ലുകൾകൊണ്ട് നിങ്ങളവ കടിച്ചു പിടിക്കുക." (മുവത്വാ)', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'കിഴക്കിന്റെയോ പടിഞ്ഞാറിന്റെയോ അതിർവരമ്പുകളിൽ ഒതുങ്ങാത്ത ലോക നേതാവായിരുന്നു മുഹമ്മദ് നബി(സ). ലക്ഷോപലക്ഷം ജനങ്ങളുടെ മനസ്സാന്തരങ്ങളിലെ അന്ധകാരം തുടച്ചു നീക്കിയ ഉജ്ജ്വല പ്രകാശമാണ് നബി(സ). കോടാനകോടികളുടെ കണ്ണിലും കരളിലും തൗഹീദിന്റെ പൊൻവെളിച്ചം കൊളുത്തിക്കൊടുത്ത ആത്മീയ ജ്വാലയാണ് പ്രവാചകൻ. തിരുദൂതർ സ്വയം അവരോധിതനായ ഒരു നവോത്ഥാന നായകനായിരുന്നില്ല. സർവ്വലോക രക്ഷിതാവ് അവതരിപ്പിച്ച സത്യപ്രബോധകനാണ് നബിതങ്ങൾ(സ). അതുകൊണ്ടുതന്നെ അവിടുത്തെ ഉദ്ബോധനങ്ങളും സ്രഷ്ടാവിൽ നിന്നുള്ളതു തന്നെയായാകുന്നു. "അവിടുന്ന് സ്വന്തം ഇഷ്ടാനുസരണം സംസാരിക്കുകയില്ല, അവിടുത്തേക്ക് അവതീർണ്ണമായ ദിവ്യബോധനമല്ലാതെ ........" (53:3,4)', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', '"അഹമിദി പിതു: പരിമേധാ മൃതസ്യ ജാഗ്രഹ അഹം സൂര്യ ഇവാജനീ" (സാമവേദം കക 6-8) (അഹമ്മദിന് ജഗൽ പിതാവിൽ നിന്നും വേദജ്ഞാനം ലഭിച്ചു. ഈ വേദജ്ഞാനങ്ങളെല്ലാം തത്വം നിറഞ്ഞവയാണ്. സൂര്യനിൽ നിന്നെന്ന പോലെ ഞാൻ അവനിൽ നിന്നും പ്രകാശം സ്വീകരിക്കുന്നു.)', null, '37' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'അവൻ സ്വമേധയാ ആയിരിക്കില്ല സംസാരിക്കുന്നത്, അവൻ കേൾക്കുന്നത് മാത്രം സംസാരിക്കും. (യോഹന്നാൻ 16:12,13)', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'മനുഷ്യോന്മുഖമായ ഒരു മഹാ പ്രസ്ഥാനത്തിന്റെ തലപ്പത്തിരുന്ന് ദിവ്യ വെളിപാടുകളുടെ പ്രത്യേകതയാൽ സമഗ്ര മനുഷ്യ വിമോചനത്തിനും മാനസിക വിപ്ലവത്തിനും തിരികൊളുത്തിയ അദ്വിതീയനായിരുന്നു മുഹമ്മദ് നബി(സ).', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'പതിനാല് നൂറ്റാണ്ടുകൾക്കപ്പുറത്തോ ഇപ്പുറത്തോ ഇത്രയേറെ അനുകരിക്കപ്പെടുകയും അനുസരിക്കപ്പെടുകയും ചെയ്യുന്ന ഒരു മനുഷ്യ നേതാവ് ലോകത്ത് വേറെയില്ല. അവിടുത്തെ നിർദ്ദേശങ്ങൾ എല്ലാ ജനതക്കും പ്രയോജനകരമായിരുന്നു. ഒരുകാലത്ത് സുബദ്ധം മറ്റൊരുകാലത്ത് അബദ്ധം, ഒരു ജനതക്ക് സ്വീകാര്യം മറ്റൊരു ജനതക്ക് അസ്വീകാര്യം, ഒരു പ്രദേശത്തേക്ക് പര്യാപ്തം മറ്റൊരു ദേശത്തേക്ക് അപര്യാപ്തം അങ്ങിനെയായിരുന്നില്ല.', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'തിരുനബിയുടെ ഹദീസുകൾ രേഖപ്പെടുത്തപ്പെട്ട അനേകം ഗ്രന്ഥങ്ങളുണ്ട്. അവയിൽ ഏറ്റവും പ്രാമാണിക യോഗ്യമായതാണ് ''സ്വിഹാഹുസ്സിത്തഃ''. മുസ്തഫാ കമാൽ പാഷാ സാഹിബ് കേരള മുസ്ലിംകൾക്ക് അവരുടെ ഭാഷയിൽ ആ ഗ്രന്ഥങ്ങളെ പരിചയപ്പെടുത്തുകയാണ്. ''സ്വിഹാഹുസ്സിത്തഃ'' ഉലമാക്കൾ മാത്രം കൈകാര്യം ചെയ്തിരുന്നവയാണ്. സാധാരണക്കാരന് അവ എന്നും അപ്രാപ്യമായിരുന്നു. ബുഖാരി, മുസ്ലിം പോലുള്ളവരുടെ ഗ്രന്ഥങ്ങൾ മാത്രമാണ് അക്കൂട്ടത്തിൽ നിന്നും മലയാളത്തിലേക്ക് വന്നത്. ഈ പ്രബല ഗ്രന്ഥങ്ങളിൽ നിന്നും പെട്ടെന്നൊരു നബിവചനം കണ്ടെത്തുക പണ്ഡിതന്മാർക്കു പോലും ദുഷ്കരമായിരുന്നു. കാരണം അവയോരോന്നിന്റെയും വിഷയ ക്രമീകരണം അത്തരത്തിലായിരുന്നു. ഇവയിൽ ''സ്വഹീഹു മുസ്ലിം'' എന്ന ഗ്രന്ഥം മാത്രമാണ് വിഷയക്രമത്തിൽ എളുപ്പത്തിൽ ഹദീസുകൾ ക്രോഡീകരിച്ചത്. അത്തരം സാങ്കേതികത്വമെല്ലാം ഇനി സാധാരണക്കാർക്കുപോലും എളുപ്പമാകത്തക്ക നിലയിലാണ് ജ:കമാൽ പാഷയുടെ ഈ ശ്രമം.', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'അല്ലെങ്കിലും മറ്റാരും നടക്കാത്ത വഴിയിലൂടെ നടക്കാൻ എന്നും കമാൽ പാഷ ശ്രമിച്ചിരുന്നു. അദ്ദേഹം കാലഘട്ടത്തിന്റെ വിളികേട്ടു. കാലത്തിന്റെ ആവശ്യമറിഞ്ഞു. അതിന് തന്നാൽ കഴിയുന്നത് ചെയ്യുകയും ചെയ്തു. ''അസ്സ്വലാത്ത്'' എന്ന നിസ്കാരം പഠിക്കാനുതകുന്ന കാസറ്റും, ''ഖുർആനിലെ ചരിത്ര ഭൂമിയിലൂടെ'' എന്ന പ്രസിദ്ധ ശ്രമവുമെല്ലാം അതിൽ ചിലതു മാത്രമാണ്. അവയിൽ ഏറ്റവുമൊടുവിലത്തെ ത്യാഗപൂർണ്ണമായ പരിശ്രമമാണ് അനുവാചകരുടെ കയ്യിലിരിക്കുന്ന ഗ്രന്ഥം! ഇത്തരത്തിലൊന്ന് മലയാളത്തിൽ ആദ്യത്തേതാണ്. ഹദീസിനെ സ്നേഹിക്കുന്ന പ്രവാചക പ്രഭുവിനോടുള്ള പ്രേമം നെഞ്ചു പൊള്ളിക്കുന്ന ഏതൊരു സത്യവിശ്വാസിക്കും ഇത് പുളകം പകരുന്ന അനുഭവമായിരിക്കും തീർച്ച.', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'സർവ്വശക്തൻ ഇതൊരു സ്വാലിഹായ അമലായി സ്വീകരിക്കട്ടെ. പാഷ സാഹിബിന് ജഗന്നിയന്താവ് ദീർഘായുസ്സ് നൽകുകയും മുസ്ലിം സമുദായത്തിന് അദ്ദേഹത്തിൽ നിന്ന് ഒരുപാട് സംഭാവനകൾ ഇനിയും ലഭിക്കുകയും ചെയ്യട്ടെ എന്ന് ആശംസിക്കുന്നു.', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'വിനീതൻ,', null, '38' from articles where volume_id=1 and section_no=2;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'ഹാഫിസ് പി.എൻ അബ്ദുൽ ഗഫ്ഫാർ മൗലവി,', null, '38' from articles where volume_id=1 and section_no=2;
