insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'മുഹമ്മദ് നബി(സ)യുടെ വാക്ക്, പ്രവൃത്തി, മൗനാനുവാദങ്ങൾ എന്നിവ ഉൾക്കൊള്ളുന്ന ജീവിതത്തിന് സുന്നത്ത് എന്ന് സാങ്കേതിക ഭാഷയിൽ പറയുന്നു. ഹദീസ് എന്ന പേരിൽ അറിയപ്പെടുന്നത് ഈ സുന്നത്തിന്റെ പ്രാമാണികമായ രേഖകളാണ്.', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'വിശുദ്ധ ഖുർആനാണ് ഇസ്ലാമിന്റെ ഏറ്റവും പ്രബലമായ പ്രമാണം. രണ്ടാം പ്രമാണമത്രെ ഹദീസ്. യഥാർത്ഥത്തിൽ വിശുദ്ധ ഖുർആന്റെ ഏറ്റവും വിശ്വസ്തവും ആധികാരികവുമായ വ്യാഖ്യാനവും വിശദീകരണവുമാണ് തിരുസുന്നത്ത്.', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'നിയമ നിർദ്ധാരണ രംഗത്ത് വിശുദ്ധ ഖുർആന് തൊട്ടടുത്തുള്ള സ്ഥാനമാണ് സുന്നത്തിന് കൽപിക്കപ്പെടുന്നത്. വിശുദ്ധ ഖുർആനിന്റെ പ്രാമാണികതയും ആധികാരികതയും സ്ഥാപിക്കുന്നതുതന്നെ തിരുസുന്നത്താണ്.', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'ഇരുപത്തിമൂന്ന് വർഷങ്ങളിലായാണ് വിശുദ്ധ ഖുർആനിന്റെ അവതരണം പൂർത്തിയായത്. ഓരോ സന്ദർഭങ്ങളിലും അവതീർണ്ണമാകുന്ന ഖുർആനിക വചനങ്ങൾ മനുഷ്യ മനസ്സുകൾക്ക് ഉൾക്കൊള്ളാവുന്ന വിധം വ്യാഖ്യാനിച്ചു നൽകുകയും അതിഗഹനമായ ആശയങ്ങൾ സരളമായി വിശദീകരിച്ചു കൊടുക്കുകയുമായിരുന്നു തിരുനബി(സ). ഖുർആനിന്റെ പ്രായോഗിക രീതിയും വ്യാഖ്യാനവുമായിരുന്നു നബി(സ)യുടെ ജീവിതം. നബി(സ)യുടെ സ്വഭാവം ഖുർആനായിരുന്നുവെന്ന് സാരം. ഈ വ്യഖ്യാനങ്ങളും വിശദീകരണങ്ങളുമാണ് ഖുർആനിക വചനങ്ങളുടെ പൊരുളും അവതരണ ലക്ഷ്യങ്ങളും മനുഷ്യ മനസ്സിന് ബോധ്യപ്പെടുത്തിയത്.', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'തിരുസുന്നത്ത് ഖുർആനികാധ്യാപനങ്ങളെ ഊട്ടിയുറപ്പിക്കുകയും ദൃഢീകരിക്കുകയും ചെയ്യുന്നു. ചിലപ്പോൾ ഖുർആനിന്റെ നിർദ്ദേശങ്ങൾ അത് വിശദീകരിച്ചു തരികയും നിയമ വിധികളുടെ പൂർണ്ണരൂപം പഠിപ്പിക്കുകയും ചെയ്യുന്നു. നിസ്കാരം, നോമ്പ്, സകാത്ത്, ഹജ്ജ് തുടങ്ങിയ കർമ്മ വിഷയങ്ങളും വിവരിച്ചു തരുന്നതും നിയമ സമുച്ചയങ്ങൾ ക്രോഡീകരിക്കുന്നതും തിരുസുന്നത്താണ്.', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'അതുകൊണ്ടുതന്നെ തിരുസുന്നത്തിനെ അവഗണിച്ചു കൊണ്ടുള്ള ഒരു നിയമ നിർമ്മാണം ഇസ്ലാമിൽ സ്വീകാര്യമല്ല. ഇക്കാര്യം വിശുദ്ധ ഖുർആൻ തന്നെ നിരുപാധികം വ്യക്തമാക്കിയിട്ടുണ്ട്: "റസൂൽ കൊണ്ടു വന്നത് നിങ്ങൾ സ്വീകരിക്കുക. അവിടുന്ന് വിലക്കിയത് നിങ്ങൾ ഒഴിവാക്കുക." (അൽ ഹശ്ർ: 7) "അവർക്കിടയിൽ തർക്ക വിഷയമായതിൽ താങ്കളെ അവർ വിധികർത്താവാക്കുകയും യാതൊരു മനഃക്ലേശവുമില്ലാതെ താങ്കളുടെ വിധി സ്വീകരിക്കുകയും ചെയ്യുന്നതുവരെ അവർ വിശ്വാസികളായിത്തീരുകയില്ല. നിന്റെ റബ്ബിനെ തന്നെയാണു കട്ടായം." (അന്നിസാഅ്: 65)', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'തിരുനബി(സ) പറഞ്ഞു: "തന്റെ പ്രത്യേക സ്ഥാനങ്ങളിലിരുന്ന് തനിക്കു ലഭിക്കുന്ന ഹദീസുകളെക്കുറിച്ച് ഒരാൾ പ്രതികരിച്ചേക്കാം. അയാൾ പറയും: നമുക്കും നിങ്ങൾക്കുമിടയിൽ അല്ലാഹുവിന്റെ കിതാബുണ്ട്. അതിൽ ഹലാലാണെന്നു കണ്ടത് ഹലാലാണെന്ന് നാം അംഗീകരിക്കും. ഹറാമായി കണ്ടത് ഹറാമായും അംഗീകരിക്കും. എന്നാൽ അല്ലാഹുവിന്റെ റസൂൽ ഹറാമായി കണ്ടത് അല്ലാഹു ഹറാമാക്കിയതു പോലെ തന്നെയാണ്." (അബൂദാവൂദ്)', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'തിരുസുന്നത്തിന്റെ പ്രാമാണികത വിശുദ്ധ ഖുർആനും തിരുനബിയും വ്യക്തമാക്കിയിട്ടുണ്ട്. തന്റെ ശിഷ്യരായ സ്വഹാബികളുടെ കൂടി വ്യാഖ്യാനങ്ങളും വിശദീകരണങ്ങളും അംഗീകരിച്ചു കൊണ്ടാണ് സുന്നത്തിനെ സ്വീകരിക്കേണ്ടതെന്നും തിരുമേനി(സ) പഠിപ്പിച്ചിരിക്കുന്നു; "എന്റെ സുന്നത്ത് നിങ്ങൾ മുറുകെപ്പിടിക്കുക. സന്മാർഗ്ഗ സിദ്ധരായ ഖുലഫാഇന്റെ സുന്നത്തും." (ഹ.ശ) "എന്റെ സ്വഹാബികൾ നക്ഷത്ര സമാനരാണ്. അവരിൽ ആരെ അനുസരിച്ചാലും നിങ്ങൾ സന്മാർഗ്ഗ സിദ്ധരായിരിക്കും. (ഹ.ശ)', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ഈ അടിസ്ഥാനത്തിൽ തിരുനബിയുടേതു പോലെ തന്നെ പ്രാമാണികവും വിശ്വസ്തവുമായി തെളിഞ്ഞ സ്വഹാബികളുടെ വാക്ക്, പ്രവൃത്തി, മൗനാനുവാദങ്ങൾ എന്നിവയും സുന്നത്തിന്റെ വ്യാപ്തിയിൽ പെടുന്നുണ്ട്. പൂർവ്വകാല പണ്ഡിതന്മാർ ഇതംഗീകരിച്ചു വരികയും കർമ്മശാസ്ത്ര വിഷയങ്ങളിലും മറ്റും അവർ നടത്തിയ ഗവേഷണങ്ങൾക്ക് പ്രാമാണമായി ഇവയെ സ്വീകരിക്കുകയും ചെയ്തിട്ടുണ്ട്.', null, '39' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'ആനുകാലിക വിഷയങ്ങൾക്കു വിധി കണ്ടെത്താനായി ഗവേഷണത്തിലേർപ്പെടുമ്പോൾ സുന്നത്തിനെ ഈ വ്യാപ്തിയോടെ തന്നെയായിരുന്നു അവർ സ്വീകരിച്ചതും അവലംബിച്ചതും.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'തിരുസുന്നത്തിന്റെ പ്രാമാണികത എന്നും അംഗീകരിക്കുക, അതിനെ പ്രമാണമായി സ്വീകരിക്കുക എന്നത് തിരുനബിയിൽ വിശ്വസിക്കുന്നതിന്റെ ഭാഗമാണ്. സുന്നത്തിനെ അംഗീകരിക്കാത്തവർ തിരുനബിയെതന്നെ അവിശ്വസിക്കുകയാണ് ചെയ്യുന്നത്.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'വിശുദ്ധ ഖുർആൻ അവതരണ സന്ദർഭത്തിൽ തന്നെ രേഖപ്പെടുത്തി വെക്കാൻ നബി(സ) നിർദ്ദേശിച്ചിരുന്നു. എഴുത്തിനെ അത്യധികം പ്രോത്സാഹിപ്പിക്കുകയും പ്രബോധനാവശ്യത്തിന് ഉപയോഗിക്കുകയും ചെയ്ത നബി(സ) എഴുത്തും വായനയും പഠിപ്പിക്കാൻ വ്യത്യസ്ത പദ്ധതികൾ ആവിഷ്കരിക്കുകയും ചെയ്തിരുന്നു.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'ഖുർആൻ പ്രത്യേകം എഴുതി സൂക്ഷിക്കുവാൻ നിർദ്ദേശമുള്ളതു കൊണ്ട് അതിന്റെ കൂടെ മറ്റൊന്നും കൂടിക്കലരാൻ അവസരമൊരുക്കരുതെന്ന നിലക്ക് ഖുർആനല്ലാത്ത എന്റെ വചനങ്ങൾ എഴുതി വെക്കരുതെന്ന് നബി(സ) വിലക്കിയിരുന്നു. ഇക്കാരണത്താൽ ആദ്യ സന്ദർഭങ്ങളിൽ ഹദീസുകൾ ക്രോഡീകരിക്കപ്പെടുകയോ ഖുർആൻ പോലെ ഗ്രന്ഥ രൂപത്തിൽ രേഖപ്പെടുത്തുകയോ ചെയ്തിരുന്നില്ല.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'പിന്നീട് ഇസ്ലാം ലോകത്തിന്റെ നാനാഭാഗങ്ങളിൽ അതിശീഘ്രം പ്രചരിക്കുകയും വ്യത്യസ്ത സംസ്കാരങ്ങളും സാമ്രാജ്യങ്ങളും ഇസ്ലാമിന്റെ പരിധിയിൽ വരികയും ചെയ്തു. സംസ്കാരങ്ങളുടെ സമ്മേളനവും സമൂഹങ്ങളുടെ കൂടിച്ചേർച്ചയും വിശ്വാസാനുഷ്ടാന രംഗങ്ങളിൽ പുതിയ പ്രശ്നങ്ങളും സംശയങ്ങളും ജനിപ്പിക്കുകയും അതാതു സന്ദർഭങ്ങളിലുയർന്നു വരുന്ന പ്രശ്നങ്ങൾക്ക് പ്രമാണങ്ങളുടെ വെളിച്ചത്തിൽ പരിഹാരം നിർദ്ദേശിക്കാൻ പണ്ഡിതന്മാർ ബാധ്യസ്ഥരാവുകയും ചെയ്തു.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'ഈ സന്ദർഭത്തിൽ ഇസ്ലാമിലേക്കു കടന്നുവന്ന ചില വിഭാഗങ്ങൾ വിശുദ്ധ ഖുർആനിനെ വികലമായി മനസ്സിലാക്കാനും പാരായണം ചെയ്യാനും ഇടവരുമെന്ന് മനസ്സിലാക്കിയതുകൊണ്ട് ഹ: അബൂബക്കർ(റ)യുടെ കാലത്ത് ഗ്രന്ഥമായി ക്രോഡീകരിക്കപ്പെട്ടു കിടന്നിരുന്ന വിശുദ്ധ ഖുർആനിന്റെ പകർപ്പുകളെടുത്ത് വ്യത്യസ്ത പ്രവിശ്യകളിലേക്കയക്കുകയും ആ രാജ്യങ്ങളിലെ ഖുർആൻ പഠനം ഈ അടിസ്ഥാന ഗ്രന്ഥമവലംബിച്ചാവണമെന്ന് കണിശമായ നിർദ്ദേശം നൽകുകയും ചെയ്തു. ഹ: ഉസ്മാ(റ)ന്റെ കാലത്താണ് ഈ നടപടിയുണ്ടായത്.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'തിരുനബിയുടെ കാലത്തു തന്നെ രേഖപ്പെടുത്തപ്പെട്ട ഖുർആൻ "മുസ്ഹഫ്" രൂപത്തിൽ എഴുതി ഒറ്റ ഗ്രന്ഥമായി ക്രോഡീകരിക്കുകയും പകർപ്പുകളെടുത്ത് കൈമാറുകയുമാണ് അബൂബക്കർ(റ), ഉമർ(റ), ഉസ്മാൻ(റ) തുടങ്ങിയ ഫലീഫമാർ ചെയ്തത്. അതിൽ എന്തെങ്കിലും കൂട്ടുകയോ കുറക്കുകയോ ചെയ്തിട്ടില്ല. ഇതുകാരണം വിശുദ്ധ ഖുർആനിന്റെ പേരിൽ ക്രിത്രിമ ഗ്രന്ഥങ്ങളോ സൂക്തങ്ങളോ നിർമ്മിക്കാൻ ശ്രമിച്ച ജൂത ക്രൈസ്തവ ലോബികൾക്കു പോലും ഖുർആനിനെ വികൃതമാക്കാൻ സാധിച്ചില്ല.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'എന്നാൽ ആദ്യ കാലത്ത് ഈ കണിശത തിരുസുന്നത്തിന്റെ വിഷയത്തിൽ പുലർത്തിയിരുന്നില്ല. ചുരുക്കം ചില സ്വഹാബികൾ മാത്രമെ ഹദീസുകൾ രേഖപ്പെടുത്തി വെച്ചിരുന്നുള്ളൂ.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 18, 'paragraph', 'അമവി ഖലീഫമാരിൽ പ്രമുഖനായ ഉമറുബ്നു അബ്ദിൽ അസീസിന്റെ ഭരണ കാലത്ത് ഇവ്വിഷയകമായി ഔദ്യോഗിക ചർച്ചകളും പഠനങ്ങളും നടന്നു. സ്വഹാബി പ്രമുഖരെല്ലാം ഇഹലോകവാസം വെടിഞ്ഞതോടെ ഹദീസുകൾ നഷ്ടപ്പെടുകയും തിരുസുന്നത്ത് എന്തെന്നറിയാത്ത സാഹചര്യം ഉണ്ടാവുകയും ചെയ്യുമെന്ന് ഭയപ്പെട്ട് ഖലീഫ ഉമറുബ്നു അബ്ദിൽ അസീസ് തിരുനബിയുടെ ഹദീസുകൾ ക്രോഡീകരിക്കാനും രേഖപ്പെടുത്തി വെക്കാനും നിർദ്ദേശിച്ചു.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 19, 'paragraph', 'ഈ നിർദ്ദേശാടിസ്ഥാനത്തിൽ ആദ്യമായി ഹദീസ് ശേഖരിക്കാൻ മുന്നോട്ടു വന്ന മഹാ പണ്ഡിതനാണ് അല്ലാമാ മുഹമ്മദുബ്നു ശിഹാബ് അൽ സുഹ്‌രി. ആദ്യമായി ഹദീസ് ക്രോഡീകരിച്ച വ്യക്തി എന്ന ഖ്യാതി അദ്ദേഹത്തിനുള്ളതാണ്. ഈ കാലഘട്ടത്തിൽ മറ്റുപല പണ്ഡിതന്മാരും ഹദീസ് ശേഖരിക്കാൻ ഇറങ്ങിത്തിരിച്ചു. ശൈഖ് ഇബ്നു ജുറൈജ് (മ.150) ഇബ്നു ഇസ്ഹാഖ് (മ.150) ഇമാം മാലിക് (മ.179) റബീഅതുബ്നു സ്വബീഹ് (മ.160) സഈദു ബ്നുൽ അബീ അറുബത് (മ.156) ഹമ്മാദുബ്നു സലമ (മ.167) സുഫ്‌യാനുസ്സൗരി (മ.161) ഇമാം ഔസാഈ (മ.157) ഹ: ഹുശൈം (മ.183) മഅ്മർ (മ.153) ജരീറുബ്നു അബ്ദിൽ ഹമീദ് (മ.188) ഇബ്നുൽ മുബാറക് (മ.181) തുടങ്ങിയ മഹാ പണ്ഡിതന്മാർ ഹദീസ് ശേഖരണ രംഗത്ത് സജീവമായി ഇറങ്ങിത്തിരിച്ചു.', null, '40' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 20, 'paragraph', 'മക്ക, മദീന, ബസ്വറ, കൂഫ, ശാം, വാസിത്വ്, യമൻ, ഖുറാസാൻ തുടങ്ങിയ രാജ്യങ്ങളിൽ ഈ പണ്ഡിതന്മാർ ഹദീസ് ശേഖരണത്തിന് നേതൃത്വം നൽകി. അവർ ശേഖരിച്ച ഹദീസുകൾ ഗ്രന്ഥങ്ങളാക്കി ക്രോഡീകരിക്കുകയും ചെയ്തു.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 21, 'paragraph', 'ഇസ്ലാമിക സാമ്രാജ്യം വീണ്ടും വികസിക്കുകയും ഇസ്ലാമിലേക്കു വന്ന പുത്തൻ സമൂഹങ്ങളിൽ പഴയ ആത്മീയ വ്യക്തിത്വവും വിശുദ്ധിയും ഇല്ലാതെ പോവുകയും ചെയ്ത സാഹചര്യത്തിൽ ചില തൽപര കക്ഷികളും കപട വിശ്വാസികളും വ്യാജ ഹദീസുകൾ ചമയ്ക്കാൻ തുടങ്ങുകയും ഹദീസുകൾ വികലമാക്കാൻ തുടങ്ങുകയും ചെയ്തു.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 22, 'paragraph', 'ഈ സാഹചര്യത്തിൽ അതാതു കാലത്തെ പണ്ഡിതന്മാർ ഹദീസ് സംരക്ഷണത്തിനായി ചില മാനദണ്ഡങ്ങൾ നിശ്ചയിക്കുകയും, ഈ മാനദണ്ഡമനുസരിച്ച് സ്വീകാര്യമായ ഹദീസുകൾ ക്രോഡീകരിക്കുകയും ചെയ്തു. അങ്ങെനെ "ഇൽമുൽ ഹദീസ്" എന്ന ഹദീസ് വിജ്ഞാന ശാഖ തന്നെ രൂപപ്പെടുകയും ചെയ്തു.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 23, 'paragraph', 'ഈ രംഗത്ത് ഏറ്റവും കൂടുതൽ കണിശത പാലിക്കുകയും ഹദീസ് പഠനത്തിനും അന്വേഷണത്തിനുമായി ജീവിതം മാറ്റിവെക്കുകയും ചെയത പ്രമുഖ പണ്ഡിതനാണ് ഇമാം ബുഖാരി. ഏഴു ലക്ഷത്തോളം ഹദീസുകൾ ക്രോഡീകരിച്ച് അവയുടെ ഗ്രേഡുകൾ തന്റെ കണിശമായ നിയമങ്ങൾക്കനുസരിച്ച് നിശ്ചയിച്ച ഇമാം ബുഖാരി(റ) ഇവയിൽ തെരഞ്ഞെടുത്തവ മാത്രം ഉൾക്കൊള്ളിച്ചു കൊണ്ടാണ് സ്വഹീഹുൽ ബുഖാരി രചിച്ചത്. വിശുദ്ധ ഖുർആനിനു ശേഷം ഏറ്റവും പ്രാമാണികമായ ഗ്രന്ഥം ബുഖാരിയാണെന്ന് മുസ്ലിം ലോകം ഒന്നടങ്കം അംഗീകരിച്ച യാഥാർത്ഥ്യമാണ്.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 24, 'paragraph', 'സ്വഹീഹു മുസ്ലിം, തിർമുദി, അബൂദാവൂദ്, നസാഈ, ഇബ്നുമാജഃ എന്നിവയാണ് ബുഖാരിക്കു ശേഷം ഏറ്റവും പ്രാമാണികമായവ. ഇവക്ക് സ്വിഹാഹുസ്സിത്തഃ എന്നു പറയപ്പെടുന്നു. ഇമാം മാലികിന്റെ മുവത്വ ഈ രംഗത്തെ ശ്രദ്ധേയമായ ആദ്യഘട്ട രചനയാണ്. ഇമാം അഹ്മദുബ്നു ഹമ്പൽ, ഇബ്നു ഖുസൈമ, ഇബ്നു ഹിബ്ബാൻ, ഹാകിം തുടങ്ങി ഒട്ടനേകം ഹദീസ് പണ്ഢതന്മാർ ഈ രംഗത്ത് മഹാ ത്യാഗങ്ങൾ സഹിച്ച് ശ്രമങ്ങളർപ്പിച്ചിട്ടുണ്ട്.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 25, 'paragraph', 'പതിനായിരത്തിൽപരം സ്വഹാബി വര്യന്മാരിൽ നിന്നായി ലക്ഷക്കണക്കായ ഹദീസുകൾ ക്രോഡീകരിക്കപ്പെട്ടിട്ടുണ്ടെങ്കിലും വളരെ പരിമിതമായവ മാത്രമാണ് ഗ്രന്ഥ രൂപത്തിൽ സൃഷ്ടിക്കപ്പെടുകയും പിൻതലമുറക്ക് ലഭിക്കുകയും ചെയ്തിട്ടുള്ളത്.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 26, 'paragraph', 'ഹദീസ് പഠനത്തിനും ശരീഅത്ത് വിജ്ഞാനങ്ങളുടെ പ്രചാരണത്തിനുമായി ഇന്ത്യൻ പണ്ഡിതന്മാർ അനർഘ സേവനങ്ങൾ അർപ്പിച്ചിട്ടുണ്ട്. ഒട്ടനേകം ഹദീസ് വ്യാഖ്യാനങ്ങൾ ഇന്ത്യൻ പണ്ഡിതന്മാരുടേതായുണ്ട്. പക്ഷേ, ഈ രംഗത്ത് കേരളീയ പണ്ഡിതന്മാരുടെ ശ്രമങ്ങൾ താരതമ്യേന കുറവാണെന്നതു ഖേദപൂർവ്വം നാം ഓർക്കുക.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 27, 'paragraph', 'പുതിയ തലമുറയിൽപെട്ട ചിലർക്കെങ്കിലും ഹദീസിന്റെ പ്രാമാണികതയെക്കുറിച്ച് സംശയങ്ങളുണ്ട്. ഓറിയന്റലിസ്റ്റ്, സയണിസ്റ്റ് ശക്തികൾ ബോധപൂർവ്വം ഇസ്ലാമിനെ തെറ്റിദ്ധരിപ്പിക്കാൻ നടത്തിയ ശ്രമങ്ങളുടെ ഫലമാണത്. ഹദീസിന്റെ വിശ്വാസ്യതയിൽ സംശയം ജനിപ്പിക്കുകയും പ്രാമാണിക ഗ്രന്ഥങ്ങളുടെ ആധികാരികത ചോദ്യം ചെയ്യപ്പെടുകയും ചെയ്യുന്നതോടെ ഹദീസ് വിജ്ഞാനം ദുർബലമാവുമെന്നും അതോടെ ഇസ്ലാമിന്റെ സൗന്ദര്യവും നിയമങ്ങളുടെ ഭദ്രതയും പ്രസക്തിയും നഷ്ടപ്പെടുമെന്നും അവർ ധരിച്ചു.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 28, 'paragraph', 'സ്വിഹാഹുസ്സിത്തഃ എന്ന പ്രമാണിക ഗ്രന്ഥങ്ങളുടെ ആധികാരികതെക്കുറിച്ച് മുസ്ലിം പണ്ഡിത സമൂഹത്തിന് സന്ദേഹമില്ല. ഹദീസുകളുടെ ബലാബലം നിർണ്ണയിക്കാൻ നമ്മുടെ മുന്നിലുള്ള ഏക മാർഗ്ഗം പൂർവ്വീകരുടെ തീരുമാനങ്ങളംഗീകരിക്കുകയും പിന്തുടരുകയുമാണ്.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 29, 'paragraph', 'ഇമാം നവവി(റ), ഇമാം ഇബ്നു ഹജർ(റ), സുയൂത്വി(റ) തുടങ്ങിയ മഹാ പണ്ഡിതന്മാർ അന്നു ലഭ്യമായ ഏറ്റവും സൂക്ഷ്മവും കണിശവുമായ മാർഗ്ഗങ്ങൾ സ്വീകരിച്ചു കൊണ്ടാണ് ഹദീസുകൾ അപഗ്രഥനം ചെയ്തത്. അവർക്കുശേഷം നൂറ്റാണ്ടുകൾ പിന്നിട്ട ഈ കാലഘട്ടത്തിൽ അവർക്കു ലഭ്യമായ വഴികൾ പോലും നമ്മുടെ മുമ്പിലില്ല എന്നത് നഗ്ന സത്യമാണ്. ഈ സാഹചര്യത്തിൽ പൂർവ്വീകരുടെ പഠനങ്ങളും ശ്രമങ്ങളും അംഗീകരിക്കുകയല്ലാതെ മറ്റു വഴികൾ നമ്മുടെ മുന്നിലില്ല. പുതിയൊരു രീതി നിനച്ചുണ്ടാക്കാനുള്ള ഏതു ശ്രമവും ഫലശൂന്യമായിരിക്കും. വിശ്വാസത്തിനും മത നിയമങ്ങൾക്കുമെതിരെ പുത്തൻ വെല്ലു വിളികൾ ഉയർന്ന സാഹചര്യത്തിൽ അവയുടെ പ്രമാണങ്ങളെക്കുറിച്ചുള്ള അന്വേഷണങ്ങൾ സ്വാഭാവികമാണെങ്കിലും വിശ്വാസങ്ങൾ സമർത്ഥിക്കാനും ചിലർ പ്രമാണങ്ങളുദ്ധരിക്കുമ്പോൾ പ്രമാണങ്ങളറിയാത്ത സാധാരണക്കാർ ആശയക്കുഴപ്പത്തിലാവുന്നു.', null, '41' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 30, 'paragraph', 'ഹദീസുകളായാലും വിശുദ്ധ ഖുർആനായാലും അവയിൽ നിന്ന് നേരിട്ട് മതവിധിയും വിശ്വാസത്തിന്റെ തെളിവുകളും കണ്ടെത്താൻ സാധാരണക്കാർക്ക് കഴിയില്ല. മഹാപണ്ഡിതന്മാർക്കുവരെ പ്രയാസമുള്ള കാര്യമാണിത്. അതുകൊണ്ടുതന്നെ ഇത്തരം വിഷയങ്ങളിൽ പൂർവ്വകാല പണ്ഡിത മഹത്തുക്കളെ പിന്തുടരുകയാണ് അഭികാമ്യം. അതേഅവസരം പ്രമാണങ്ങളുമായി അടുത്ത ബന്ധം സ്ഥാപിക്കുന്നത് പലപ്പോഴും തെറ്റിദ്ധാരണകളിൽ നിന്ന് രക്ഷപ്പെടാൻ സഹായിച്ചേക്കും.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 31, 'paragraph', 'വിശുദ്ധ ഖുർആനും തിരുസുന്നത്തും മറ്റുള്ളവർക്കു മനസ്സിലാക്കാനുള്ള സാഹചര്യം സൃഷ്ടിക്കുന്നതിന് അവയുടെ വ്യാഖ്യാനങ്ങളും ഇതര ഭാഷകളിലേക്കുള്ള മൊഴിമാറ്റങ്ങളും സഹായകമാണ്.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 32, 'paragraph', 'സ്വിഹാഹുസ്സിത്തയിലെ ആവർത്തനങ്ങളൊഴിവാക്കിയുള്ള ഹദീസുകളുടെ മലയാള സാരം. ഇതൊരു വലിയ ശ്രമമാണ്. ദീർഘ കാലത്തെ ക്ഷമയും ത്യാഗവും അതിന്നാവശ്യമാണ്. പ്രമുഖ ദഅ്വാ പ്രവർത്തകനും ചരിത്ര പണ്ഡിതനുമായ ഡോക്ടർ മുസ്തഫാ കമാൽ പാഷ കിട്ടാവുന്നിടത്തോളം പണ്ഡിതന്മാരുടെയും ടെക്നോളജിയുടെയും സഹായം തേടിക്കൊണ്ടാണ് ഇങ്ങനെയൊരു ശ്രമത്തിനു മുന്നോട്ടു വന്നത്. ഈ ശ്രമം പ്രോത്സാഹന ജനകമാണെന്നതു കൊണ്ട് ചെറിയ അനുഭവവും അറിവും ഉപയോഗിച്ച് കഴിയുന്ന സഹായങ്ങൾ ഈ വിനീതനും വാഗ്ദത്തം നൽകി. നന്മയിൽ സഹകരിക്കുക എന്ന നിലക്ക്. ഗുണകാംക്ഷ മാത്രം.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 33, 'paragraph', 'ഗ്രന്ഥത്തിന്റെ പ്രഥമ വാല്യമാണ് നിങ്ങളുടെ കയ്യിൽ. പല ഭാഗങ്ങളും തിരക്കിനിടയിൽ ഓടിച്ചു വായിക്കാൻ ശ്രമിക്കുകയും ചിലതെല്ലാം എഡിറ്റു ചെയ്ത് സഹായിക്കുകയും ചെയ്തിട്ടുണ്ട്.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 34, 'paragraph', 'പരസ്പര വിരുദ്ധമെന്നു തോന്നിക്കുന്ന ചില ഹദീസുകൾ കാണാം. ഉദാ: പെരുന്നാൾ ആഘോഷം വെള്ളിയാഴ്ച വന്നാൽ അന്ന് ജുമുഅഃ വേണമോ? വേണ്ടയോ? രണ്ട് വീക്ഷണവും ഹദീസിൽ കാണാം. സാധാരണ ജുമുഅഃ നിർബന്ധമില്ലാത്തവർ, ജുമുഅക്ക് ആൾ തികയാത്ത ഗ്രാമവാസികളും നാടോടികളും മറ്റും ദൂരദിക്കുകളിൽ നിന്നു പെരുന്നാൾ നിസ്കരിക്കാനെത്തിയപ്പോൾ അവരോടാണ് നിങ്ങളിനി ജുമുഅക്ക് വരേണ്ടെന്ന് തിരുനബി പറഞ്ഞത്. അല്ലാത്തവരോട് ജുമുഅഃ കൂടി നിർവ്വഹിക്കണമെന്ന് നിർദ്ദേശിക്കുകയും ചെയ്തു.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 35, 'paragraph', 'ഹദീസിന്റെ സാഹചര്യവും നിർദ്ദേശിക്കപ്പെട്ട സദസ്സിന്റേയോ വ്യക്തിയുടേയോ സ്ഥിതിഗതികളുമെല്ലാം വ്യക്തമായി മനസ്സിലാകുമ്പോൾ മാത്രമേ ഈ വിശദീകരണം ലഭിക്കുകയുള്ളൂ. അല്ലാത്തവർ ഹദീസുകളുടെ വാചാർത്ഥം സ്വീകരിച്ച് ആശയക്കുഴപ്പത്തിലാവുകയും ചെയ്യും.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 36, 'paragraph', 'ഇത്തരം ഹദീസുകളെ വിശദീകരിക്കാൻ സ്ഥല പരിമിതി കാരണം ശ്രമിച്ചിട്ടില്ല. വായനക്കാർ വ്യാഖ്യാന ഗ്രന്ഥങ്ങൾ അവലംബിച്ച് മനസ്സിലാക്കുമെന്ന ഉത്തമ വിശ്വാസത്തോടെ കേവലം സാരാർത്ഥങ്ങൾ മാത്രമാണ് ഈ ഗ്രന്ഥത്തിൽ നൽകിയിട്ടുള്ളത്. അപൂർവ്വം ചില ഉദ്ധരണികളും.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 37, 'paragraph', 'തിരുസുന്നത്തുമായി പരിചയപ്പെടാനും ഇസ്ലാമിക വൈജ്ഞാനിക പാരമ്പര്യങ്ങൾ കൊണ്ട് വിശ്വാസത്തിന്റെ സരണിയിൽ അണിചേരാനും ഈ ഗ്രന്ഥം സഹായകമാവുമെന്ന ശുഭാപ്തി വിശ്വാസത്തോടെ ഇങ്ങനെ ഒരു സാഹസത്തിന് ആത്മാർത്ഥമായി മുന്നോട്ടു വന്ന ഡോക്ടർ മുസ്തഫാ കമാൽ പാഷയെ അഭിനന്ദിക്കുന്നു.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 38, 'paragraph', 'മൊഴിമാറ്റത്തിനും പരിശോധനക്കും മറ്റുമായി അദ്ദേഹത്തോടൊപ്പം നിന്ന സഹായികൾക്കും സഹോദരങ്ങൾക്കുമെല്ലാം ആശംസകൾ നേർന്നുകൊണ്ട്;', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 39, 'paragraph', 'പി. എം. കെ. ഫൈസി മോങ്ങം.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 40, 'paragraph', 'ചീഫ് എഡിറ്റർ', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 41, 'paragraph', 'അൽ ഇർഫാദ് മാസിക.', null, '42' from articles where volume_id=1 and section_no=3;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 42, 'paragraph', 'കോഴിക്കോട്.', null, '42' from articles where volume_id=1 and section_no=3;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 4, 'മുഹമ്മദ് നബി(സ): ഒരു ലഘു ചരിത്രം', '43', '50');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'മനുഷ്യനൊഴിച്ച് മറ്റു ജീവികളെല്ലാം ജന്മ വാസനക്കൊത്ത് ജീവിക്കുന്നു, എങ്ങനെ ജീവിക്കണമെന്ന് നേരത്തെ നിർണ്ണയിക്കപ്പെട്ടിരിക്കുന്നു. അവക്ക് പ്രകൃത്യാ തന്നെ നിർണ്ണിതമായ ഒരു ജീവിത രീതിയുണ്ട്, അതുപേക്ഷിച്ച് മറ്റൊരു ജീവിത രീതി കണ്ടെത്താനോ സ്വീകരിക്കാനോ സാധ്യമല്ല. മനുഷ്യന്റെ സ്ഥിതി അതല്ല; അവന്റെ ജീവിത മാർഗ്ഗം അവൻ തന്നെ സ്വയം ഇച്ഛാശക്തി ഉപയോഗിച്ച് തെരഞ്ഞെടുക്കേണ്ടതാണ്. അതിനാൽ ജീവിതത്തിൽ മാർഗ്ഗ ദർശനം ഏറ്റവും കൂടുതൽ ആവശ്യമായിട്ടുള്ളത് മനുഷ്യന്നാണ്. അവൻ ചിന്താശീലനാണ്. ഓരോ കാര്യം ചെയ്യുമ്പോഴും ഏതാണ് ശരി, ഏതാണ് തെറ്റ് എന്നീ ചിന്തകൾ അവന്റെ മുമ്പിലുയരുന്നു. അതുപോലെ മരണ ശേഷം ജീവിതമുണ്ടോ, അതോ എല്ലാം മരണത്തോടു കൂടി അവസാനിക്കുമോ എന്നീ ചോദ്യങ്ങളും അവനെ അലട്ടുന്നു. അവക്കുള്ള ഉത്തരം പരീക്ഷണ നിരീക്ഷണങ്ങൾ നടത്തി കണ്ടു പിടിക്കാനും കഴിയുന്നതല്ല. പ്രപഞ്ചം സൃഷ്ടിക്കുകയും സംവിധാനിക്കുകയും ചെയ്ത ദൈവം, മനുഷ്യനു വേണ്ടതെല്ലാം പ്രകൃതിയിൽ സജ്ജീകരിച്ച ദൈവം, മനുഷ്യന്റെ സുപ്രധാനമായ ഈ ആവശ്യം - ജീവിത മാർഗ്ഗ ദർശനം - അവഗണിച്ചിട്ടില്ല. അതുകൊണ്ടാണ് ആദ്യ മനുഷ്യനും മാനവ കുലത്തിന്റെ പിതാവുമായ ആദം(അ) തന്നെ ഒരു പ്രവാചകനായത്. അതിനു ശേഷം എപ്പോഴെല്ലാം ധർമ്മം ക്ഷയിക്കുകയും അധർമ്മം വർദ്ധിക്കുകയും ചെയ്തുവോ, അപ്പോഴെല്ലാം മാനവ കുലത്തിനു മാർഗ്ഗ ദർശനം ചെയ്യാൻ പ്രവാചകന്മാർ വന്നതായി നാം ചരിത്രത്തിൽ കാണുന്നു. ''ഒരു പ്രവാചകനും വരാത്ത ഒരു സമുദായവും ഇതിനു മുമ്പ് കഴിഞ്ഞു പോയിട്ടില്ല.'' എന്നാണ് ഖുർആൻ ഇതിനെക്കുറിച്ചു പറഞ്ഞത്.', null, '43' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'ബാബിലോണിയയിൽ നിന്നു ലഭിച്ച ഒരു പുരാതന കൽചിത്രത്തിൽ ''ഹമ്മുറാബി'' ദൈവത്തിൽ നിന്നും നിയമ ഗ്രന്ഥം സ്വീകരിക്കുന്നതായി ചിത്രീകരിച്ചിരിക്കുന്നു. ഇന്ത്യയിലെ വേദങ്ങൾ ദൈവത്തിൽ നിന്നും അവതരിച്ചു കിട്ടിയവയാണെന്നു വിശ്വസിക്കപ്പെടുന്നു. വേദങ്ങൾക്ക് ''അപുരുഷ്യ'' (മനുഷ്യ നിർമ്മിതമല്ലാത്തത്) ''നിത്യ'' (എന്നെന്നും നില നിൽക്കുന്നത്) ''ശ്രുതി'' (ദൈവത്തിൽ നിന്നും കേട്ടത്) എന്നീ പേരുകൾ സംസ്കൃതത്തിലുണ്ടെന്നതും ശ്രദ്ധേയമാണ്. ശ്രീ ബുദ്ധന്റെ പേരുതന്നെ സൂചിപ്പിക്കുന്നത് ''ബോധനം ലഭിച്ച വ്യക്തി'' എന്നാണല്ലോ. അങ്ങിനെ എത്രയോ പ്രവാചകന്മാർ ലോകത്തിന്റെ വിവിധ ഭാഗങ്ങളിൽ പല ഘട്ടങ്ങളിലായി വന്നു. മൂസ(അ)യും, ഈസ(അ)യും, മുഹമ്മദ് നബി(സ)യും അടുത്ത കാലത്തായി വന്നവരാണെന്നു മാത്രം. പഴയ ദൈവിക മാർഗ്ഗദർശന ഗ്രന്ഥങ്ങൾ പുരോഹിതന്മാരുടെ വെട്ടിത്തിരുത്തലുകൾക്കും കൂട്ടിക്കുറക്കലുകൾക്കും വിധേയമായപ്പോഴാണ് പുതിയ പ്രവാചകന്മാർ വന്നത്. പ്രവാചക പരമ്പരയിലെ അവസാനത്തെ കണ്ണിയാണ് മുഹമ്മദ് നബി(സ).', null, '43' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'അറേബ്യയിലെ ഒരു പ്രമുഖ കുടുംബമായ ഖുറൈശികളിൽപെട്ട അബ്ദുൽ മുത്ത്വലിബിന്റെ മകൻ അബ്ദുല്ലയുടെ മകനായി ക്രിസ്താബ്ദം അഞ്ഞൂറ്റി എഴുപത്തി ഒന്നിൽ മുഹമ്മദ് നബി(സ) ജനിച്ചു. ജനനത്തിനു മുമ്പുതന്നെ പിതാവ് മരിച്ചിരുന്നു. അദ്ദേഹം അബ്ദുൽ മുത്ത്വലിബിന്റെ സംരക്ഷണത്തിലാണ് വളർന്നത്. ബാലനായിരിക്കെ തന്നെ അബ്ദുൽ മുത്ത്വലിബും മരണമടഞ്ഞു. പിന്നീട് പിതൃസഹോദരനായ അബൂ ത്വാലിബിന്റെ സംരക്ഷണത്തിൽ വളർന്നു.', null, '43' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'നിഷ്കളങ്കമായിരുന്നു ആ ബാലന്റെ സ്വഭാവം. ആ ബാലനുമായി ബന്ധപ്പെട്ടവരെല്ലാം അവനെ സ്നേഹിക്കുകയും, ബഹുമാനിക്കുകയും ചെയ്തു. എപ്പോഴും സത്യത്തിനു വേണ്ടി നിലകൊണ്ട ആ ബാലൻ ''അൽ അമീൻ'' അഥവാ ''വിശ്വസ്തൻ'' എന്ന അപരനാമത്താൽ അറിയപ്പെട്ടു. യുവാവായിരിക്കെ അദ്ദേഹം വ്യാപാരത്തിലേർപ്പെട്ടു. അവിടത്തോടൊപ്പം കൂട്ടുകച്ചവടക്കാരനായിരുന്ന ഖൈസ്, അദ്ദേഹത്തേക്കാൾ നല്ല കൂട്ടുകാരനെ കച്ചവടത്തിന് തനിക്ക് ലഭിച്ചിട്ടില്ലെന്ന് പ്രസ്താവിക്കുന്നു.', null, '43' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'ഖദീജ മക്കയിലെ ഒരു വർത്തക പ്രമുഖയായിരുന്നു. അവർ മുഹമ്മദിന്റെ വിശ്വസ്തതയെക്കുറിച്ച് കേട്ടു. സിറിയയിൽ വില്ക്കാനുള്ള കുറെ ചരക്കുകൾ അവർ അദ്ദേഹത്തെ ഏൽപിച്ചു. തന്നെ ഏൽപിച്ച കാര്യം ഭംഗിയായി അദ്ദേഹം നിർവ്വഹിച്ചു. മുഹമ്മദ് നബി(സ)യുടെ ആത്മാർത്ഥതയും, വിശ്വസ്തതയും ഖദീജയിൽ മതിപ്പുളവാക്കി. അതു വിധവയായ അവരെ അവിടത്തോട് വിവാഹാലോചന നടത്താൻ പ്രേരിപ്പിച്ചു. പിതൃവ്യന്റെ അനുഗ്രഹാശിസ്സുകളോടെ മുഹമ്മദ്(സ)യും ഖദീജയും തമ്മിലുള്ള വിവാഹം നടന്നു. അവർ ഒരു മാതൃകാ ദാമ്പത്യ ജീവിതമാണ് നയിച്ചത്. ഖദീജ(റ) എല്ലായ്പ്പോഴും മുഹമ്മദ്നബി(സ)ക്ക് ഒരു തണലായിരുന്നു. വിഷമ വേളകളിൽ അവരദ്ദേഹത്തിന് ആശ്വാസമായി. ദാരിദ്ര്യ വേളകളിൽ അദ്ദേഹത്തെ സഹായിച്ചു. പിൽക്കാലത്ത് മുഹമ്മദ് നബി(സ) ഇസ്ലാമിക പ്രബോധനം ആരംഭിച്ചപ്പോൾ ആദ്യമായി വിശ്വസിച്ചത് അവരാണ്.', null, '43' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'അവിടുന്ന് പലപ്പോഴും അടുത്തു തന്നെയുള്ള ''ഹിറാ'' ഗുഹയിൽ പോയി ധ്യാനത്തിലിരിക്കും. അവിടത്തേക്ക് നാൽപതു വയസ്സായി, ഒരു ദിവസം പ്രാർത്ഥനാ നിരതനായിരിക്കെ ''ജിബ്രീൽ'' എന്ന മലക്ക് പ്രത്യക്ഷപ്പെട്ടു അവിടത്തെ ആശ്ലേഷിക്കുകയും, ദൈവികാജ്ഞ പ്രകാരം "വായിക്കുക" എന്ന് കൽപിക്കുകയും ചെയ്തു. പ്രവാചകൻ(സ) തനിക്ക് വായിക്കാനറിയില്ലെന്ന് മറുപടി പറഞ്ഞു. വീണ്ടും ആശ്ലേഷിച്ച് വായിക്കാനാവശ്യപ്പെടുകയും, വായിക്കാനറിയില്ലെന്ന് മറുപടി പറയുകയും ചെയ്തു. മൂന്നാം പ്രാവശ്യം, "സൃഷ്ടിച്ച നിന്റെ രക്ഷിതാവിന്റെ നാമത്തിൽ വായിക്കുക. മനുഷ്യനെ രക്തക്കട്ടയിൽ നിന്നുമവൻ സൃഷ്ടിച്ചു. വായിക്കുക, പേന കൊണ്ട് (എഴുത്തു) പഠിപ്പിച്ചിരിക്കുന്ന അത്യുദാരനാണ് നിന്റെ രക്ഷിതാവ്. മനുഷ്യന് അറിവില്ലാത്തത് മനുഷ്യനെ അവൻ പഠിപ്പിച്ചു." (ഖു: 96:1-5) എന്ന് ആജ്ഞാപിക്കപ്പെട്ടു. അതു ദൈവിക സന്ദേശങ്ങളുടെ തുടക്കമായിരുന്നു. പിന്നീട് അതു പോലെയുള്ള ദൈവിക വചനങ്ങൾ പ്രവാചകർ(സ)ക്ക് പലപ്പോഴായി അവതരിപ്പിക്കപ്പെട്ടു. അവയുടെ സമാഹാരമാണ് ഖുർആൻ. അത് പ്രവാചക വചനങ്ങളല്ല. കലർപ്പില്ലാത്ത ദൈവിക വചനങ്ങൾ തന്നെയാണവ.', null, '44' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'ഭയപ്പെട്ടു വിറച്ചു കൊണ്ട് വീട്ടിലേക്കോടി മൂടിപ്പുതച്ചു കിടന്നു. അപ്പോൾ വീണ്ടും ആ ശബ്ദം അവിടത്തോടാജ്ഞാപിച്ചു: "ഓ മൂടിപ്പുതച്ചു കിടക്കുന്നവനേ, എഴുന്നേൽക്കുക, എന്നിട്ട് (ദുഷിച്ച നടപടികളെക്കുറിച്ച് മനുഷ്യർക്ക്) താക്കീത് നൽകുക, അങ്ങയുടെ രക്ഷിതാവിന്റെ മഹത്വത്തെ പ്രകീർത്തിക്കുക, അങ്ങയുടെ വസ്ത്രങ്ങൾ ശുദ്ധീകരിക്കുക, അശുദ്ധിയെ (പാപത്തെ) വിട്ട് അകന്നു നിൽക്കുക, കൂടുതൽ നേട്ടം കൊതിച്ചു കൊണ്ട് അങ്ങ് ഔദാര്യം ചെയ്യരുത്. അങ്ങയുടെ നാഥനു വേണ്ടി ക്ഷമ കൈക്കൊള്ളുക, കാഹളത്തിൽ ഊതിക്കഴിഞ്ഞാൽ (ലോകാവസാനം വന്നുകഴിഞ്ഞാൽ) അത്, ആ ദിവസം സത്യനിഷേധികൾക്കു വളരെ ഞെരുക്കമുള്ളതും ലഘുവല്ലാത്തതുമായിരിക്കും." (ഖു:74:1-10)', null, '44' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'അങ്ങനെ മുഹമ്മദ് നബി(സ)യെ ജനങ്ങളെ ഉദ്ധരിക്കാനും, താക്കീതു നൽകുവാനും ദൈവം നിയോഗിച്ചു. അവിടുന്ന് പ്രവാചകനായി. പ്രവാചകനായി നിയോഗിക്കപ്പെട്ട ശേഷം അവിടന്ന് പ്രബോധനം ആരംഭിച്ചു. മുഹമ്മദ് നബി(സ)യുടെ ആത്മാർത്ഥതയിൽ, അടുത്തറിയുന്നവർക്കാർക്കും സംശയമുണ്ടായില്ല. ആദ്യമായി ഖദീജ(റ) അദ്ദേഹത്തിന്റെ സന്ദേശം സ്വീകരിച്ചു. അധികം താമസിയാതെ അലി(റ), അബൂബക്കർ(റ), ഉസ്മാൻ(റ), അബ്ദുർറഹ്മാൻ(റ), സഅ്ദ്(റ), സുബൈർ(റ), ത്വൽഹ(റ) എന്നിവരും "മുഹമ്മദ് നബി(സ) ദൈവത്തിന്റെ ദൂതനും, അടിമയുമാണെന്ന്" വിശ്വസിച്ചു.', null, '44' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'പിന്നീടവിടത്തേക്ക് പരസ്യമായി പ്രബോധനമാരംഭിക്കാൻ നിർദ്ദേശം ലഭിച്ചു. മക്കയിലെ ''സ്വഫാ'' എന്ന കുന്നിൻ മുകളിൽ കയറി നിന്നുകൊണ്ട് ജനങ്ങളെ വിളിച്ചു കൂട്ടി. ഈ മലയുടെ അപ്പുറത്ത് നിങ്ങളെ ആക്രമിക്കാൻ ഒരു ശത്രു സൈന്യം തയ്യാറായി നിൽപ്പുണ്ട് എന്നു ഞാൻ പറഞ്ഞാൽ നിങ്ങൾ വിശ്വസിക്കുകയില്ലേ? എന്നു ചോദിച്ചു. "നിങ്ങൾ കളവു പറഞ്ഞതായി ഞങ്ങൾക്കറിയില്ല." അവർ ഉത്തരം പറഞ്ഞു. അപ്പോൾ അവിടന്ന് പറഞ്ഞു: "ഞാൻ നിങ്ങൾക്ക് താക്കീതു നൽകുന്നു; എനിക്ക് ദൈവത്തിൽ നിന്നും ഒരു സന്ദേശം ലഭിച്ചിരിക്കുന്നു, ഒരു ഭയാനകമായ ശിക്ഷയെക്കുറിച്ച് മുന്നറിയിപ്പ് നൽകാനാണ് ഞാൻ വന്നിട്ടുള്ളത്. എനിക്ക് ഈ ലോകത്ത് നിങ്ങളെ സംരക്ഷിക്കാൻ സാധിക്കുകയില്ല. മരണാനന്തര ജീവിതത്തിലും നിങ്ങൾക്ക് സംരക്ഷണം വാഗ്ദത്തം ചെയ്യാൻ എനിക്കു കഴിയില്ല, ''യഥാർത്ഥ ദൈവമല്ലാതെ മറ്റു ദൈവങ്ങളില്ല എന്ന് നിങ്ങൾ വിശ്വസിച്ചാലല്ലാതെ.'' ഇതു കേട്ടപ്പോൾ, ഇതു പറയാനാണോ നീ ഞങ്ങളെ വിളിച്ചത്? എന്നു പറഞ്ഞ് അവർ പിരിഞ്ഞു പോയി.', null, '44' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', 'മുഹമ്മദ് നബി(സ) തന്റെ ദൗത്യം തുടർന്നു കൊണ്ടിരുന്നു. പലരും ഇസ്ലാം സ്വീകരിച്ചു. മക്കയിലെ പ്രധാനികൾക്ക് ഇതൊരു തലവേദനയായി. അവർ ഉത്ബത്ത് എന്ന നേതാവിനെ മുഹമ്മദ്(സ)യുടെ അടുത്തേക്കയച്ചു. ഉത്ത്ബത്ത് മുഹമ്മദ് നബി(സ)യെ സമീപിച്ച് പറഞ്ഞു: "നിങ്ങൾക്ക് ഭരണാധികാരിയാകാനാണ് ആഗ്രഹമെങ്കിൽ നിങ്ങളെ ഞങ്ങൾ ഭരണാധികാരിയാക്കാം, നിങ്ങൾക്കൊരു ധനികനാകാനാണ് ആഗ്രഹമെങ്കിൽ നിങ്ങളെ ഞങ്ങളിൽ വെച്ചേറ്റവും വലിയ ധനികനാക്കാം, ഏതെങ്കിലും സ്ത്രീയെ വിവാഹം കഴിക്കാനാണ് ആഗ്രഹമെങ്കിൽ അതും ഞങ്ങൾ നടത്തിത്തരാം. ഈ പുതിയ പ്രസ്ഥാനം ഉപേക്ഷിച്ചാൽ മാത്രം മതി." അതിനു മറുപടിയായി പ്രവാചകൻ(സ) ഈ ഖുർആൻ വാക്യങ്ങൾ ഉദ്ധരിക്കുകയാണ് ചെയ്തത്. "പറയുക; തീർച്ചയായും ഞാൻ നിങ്ങളെപ്പോലെ ഒരു മനുഷ്യൻ മാത്രമാണ്. നിങ്ങളുടെ ദൈവം ഒരേയൊരു ദൈവം മാത്രമാണെന്ന് എന്നിലേക്ക് ബോധനം നൽകപ്പെട്ടിരിക്കുന്നു. അതുകൊണ്ട് അവനിലേക്ക് നേർവഴിക്കു പോകുകയും അവനോട് നിങ്ങൾ പാപമോചനം തേടുകയും ചെയ്യുവീൻ. (അവനോടു പങ്കു ചേർക്കുന്ന) ബഹു ദൈവ വിശ്വാസികൾക്ക് നാശം." (ഖു:41:6) മറ്റൊരവസരത്തിൽ, പ്രവാചകൻ(സ) വ്യക്തമാക്കി: "അല്ലാഹുവാണ, എന്റെ വലം കയ്യിൽ സൂര്യനേയും ഇടം കൈയിൽ ചന്ദ്രനേയും വെച്ചു തന്നിട്ട് ഈ പ്രസ്ഥാനം ഉപേക്ഷിക്കാൻ അവരെന്നോടാവശ്യപ്പെട്ടാൽ പോലും ഞാനതു ചെയ്യില്ല. ഒന്നുകിൽ അല്ലാഹു ഈ മതത്തെ വിജയിപ്പിക്കുക, അല്ലെങ്കിൽ ഈ പ്രസ്ഥാനം വിജയിപ്പിക്കാൻ വേണ്ടിയുള്ള പരിശ്രമമദ്ധ്യേ ഞാൻ മരണമടയുക. ഇത് രണ്ടിലൊന്ന് സംഭവിക്കും വരെ ഞാൻ പിന്മാറുന്ന പ്രശ്നമേയില്ല."', null, '44' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'മുസ്‌ലിംകളുടെ എണ്ണം വർദ്ധിച്ചു കൊണ്ടിരുന്നു. മുഹമ്മദ് നബി(സ)യുടെ ദൗത്യം സ്വീകരിച്ചവർ ''മുസ്‌ലിംകൾ'' അഥവാ ''ദൈവത്തിന് പൂർണ്ണമായി കീഴ്പ്പെട്ടവർ'' എന്ന പേരിലാണ് അറിയപ്പെട്ടത്. അവരുടെ മതത്തിന് ''ദൈവത്തിനുള്ള പൂർണ്ണമായ വിധേയത്വം'' എന്നർത്ഥമുള്ള ''ഇസ്‌ലാം'' എന്നും പറയുന്നു. മുഹമ്മദീയർ എന്നും, മുഹമ്മദ് മതം എന്നും പറയുന്നത് തെറ്റാണ്. ആദ്യത്തെ മനുഷ്യനായ ആദം(അ) ഒരു പ്രവാചകൻ കൂടിയായിരുന്നു. അദ്ദേഹം മുതൽ അന്ത്യ പ്രവാചകരായ മുഹമ്മദ് നബി(സ) വരെയുള്ള ലക്ഷക്കണക്കിനുള്ള പ്രവാചകന്മാർ പ്രബോധനം ചെയ്ത മത സിദ്ധാന്തങ്ങൾ ഒന്നു തന്നെയാണ്. അവരെല്ലാം പ്രബോധനം ചെയ്ത മതത്തിന്റെ പേരാണ് ഇസ്‌ലാം. ''ഇസ്‌ലാം'' മത സ്ഥാപകൻ മുഹമ്മദ് നബി(സ) അല്ല. അദ്ദേഹം അവസാന പ്രവാചകൻ മാത്രമാണ്. പ്രവാചകന്മാർ തമ്മിൽ വ്യത്യാസം കൽപ്പിക്കാതിരിക്കാൻ വി:ഖു: 2:285 ലൂടെ മുസ്‌ലിംകൾ ആജ്ഞാപിക്കപ്പെട്ടിരിക്കുന്നു.', null, '45' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'മുസ്‌ലിംകളുടെ എണ്ണം വർദ്ധിക്കുന്നത് കണ്ടപ്പോൾ മക്കയിലെ അമുസ്‌ലിം പ്രധാനികൾക്ക് അരിശം വർദ്ധിച്ചു. അവർ പ്രവാചകനെയും അനുചരന്മാരെയും മർദ്ദിക്കാൻ തുടങ്ങി. പ്രവാചകൻ(സ) നടക്കുന്ന വഴിയിൽ മുള്ളുകൾ വിതറി, ചെളിയും ചീഞ്ഞ വസ്തുക്കളും അദ്ദേഹത്തിന്റെ മേൽ എറിഞ്ഞു. മുസ്‌ലിംകളെ ചുട്ടുപഴുത്ത മണലിൽ മലർത്തിക്കിടത്തി, നെഞ്ചിൽ പാറക്കല്ലുകൾ കയറ്റി വെച്ചു. ചിലരെ ചാട്ട കൊണ്ടടിച്ചു. മർദ്ദനം സഹിക്കവയ്യാതായപ്പോൾ, പ്രവാചകൻ(സ) തന്റെ ചില അനുയായികളോട് അബ്‌സീനിയ (എത്യോപ്യ)യിലേക്ക് പലായനം ചെയ്യാൻ നിർദ്ദേശിച്ചു. അന്ന് എത്യോപ്യയിൽ ഒരു ക്രിസ്ത്യൻ രാജാവായ നെഗസ് (നജ്ജാശി) ആയിരുന്നു ഭരിച്ചിരുന്നത്. അങ്ങനെ പ്രവാചക ദൗത്യത്തിന്റെ അഞ്ചാം വർഷം പതിനൊന്ന് പുരുഷന്മാരും, നാല് സ്ത്രീകളും അടങ്ങുന്ന ഒരു സംഘം എത്യോപ്യയിലേക്ക് പലായനം ചെയ്തു.', null, '45' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'മുസ്‌ലിംകൾ പലായനം ചെയ്തതറിഞ്ഞ മക്കയിലെ പ്രധാനികൾ ഒരു സംഘത്തെ എത്യോപ്യയിലെ രാജാവിന്റെ അടുക്കലേക്കയച്ചു. അവർ രാജാവിനെ സമീപിച്ച് ''തങ്ങളിൽ നിന്നും ഓടിപ്പോന്ന അടിമകളാണ് മുസ്‌ലിംകൾ എന്നും അവരെ തങ്ങൾക്ക് വിട്ടുതരണമെന്നും'' അപേക്ഷിച്ചു. രാജാവിന്റെ മുന്നിൽ ഹാജരാക്കപ്പെട്ട മുസ്‌ലിംകൾ ഇങ്ങനെ ബോധിപ്പിച്ചു: "രാജാവെ, ഞങ്ങൾ അജ്ഞതയിലായിരുന്നു, വിഗ്രഹാരാധനയിലും അധർമ്മ ജീവിതത്തിലും മുഴുകി ജീവിക്കുകയായിരുന്നു. ഞങ്ങളിൽ ശക്തിയുള്ളവർ ശക്തി കുറഞ്ഞവരെ ദ്രോഹിച്ചു. ഞങ്ങൾ കള്ളം പറഞ്ഞിരുന്നു, ആഥിത്യ മര്യാദകൾ പാലിച്ചിരുന്നില്ല. അങ്ങനെയിരിക്കെ ഞങ്ങളിൽ ഒരു പ്രവാചകൻ വന്നു. ചെറുപ്പം മുതലേ അദ്ദേഹത്തിന്റെ സ്വഭാവത്തെക്കുറിച്ചും ധാർമ്മിക ജീവിതത്തെക്കുറിച്ചും ഞങ്ങൾക്ക് നന്നായറിയാം. ഞങ്ങളദ്ദേഹത്തിൽ വിശ്വസിക്കുകയും അദ്ദേഹത്തെ അനുഗമിക്കുകയും ചെയ്തു. എന്നാൽ നാട്ടുകാർ ഞങ്ങളെ മർദ്ദിക്കുകയും, ഞങ്ങളുടെ മതത്തെ ഉപേക്ഷിക്കുവാൻ നിർബന്ധിക്കുകയും ചെയ്തു." ഇതുകേട്ടപ്പോൾ രാജാവ് മുസ്‌ലിംകളുടെ കാര്യത്തിൽ തൽപരനാവുകയും അവർക്ക് ലഭിച്ചുവെന്നു പറയുന്ന വേദത്തിന്റെ ചില ഭാഗങ്ങൾ കേൾപ്പിക്കാൻ ആവശ്യപ്പെടുകയും ചെയ്തു. മുസ്‌ലിംകളിൽപ്പെട്ട ജഅ്ഫർ(റ) ഖുർആനിലെ ഒരദ്ധ്യായം വായിച്ചു കേൾപ്പിച്ചു. രാജാവ് അവരെ എത്യോപ്യയിൽ താമസിച്ചുകൊള്ളാൻ അനുവദിച്ചു. അധികം കഴിയുന്നതിനു മുമ്പ് മറ്റൊരു സംഘം കൂടി എത്യോപ്യയിലേക്ക് പലായനം ചെയ്തു. ആ സംഘത്തിൽ നൂറ്റൊന്നു പേരുണ്ടായിരുന്നു. അതിൽ പതിനെട്ട് പേർ സ്ത്രീകളായിരുന്നു.', null, '45' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'മുസ്‌ലിംകളുടെ അംഗസംഖ്യ അനുദിനം വർദ്ധിച്ചു കൊണ്ടിരുന്നത് മക്കയിലെ പ്രധാനികളെ അലോസരപ്പെടുത്തി. അവർ ഒന്നായി സമ്മേളിച്ച് പ്രവാചകർ(സ)യുടെ കുടുംബത്തിന്നെതിരിൽ ഉപരോധം ഏർപ്പെടുത്താൻ നിശ്ചയിച്ചു. അവർക്ക് ധാന്യങ്ങളോ, മറ്റു ആവശ്യ സാധനങ്ങളോ നൽകാൻ പാടില്ലെന്ന് തീരുമാനിച്ചു. ഇത് പ്രവാചകർ(സ)യുടെ കുടുംബത്തെ വളരെയധികം വിഷമിപ്പിച്ചു. ഈ അവസ്ഥ ഏതാണ്ട് മൂന്ന് കൊല്ലം തുടർന്നു. പ്രവാചക ദൗത്യത്തിന്റെ പത്താം വർഷത്തിൽ അമുസ്‌ലിംകളിൽപെട്ട ചില ചെറുപ്പക്കാർ തന്നെ മനുഷ്യത്വ ഹീനമായ ഈ ഉപരോധം പിൻവലിക്കാൻ നേതാക്കന്മാരെ നിർബന്ധിച്ചു. അങ്ങനെ ഉപരോധം നീങ്ങി. അതേവർഷം തന്നെ ഖദീജ(റ)യും പിതൃവ്യൻ അബൂത്വാലിബും അന്തരിച്ചു. മുസ്‌ലിംകൾക്കെതിരെയുള്ള മർദ്ദനം തുടർന്നു കൊണ്ടിരുന്നു.', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'അടുത്ത ഒരു നഗരമായ ത്വാഇഫിലെ ജനങ്ങൾ ഇസ്‌ലാം സ്വീകരിച്ചേക്കുമെന്ന പ്രതീക്ഷയിൽ നബി(സ) അങ്ങോട്ടു പോയി. എന്നാൽ അവിടെയുള്ള ജനങ്ങൾ അവിടുത്തെ കൂക്കി വിളിക്കുകയും, കല്ലെറിഞ്ഞ് ഉപദ്രവിക്കുകയും ചെയ്തു. നബി(സ) മക്കയിലേക്കു തന്നെ മടങ്ങി.', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'മക്കയിൽ ഒരു വാർഷിക ഉത്സവം നടക്കാറുണ്ടായിരുന്നു. ആ ഉത്സവ ദിവസം സമീപ പ്രദേശങ്ങളിൽ നിന്ന് ആളുകൾ വരും. അങ്ങനെ വരുന്ന ജനങ്ങളോട് ദൈവം ഏകനാണെന്നും, അവനെ മാത്രമേ ആരാധിക്കാവൂ എന്നും, മരണാനന്തരം ഈ ലോകത്തെ പ്രവർത്തനങ്ങൾക്കനുസരിച്ച് രക്ഷാശിക്ഷകൾ നൽകപ്പെടുമെന്നും നബി(സ) ഉപദേശിച്ചു കൊണ്ടിരുന്നു. യഥ്‌രിബി(മദീന)ൽ നിന്നും വന്ന ചിലർ പ്രവാചകർ(സ)യുടെ സംഭാഷണത്തിൽ ആകൃഷ്ടരാവുകയും "തങ്ങൾ ഇനിമേൽ ദൈവത്തിന്റെ അധികാരാവകാശങ്ങളിൽ ആരെയും പങ്കുചേർക്കുകയില്ലെന്നും, വ്യഭിചരിക്കുകയോ, കളവു നടത്തുകയോ, കുഞ്ഞുങ്ങളെ കൊല്ലുകയോ, പരദൂഷണം പറയുകയോ, കള്ള വാർത്തകൾ പ്രചരിപ്പിക്കുകയോ ചെയ്യുകയില്ലെന്നും, സുഖദുഃഖങ്ങളിലെല്ലാം പ്രവാചകർ(സ)യോ അനുസരിച്ചു കൊണ്ട് ജീവിക്കുമെന്നും" പ്രതിജ്ഞ ചെയ്തു. അവർ പന്ത്രണ്ടു പേരുണ്ടായിരുന്നു.', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'ഈ ഘട്ടത്തിൽ ഒരു രാത്രിയിൽ അല്ലാഹു പ്രവാചകർ(സ)യെ തന്റെ സന്നിധാനത്തിലേക്കുയർത്തി. ഇതിനെ ഇസ്‌ലാമിന്റെ സാങ്കേതിക ഭാഷയിൽ "മിഅ്റാജ്" എന്നു പറയുന്നു. ഈ അവസരത്തിലാണ് മുസ്‌ലിംകൾ ദിനംപ്രതി അഞ്ചു പ്രാവശ്യം നിസ്കരിക്കണമെന്ന് അല്ലാഹു ആജ്ഞാപിച്ചത്.', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 18, 'paragraph', 'അടുത്ത കൊല്ലം യഥ്‌രിബിൽ നിന്നും എഴുപത്തിമൂന്നുപേർ ഉത്സവ വേളയിൽ മക്കയിൽ വരികയും, ദൈവത്തെയും, പ്രവാചകനെയും അനുസരിച്ചു ജീവിച്ചു കൊള്ളാമെന്ന് പ്രതിജ്ഞയെടുക്കുകയും ചെയ്തു. അവർ പ്രവാചകൻ(സ)യെ തങ്ങളുടെ പട്ടണത്തിലേക്ക് ക്ഷണിച്ചു.', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 19, 'paragraph', 'ഇസ്‌ലാമിന്റെ സ്വാധീനം വർദ്ധിക്കുന്നതു കണ്ട് വിറളിപൂണ്ട മക്കാ നേതാക്കൾ മർദ്ദനത്തിന് രൂക്ഷത വർദ്ധിപ്പിക്കുകയും, നബി(സ)യെ വധിക്കാൻ പരിപാടിയിടുകയും ചെയ്തു. മർദ്ദനം സഹിക്കവയ്യാതായപ്പോൾ തന്റെ അനുയായികളോട് യസ്‌രിബിലേക്ക് പലായനം ചെയ്യാൻ നിർദ്ദേശിച്ചു. നബി(സ)യെ വധിക്കാൻ മക്കയിലെ നേതാക്കൾ പരിപാടിയിട്ട് വീടു വളഞ്ഞ ദിവസം രാത്രി ദൈവിക കൽപന പ്രകാരം തന്റെ ശയ്യയിൽ പിതൃവ്യ പുത്രനും ഇസ്‌ലാമിക പ്രവർത്തകനുമായ അലി(റ)വിനോടു കിടക്കാൻ നിർദ്ദേശിച്ച ശേഷം നബി(സ) തന്റെ സന്തത സഹചാരിയായ അബൂബക്കർ(റ)വിനൊപ്പം യസ്‌രിബിലേക്ക് യാത്രതിരിച്ചു. പകൽ സമയത്ത് ''സൗർ'' എന്ന ഗുഹയിൽ അവർ അഭയം തേടി. പ്രവാചകൻ(സ) രക്ഷപ്പെട്ടു എന്നറിഞ്ഞ് മക്കയിലെ പ്രധാനികൾ പല ഭാഗത്തേക്കും ആളുകളെ പറഞ്ഞയച്ചു. അവരിലൊരു സംഘം നബി(സ)യും അബൂബക്കർ(റ)വും ഒളിച്ചിരിക്കുന്ന ഗുഹാ മുഖത്തെത്തിപ്പെട്ടു. അതു കണ്ട് അബൂബക്കർ(റ) ഭയന്നു. നബി(സ) അദ്ദേഹത്തെ സാന്ത്വനപ്പെടുത്തി. "ദുഃഖിക്കരുത്, ദൈവം നമ്മുടെ കൂടെയുണ്ട്." ഖുറൈശി പ്രമുഖർ പ്രവാചകർ(സ)യെ കാണാതെ തിരിച്ചു പോയി. അവർ രണ്ടുപേരും യഥ്‌രിബിലേക്ക് യാത്ര തുടർന്നു.', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 20, 'paragraph', 'പ്രവാചകർ(സ)ക്ക് ഹാർദ്ദവമായ സ്വീകരണമാണ് ലഭിച്ചത്. നബി(സ) യസ്‌രിബിലെത്തിയതോടെ ഇസ്‌ലാമിക സമൂഹത്തിന് ഒരു നവീന രൂപം കൈവന്നു. ഒരു മാതൃകാ രാഷ്ട്രം കെട്ടിപ്പടുക്കുകയാണ് നബി(സ) അവിടെ ചെയ്തത്. ഒരു നിയമ ഗ്രന്ഥവും ഒരു നേതൃത്വവും ഒരു ദൈവത്തിലുള്ള വിശ്വാസവും നൽകിക്കൊണ്ട് മുസ്‌ലിംകളെ അദ്ദേഹം ഏകീകരിച്ചു. മദീനാ വാസികൾക്ക് ഒരു പുതുനാമം അദ്ദേഹം നൽകി. "അൻസ്വാറുകൾ" അഥവാ സഹായികൾ. മക്കയിൽ നിന്ന് വന്നവർ "മുഹാജിറുകൾ" അഥവാ "അഭയാർത്ഥികൾ" എന്ന പേരിലറിയപ്പെട്ടു. "സത്യ വിശ്വാസികൾ സഹോദരന്മാരാണ്" എന്ന ഖുർആൻ വാക്യം ഉദ്ധരിച്ചുകൊണ്ട് പ്രവാചകൻ(സ) അൻസ്വാറിനെയും മുഹാജിറിനെയും ഒന്നിപ്പിച്ചു. അൻസ്വാറുകളും മുഹാജിറുകളും തമ്മിലുള്ള സ്നേഹബന്ധം സഹോദരന്മാർ തമ്മിലുള്ളതിനെക്കാൾ സുദൃഢമായിരുന്നു. അത് അല്ലാഹുവിന്നു വേണ്ടിയുള്ള സ്നേഹമായിരുന്നു. അൻസ്വാറുകൾ അഭയാർത്ഥികളെ തങ്ങളുടെ വീടുകളിലെ അംഗങ്ങളായി സ്വീകരിക്കുകയും, അവർക്കു വേണ്ടി സഹായ സഹകരണങ്ങൾ ചെയ്യുകയും ചെയ്തു. പല മദീനാ നിവാസികളും തങ്ങളുടെ സമ്പത്തിന്റെ പകുതി മക്കയിൽ നിന്നു വന്നവർക്കു കൊടുത്തു. അവരുടെ കൃഷിയിലും കച്ചവടത്തിലും മുഹാജിറുകളെ പങ്കാളികളാക്കി. മുഹാജിറുകളും അൻസ്വാറുകളും ഇഴുകിച്ചേർന്നു കൊണ്ടുള്ള, സുഖദുഃഖങ്ങൾ പങ്കിട്ടെടുത്തു കൊണ്ടുള്ള ആ ജീവിതം ചരിത്രത്തിൽ തുല്യതയില്ലാത്തതാണ്. ഇതിനെക്കുറിച്ച് ഖുർആൻ പറയുന്നു: "(മക്കയിൽ നിന്ന് ഹിജ്റ പോയവർക്ക്) വീടും, സത്യ വിശ്വാസവും, അവർ എത്തും മുമ്പുതന്നെ ഒരുക്കിവെച്ചവരാവട്ടെ, അവരുടെ അടുക്കലേക്കു സ്വദേശം വെടിഞ്ഞു ചെല്ലുന്നവരെ സ്നേഹിക്കുന്നു. ഹിജ്റ പോയവർക്കു ലഭിക്കുന്ന ധനത്തെ സംബന്ധിച്ച് മനസ്സിൽ യാതൊരാഗ്രഹവും അവർക്ക് തോന്നിയിരുന്നുമില്ല. (മാത്രമല്ല) അവർക്ക് സാമ്പത്തിക ക്ലേശമുണ്ടെങ്കിൽ പോലും (മുഹാജിറുകൾക്ക്) തങ്ങളേക്കാൾ അവർ മുൻഗണന കൽപിക്കുന്നു. മനസ്സിന്റെ പിശുക്കിൽ നിന്നും അത്യാഗ്രഹത്തിൽ നിന്നും വല്ലവരും സുരക്ഷിതരായാൽ അവർ തന്നെയാണ് വിജയികൾ." (ഖു:59:9)', null, '46' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 21, 'paragraph', 'മദീനയിൽ എത്തിയ ശേഷം പ്രവാചകൻ(സ) ആദ്യമായി ചെയ്തത് ഒരു കേന്ദ്രം സ്ഥാപിക്കുക എന്നതായിരുന്നു. അവിടുന്ന് മദീനയിൽ ഒരു പള്ളി സ്ഥാപിച്ചു. അതു തന്നെയായിരുന്നു ഇസ്ലാമിക രാഷ്ട്രത്തിന്റെ കേന്ദ്രവും ഇസ്ലാമിക രാഷ്ട്രത്തിന്റെ സെക്രട്ടറിയേറ്റും. കോടതിയും, അഭയാർത്ഥികളുടെ കേന്ദ്രവും എല്ലാം അതു തന്നെ. കേന്ദ്രം സ്ഥാപിച്ചശേഷം അതിന്റെ ഭദ്രത പ്രവാചകൻ(സ) ഉറപ്പു വരുത്തി. ആഭ്യന്തര സമാധാനവും രാജ്യ രക്ഷയും ഉറപ്പു വരുത്തുന്ന ഒരു ഉടമ്പടി പ്രവാചകർ(സ) ഉണ്ടാക്കി. മുസ്ലിംകളും അമുസ്ലിംകളുമായ മദീനയിലും മദീനക്കു ചുറ്റുമുള്ള എല്ലാ ഗോത്രങ്ങൾക്കിടയിലും സമാധാനപരമായ സഹവർത്തിത്വം നേടിയെടുക്കുക എന്നതായിരുന്നു ഉടമ്പടിയുടെ ലക്ഷ്യം. തുല്യമായ അവകാശങ്ങളുടെയും ബാധ്യതകളുടെയും അടിസ്ഥാനത്തിലുള്ള ആ ഉടമ്പടിയിൽ ജൂത ഗോത്രങ്ങളും അമുസ്ലിം ഗോത്രങ്ങളും ഒപ്പു വെക്കാൻ ഔൽസുക്യം കാണിച്ചു. ഭരണാധികാരി ഭരണീയർക്കു കൊടുത്ത എഴുതപ്പെട്ട ഭരണഘടന എന്ന നിലക്ക് രാഷ്ട്ര തന്ത്രജ്ഞന്മാർ ഇതിന് പ്രാധാന്യം കൽപിക്കുന്നു. വില്യം മൂർ എഴുതുന്നു: "ആ ഉടമ്പടി അദ്ദേഹത്തിൽ ഉൾക്കൊണ്ട മഹത്വം വ്യക്തമാക്കുന്നു. അദ്ദേഹത്തിന്റെ കാലഘട്ടത്തിലെ മാത്രമല്ല, എല്ലാ യുഗങ്ങളിലെയും ഒരു മഹാത്മാവായിരുന്നു അദ്ദേഹം." പിന്നീട് നജ്റാനിലെ ക്രിസ്ത്യാനികളും പ്രവാചകനുമായി ഉടമ്പടിയിലേർപ്പെട്ടു.', null, '47' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 22, 'paragraph', 'മദീനയിൽ രൂപംകൊണ്ടത് പ്രവാചകന്റെ നേതൃത്വത്തിലുള്ള ഒരു ആദർശ രാഷ്ട്രമാണ്. ദൈവേതരങ്ങളായ എല്ലാ അടിമച്ചങ്ങലകളിൽ നിന്നും മനുഷ്യനെ മോചിപ്പിച്ച് ഇസ്ലാം വിഭാവനം ചെയ്യുന്ന സാമൂഹ്യ നീതി കൈവരുത്തുക എന്നതാണ് ആ രാഷ്ട്രത്തിന്റെ ലക്ഷ്യം. ഖുർആൻ മനുഷ്യ ജീവിതത്തിന് മത രംഗത്തെന്നപോലെ രാഷ്ട്രീയ രംഗത്തും മാർഗ്ഗ ദർശനം നൽകുന്നുണ്ട്. ഖുർആന്റെ തത്വങ്ങളിലധിഷ്ഠിതമായിരുന്നു പുതിയ ഭരണകൂടം. യഥാർത്ഥത്തിൽ പരമാധികാരിയും നിയമ നിർമ്മാതാവും ദൈവമാണെന്നും അവന്റെ നിയമങ്ങൾ അനുസരിച്ചു ജീവിക്കാൻ എല്ലാവരും ബാധ്യസ്ഥരാണെന്നും പ്രവാചകൻ(സ) പഠിപ്പിച്ചു. ഖുർആനിക നിയമത്തിനു മുമ്പിൽ പ്രവാചകർ(സ)യടക്കം എല്ലാവരും സമന്മാരാണ്. വർഗ്ഗ വർണ്ണ വ്യത്യാസങ്ങളൊന്നും ഇസ്ലാമിക നിയമം അംഗീകരിക്കുന്നില്ല. സാധാരണക്കാർക്കും ഭരണത്തെ വിമർശിക്കാം. കൂടിയാലോചിച്ചാണ് പ്രവാചകൻ(സ) ഭരണം നടത്തിയത്. അങ്ങനെ ചെയ്യണമെന്ന് ഖുർആനിന്റെ നിർദ്ദേശമുണ്ട്. സിവിൽ, ക്രിമിനൽ നിയമങ്ങളും ഖുർആൻ നൽകി. ഇസ്ലാമിക വീക്ഷണത്തിൽ സ്വത്ത് സമൂഹത്തിൽ ചുറ്റിത്തിരിഞ്ഞു കൊണ്ടിരിക്കണം. അതുകൊണ്ട് ''സകാത്ത്'' എന്ന പേരിൽ പണമായുള്ള സ്വത്തിന്റെ രണ്ടര ശതമാനവും, കാർഷിക വരുമാനത്തിന്റെ പത്ത് ശതമാനവും ദരിദ്ര വിഭാഗങ്ങളിൽ മാത്രം ഓരോ വർഷവും വിതരണം ചെയ്യപ്പെട്ടു. അതിനെ ദരിദ്രരുടെ അവകാശം എന്നാണ് ഖുർആൻ വിശേഷിപ്പിച്ചത്. അതുപോലെ തൊഴിൽരഹിതർക്കും ദരിദ്രർക്കും പൊതു ഖജനാവിൽ അവകാശമുണ്ടെന്നും അവരുടെ സംരക്ഷണം ഗവൺമെന്റിന്റെ ബാധ്യതയാണെന്നും ഭരണകൂടം അംഗീകരിച്ചു.', null, '47' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 23, 'paragraph', 'കുറഞ്ഞ കാലത്തെ ഇസ്ലാമിക ഭരണം കൊണ്ടു തന്നെ ''സകാത്ത്'' (നിർബന്ധ ദാനം) വാങ്ങാൻ ആളുകളില്ലാത്ത അവസ്ഥ ഇസ്ലാമിക ലോകത്ത് സംജാതമായി. മുതലാളിത്തത്തിന്റെ അടിസ്ഥാന ഘടകമായ പലിശയെ ഇസ്ലാം നിരോധിച്ചു. പുതുതായി മുസ്ലിംകളാകുന്നവരുടെ ജീവിതം ക്രമപ്പെടുത്തുന്നതിൽ പ്രവാചകൻ ശ്രദ്ധിച്ചു. ഇസ്ലാമിന്റെ അടിസ്ഥാന കാര്യങ്ങളെക്കുറിച്ച് പ്രവാചകൻ(സ) ഇങ്ങനെ പറഞ്ഞു: "ഇസ്ലാമാകുന്ന സൗധത്തെ അടിയുറപ്പിച്ചിരിക്കുന്നത് അഞ്ച് തൂണിന്മേലാണ്; ഒന്ന്: അല്ലാഹു അല്ലാതെ ഒരു ദൈവമില്ലെന്നും മുഹമ്മദ് നബി(സ) അവന്റെ ദൂതനാണെന്നും സാക്ഷ്യം വഹിക്കുക. ദൈവത്തിന്റെ അധികാരാവകാശങ്ങൾ ആർക്കും നൽകാൻ പാടില്ലെന്നർത്ഥം. ഖുർആൻ പറയുന്നു: (മനുഷ്യരോട്) പറയുക: (ആരുടെ തൃപ്തി ലക്ഷ്യം വെച്ചുകൊണ്ട് ഞങ്ങൾ ജീവിക്കുന്നുവോ) അവൻ ഏകനാണ്. (സർവ്വ ചരാചരങ്ങൾക്കും) അഭയം നൽകുന്നവനും, ആരുടെയും ആശ്രയം ആവശ്യമില്ലാത്തവനുമായി നില കൊള്ളുന്നവൻ അല്ലാഹു മാത്രമാകുന്നു. അവന് സന്താനം ജനിച്ചിട്ടില്ല. അവൻ ആരുടെയും സന്താനവുമല്ല. (ചുരുക്കത്തിൽ) അവനു തുല്യമായി ആരും തന്നെയില്ല." (ഖു: 112:1-4)', null, '48' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 24, 'paragraph', 'മുഹമ്മദ് നബി(സ) ദൈവദൂതനും ദാസനുമാണെന്ന് സാക്ഷ്യം വഹിക്കുക എന്നതുകൊണ്ട് ഉദ്ദേശ്യം മുഹമ്മദ് നബി(സ) കാണിച്ചുതന്ന രീതിയിൽ ജീവിക്കുക എന്നതാണ്. പ്രവാചകൻ(സ) പറഞ്ഞ കാര്യങ്ങളിൽ വിശ്വസിക്കുകയും വേണം. ലോകത്തിനൊരു അന്ത്യമുണ്ടെന്നും അതിനുശേഷം ഈലോക ജീവിത്തെക്കുറിച്ച് ദൈവം കണക്കു ചോദിക്കുമെന്നും ദൈവത്തെ അനുസരിച്ചവർക്ക് സ്വർഗ്ഗവും, ധിക്കരിച്ചവർക്ക് കഠിനമായ നരകവും ലഭിക്കുമെന്നും നബി(സ) പറഞ്ഞത് വിശ്വസിക്കുകയും വേണം. രണ്ട്: അഞ്ചു പ്രാവശ്യം നിസ്കരിക്കുക. മൂന്ന്: നിർബന്ധ ദാനം. നാല്: റമദാൻ മാസം പകൽ മുഴുവൻ വ്രതമനുഷ്ഠിക്കുക. അഞ്ച്: കഴിവുള്ളവർ മക്കയിൽ പോയി ഹജ്ജ് നിർവ്വഹിക്കുക. മുഹമ്മദ് നബി(സ) താൻ ഒരു മനുഷ്യൻ മാത്രമാണെന്നും പ്രവാചകനും മനഷ്യനുമായ യേശുവിന് ദൈവികത്വം കൽപിച്ചപോലെ തനിക്കാരും ദൈവികത്വം കൽപ്പിക്കരുതെന്നും തറപ്പിച്ചു പറഞ്ഞിരുന്നു.', null, '48' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 25, 'paragraph', 'പുതുതായി രൂപം കൊണ്ട ഇസ്ലാമിക സമൂഹത്തെയും രാഷ്ട്രത്തെയും നിലനിൽക്കാൻ മക്കയിലെ പ്രധാനികൾ അനുവദിക്കുകയില്ല എന്ന് വ്യക്തമായിരുന്നു. മുഹമ്മദ് നബി(സ)ക്ക് അഭയം നൽകിയ യസ്രിബ് (മദീന) നിവാസികളോട് അവർക്ക് കടുത്ത അമർഷമുണ്ടായിരുന്നു. അവർ ഇടക്കിടെ മദീന നിവാസികളെ ശല്യം ചെയ്തു കൊണ്ടിരുന്നു. ആയിടെ സിറിയയിൽ നിന്നും മടങ്ങുന്ന ഒരു അറേബ്യൻ കച്ചവട സംഘത്തെ മുഹമ്മദ്(സ)യും കൂട്ടുകാരും ആക്രമിക്കാൻ പരിപാടിയിട്ടിട്ടുണ്ട് എന്നൊരു വാർത്ത മക്കയിൽ വ്യാപിച്ചു. അങ്ങിനെയുണ്ടെങ്കിൽ അത് തടയാനും മദീനക്കാരെ ഒരു പാഠം പഠിപ്പിക്കാനും മക്കാനിവാസികൾ ഒരുങ്ങി. അവർ 1000 ആയുധധാരികളെ ഒരുക്കി, വമ്പിച്ച സന്നാഹങ്ങളോടെ മദീനയുടെ ഭാഗത്തേക്ക് തിരിച്ചു. ആ വാർത്തയറിഞ്ഞ പ്രവാചകൻ(സ) മദീനയിൽ വെച്ചുള്ള ഒരു സംഘട്ടനം ഒഴിവാക്കാൻ മദീനയുടെ പുറത്തേക്കു വന്നു. അവിടത്തോടൊപ്പം 313 പേരേ ഉണ്ടായിരുന്നുള്ളൂ. സായുധരല്ലാത്ത അവർക്ക് രണ്ട് കുതിരകളും എഴുപത് ഒട്ടകങ്ങളും മാത്രമാണുണ്ടായിരുന്നത്. സാധാരണ ഗതിയിൽ മുസ്ലിംകൾ പരാജയപ്പെടുമെന്ന് തീർച്ചയായിരുന്നു. എന്നാൽ, എല്ലാം അല്ലാഹുവിൽ അർപ്പിച്ച് രണാങ്കണത്തിലിറങ്ങിയ മുസ്ലിംകൾ വിജയിച്ചു. തടവുകാരായി പിടിച്ചവരെ മോചനമൂല്യം വാങ്ങി വിട്ടയച്ചു. മോചനമൂല്യം നൽകാൻ കഴിയാത്തവർക്ക് മദീനയിലെ 10 പേരെ എഴുത്തും വായനയും പഠിപ്പിക്കുക എന്ന മോചന മൂല്യം നിശ്ചയിച്ചു. അല്ലാഹുവിന്റെ സഹായം കൊണ്ടാണ് ബദ്റിൽ ജയിച്ചതെന്ന് മുസ്ലിംകൾ വിശ്വസിച്ചു. സത്യവും അസത്യവും തമ്മിലുള്ള സമരത്തിൽ അംഗസംഖ്യ ഒരു പ്രശ്നമല്ല എന്ന് ബദ്റിലെ വിജയം തെളിയിച്ചു. ബദ്റിനു ശേഷവും മക്കയിലെ പ്രധാനികൾ മദീനയെ ആക്രമിച്ചു കീഴടക്കാൻ പലതവണ ശ്രമിച്ചെങ്കിലും അവർ വിജയിച്ചില്ല.', null, '48' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 26, 'paragraph', 'മദീനയിലെത്തിയതിന്റെ ആറാം വർഷം തീർത്ഥാടനത്തിനായി നബി(സ) മക്കയിലെ കഅ്ബയിലേക്കു പുറപ്പെട്ടു. യുദ്ധം നിഷിദ്ധമാണെന്ന് അറബികൾ വിശ്വസിക്കുന്ന മാസത്തിലായിരുന്നു ആ സംഭവം. യുദ്ധം ചെയ്യാനുള്ള പരിപാടിയില്ല എന്നറിഞ്ഞിട്ടും മക്കയിലേക്കു പ്രവേശിക്കാൻ നബി(സ)യെ ശത്രുക്കൾ സമ്മതിച്ചില്ല. ദൂതന്മാർ പരസ്പരം ബന്ധപ്പെട്ടതിന്റെ ഫലമായി അവസാനം ഒരു സന്ധിയുണ്ടാക്കി. സന്ധി പ്രഥമദൃഷ്ട്യാ മുസ്ലിംകൾക്ക് അനുകൂലമല്ലായിരുന്നു. നബി(സ) വിട്ടുവീഴ്ച ചെയ്യുകയാണ് ചെയ്തത്. ആ വർഷം മുസ്ലിംകൾ കഅ്ബ സന്ദർശിക്കാതെ മടങ്ങണമെന്നും, അടുത്ത വർഷം സന്ദർശിക്കാമെന്നും, മക്കക്കാരിൽ ആരെങ്കിലും നേതാക്കന്മാരുടെ സമ്മതമില്ലാതെ മദീനയിൽ വന്നാൽ അവരെ തിരിച്ചയക്കണമെന്നും, മദീനയിൽ നിന്നും ആരെങ്കിലും മക്കയിൽ വന്നാൽ തിരിച്ചയക്കില്ല എന്നുമായിരുന്നു ഉടമ്പടിയിലെ പ്രധാന നിബന്ധനകൾ. അടുത്ത പത്തു വർഷത്തേക്ക് പരസ്പരം യുദ്ധം ചെയ്യുകയില്ലെന്നും ''ഹുദൈബിയ സന്ധി'' എന്ന പേരിലറിയപ്പെടുന്ന ഈ ഉടമ്പടിയിലുണ്ടായിരുന്നു.', null, '48' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 27, 'paragraph', '''ഹുദൈബിയ സന്ധി''ക്കു ശേഷം ലഭിച്ച സമാധാനാന്തരീക്ഷത്തിൽ നബി(സ) പേർഷ്യ, റോം, ഈജിപ്ത്, സിറിയ, യമൻ തുടങ്ങിയ രാജ്യങ്ങളിലെ രാജാക്കന്മാർക്ക് ഇസ്‌ലാമിലേക്ക് ക്ഷണിച്ചു കൊണ്ട് കത്തുകളയച്ചു.', null, '49' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 28, 'paragraph', 'ഹിജ്‌റ എട്ടാം വർഷം മക്കയിലെ ഖുറൈശികൾ ''ഹുദൈബിയ'' ഉടമ്പടി ലംഘിച്ചു. നബി(സ)യുടെ കൂട്ടത്തിലുണ്ടായിരുന്ന ''ബനൂ ഖുസ്സ'' ഗോത്രക്കാരെ ആക്രമിച്ചു. അപ്പോൾ നബി(സ) മക്കയിലെ പ്രധാനികളോട് ''ബനൂ ഖുസ്സ'' ഗോത്രത്തിന് നഷ്ടപരിഹാരം നൽകാനോ അല്ലെങ്കിൽ ''ഹുദൈബിയ'' ഉടമ്പടി റദ്ദു ചെയ്യാനോ ആവശ്യപ്പെട്ടു. നബി(സ) പതിനായിരം അനുയായികളുമായി മക്കയിലേക്ക് തിരിച്ചു. അപ്പോഴും മുസ്‌ലിംകൾ ഒരു ശക്തിയല്ല എന്ന ധാരണയാണ് മക്കക്കാർക്ക് ഉണ്ടായിരുന്നത്. നബി(സ)യും അനുയായികളും മക്കക്കു സമീപം താവളമടിച്ച വേളയിൽ അവരെ രഹസ്യമായി നിരീക്ഷിക്കാൻ ചെന്ന മക്കയിലെ നേതാവായ അബൂസുഫ്‌യാൻ മുസ്‌ലിം യോദ്ധാക്കളുടെ കൈകളിലകപ്പെട്ടു. അവരദ്ദേഹത്തോട് മാന്യമായി പെരുമാറുകയും അദ്ദേഹത്തെ വിട്ടയക്കുകയും ചെയ്തു. നബി(സ)യുടെ സ്വഭാവ മഹിമ കണ്ട് ആകൃഷ്ടനായ അബൂസുഫ്‌യാൻ(റ) ഇസ്‌ലാം സ്വീകരിച്ചു.', null, '49' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 29, 'paragraph', 'നബി(സ)യും അനുചരന്മാരും മക്കയിൽ പ്രവേശിച്ചു. അവരെ എതിർക്കാൻ ആരും വന്നില്ല. നബി(സ)യെയും അനുചരന്മാരെയും ക്രൂരമായി മർദ്ദിക്കുകയും ജന്മനാട്ടിൽ നിന്നും പുറത്താക്കുകയും ചെയ്ത ആ പട്ടണ വാസികൾ, നബി(സ) എന്തു ചെയ്യുമെന്നറിയാതെ അവിടത്തെ മുന്നിൽ ആകാംക്ഷയോടും, ഭീതിയോടും കൂടി നിന്നു. അപ്പോൾ അവരെ അഭിസംബോധന ചെയ്തു കൊണ്ട് നബി(സ) പറഞ്ഞു: "യൂസുഫ് നബി(അ) തന്റെ സഹോദരങ്ങളോട് പറഞ്ഞതുപോലെ ഇന്ന് ഞാനും ഇതാ നിങ്ങളോട് പറയുന്നു. ഇന്ന് നിങ്ങളുടെ പേരിൽ കുറ്റമൊന്നുമില്ല. നിങ്ങൾ സ്വതന്ത്രരാണ്."', null, '49' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 30, 'paragraph', 'മക്കാ വിജയത്തോടെ പ്രവാചകൻ(സ) അറേബ്യയിലെ അനിഷേധ്യ ഭരണാധികാരിയായി. മക്കയിലെ ദേവാലയമായ വിശുദ്ധ കഅ്ബ സന്ദർശിച്ച ശേഷം അവിടുന്ന് തനിക്കഭയം തന്ന മദീനയിലേക്കു തന്നെ തിരിച്ചുപോയി.', null, '49' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 31, 'paragraph', 'ഹിജ്‌റ പത്താം വർഷം പ്രവാചകൻ(സ) വീണ്ടും മക്കയിലേക്ക് തീർത്ഥാടത്തിനുപോയി. ആ ഹജ്ജ് വേളയിൽ ഒരു ലക്ഷത്തോളം വരുന്ന അനുയായികളെ അഭിസംബോധന ചെയ്തുകൊണ്ട് അവിടുന്ന് പറഞ്ഞ വാക്കുകൾ ശ്രദ്ധേയങ്ങളാണ്:', null, '49' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 32, 'paragraph', '"ജനങ്ങളേ; എന്റെ വാക്കുകൾ ശ്രദ്ധിച്ചു കേൾക്കുക. ഇക്കൊല്ലത്തിനു ശേഷം ഈ സ്ഥലത്തുവെച്ച് നിങ്ങളെ കാണാൻ സാധിക്കുമോ ഇല്ലയോ എന്നെനിക്കറിയില്ല. ജനങ്ങളേ; നിങ്ങളുടെ ഈ നാടിനും ഈ മാസത്തിനും ഈ ദിനത്തിനും എപ്രകാരം നിങ്ങൾ ആദരവ് കൽപിക്കുന്നുവോ അപ്രകാരം നിങ്ങളുടെ നാഥനുമായി കണ്ടുമുട്ടുന്നതുവരെ അഭിമാനവും, ധനവും പരസ്പരം കയ്യേറുന്നത് നിങ്ങൾക്കിതാ നിഷിദ്ധമാക്കിയിരിക്കുന്നു. ഓർക്കുക, നിങ്ങൾ പിഴച്ച് പരസ്പരം കഴുത്തു വെട്ടാൻ മുതിരരുത്. നിങ്ങളുടെ നാഥനുമായി നിങ്ങൾ കണ്ടുമുട്ടും. അപ്പോൾ നിങ്ങളുടെ പ്രവർത്തനങ്ങളെക്കുറിച്ച് അവൻ നിങ്ങളെ ചോദ്യം ചെയ്യും. ജാഹിലിയ്യാ കാലത്ത് നടന്ന ജീവനാശങ്ങൾക്കുള്ള എല്ലാ പ്രതികാര നടപടികളെയും ഞാനിതാ ദുർബ്ബലപ്പെടുത്തിയിരിക്കുന്നു. ജനങ്ങളേ; നിങ്ങളുടെ ദൈവം ഏകനാണ്. നിങ്ങളെല്ലാവരുടെയും പിതാവും ഒന്നു തന്നെ. നിങ്ങളെല്ലാം ആദമിൽ നിന്നു ജനിച്ചു. ആദം മണ്ണിൽ നിന്നും. നിങ്ങളിൽ വെച്ച് ജീവിതത്തിൽ ഏറ്റവും കൂടുതൽ സൂക്ഷ്മതയുള്ളവനാരോ, അവനത്രെ അല്ലാഹുവിങ്കൽ ഏറ്റവും മാന്യൻ. അറബിക്ക് അനറബിയേക്കാളോ, അനറബിക്ക് അറബിയേക്കാളോ യാതൊരു ശ്രേഷ്ഠതയുമില്ല. ശ്രേഷ്ഠതക്കുള്ള അടിസ്ഥാനം ജീവിതത്തിലുള്ള സൂക്ഷ്മതയത്രെ! ഖുർആൻ അടിസ്ഥാനമാക്കി ജീവിക്കുന്ന കാലമത്രയും നിങ്ങൾ വഴിപിഴക്കുകയില്ല. അല്ലാഹുവിന്റെ ഗ്രന്ഥമത്രെ അത്. ജനങ്ങളേ, സത്യവിശ്വാസികൾ പരസ്പരം സഹോദരങ്ങളാണ്. തന്റെ സഹോദരന്റെ സംതൃപ്തിയോടെയല്ലാതെ ഒരാളും അവന്റെ ധനം കരസ്ഥമാക്കാൻ പാടില്ല. ജാഹിലിയ്യാ കാലത്തെ പലിശ ഇടപാടുകളെല്ലാം ഞാനിതാ ദുർബ്ബലപ്പെടുത്തിയിരിക്കുന്നു. ആ ഇനത്തിൽ ഒന്നാമതായി ഞാൻ ദുർബ്ബലപ്പെടുത്തുന്നത് എന്റെ പിതൃവ്യൻ അബ്ബാസിന് കിട്ടാനുള്ള പലിശയാണ്. ജനങ്ങളേ; നിങ്ങളോട് നിങ്ങളുടെ പത്നിമാർക്കുള്ളപോലെ തന്നെ, നിങ്ങൾക്ക് അവരോടും ചില ബാധ്യതകൾ ഉണ്ട്. നിങ്ങൾ സ്ത്രീകളോട് നല്ല നിലയിൽ സഹവസിക്കുക. അല്ലാഹുവിന്റെ അമാനത്ത് എന്ന നിലക്കാണ് അവരെ നിങ്ങൾ ഏറ്റെടുത്തിരിക്കുന്നത്. നിങ്ങളുടെ ഭൃത്യരെ ശ്രദ്ധിക്കുക. നിങ്ങൾ ഭക്ഷിക്കുന്നത് തന്നെ അവർക്കും ഭക്ഷിക്കാൻ നൽകുക. നിങ്ങൾ ധരിക്കുന്ന വസ്ത്രം തന്നെ അവർക്കും ധരിക്കാൻ കൊടുക്കുക. ജനങ്ങളേ; എനിക്കുശേഷം ഒരു നബിയും വരാനില്ല. അതുകൊണ്ട് ശ്രദ്ധിച്ചു കേൾക്കുക; നിങ്ങളുടെ നാഥന്റെ പരിശുദ്ധ ഹറമിൽ വന്ന് ഹജ്ജ് ചെയ്യുക. നിങ്ങളുടെ ഭരണാധികാരികളെ അനുസരിക്കുക. അപ്പോൾ നിങ്ങളുടെ നാഥന്റെ സ്വർഗ്ഗത്തിൽ പ്രവേശിക്കാം." പ്രസംഗത്തിന്റെ അവസാനത്തിൽ ആ വമ്പിച്ച ജനസമൂഹത്തെ അഭിമുഖീകരിച്ചു കൊണ്ട് അവിടുന്ന് ചോദിച്ചു: "അല്ലാഹുവിന്റെ സന്നിധിയിൽ വെച്ച് എന്നെക്കുറിച്ച് നിങ്ങൾ ചോദിക്കപ്പെടും, അപ്പോൾ എന്താണ് നിങ്ങൾ പറയുക?" ജനസമൂഹം ഒരേ സ്വരത്തിൽ മറുപടി പറഞ്ഞു: അങ്ങ് അല്ലാഹുവിന്റെ സന്ദേശം ഞങ്ങളെ അറിയിക്കുകയും, അങ്ങയുടെ എല്ലാ ബാധ്യതകളും നിറവേറ്റുകയും ചെയ്തിട്ടുണ്ട് എന്ന് ഞങ്ങൾ മറുപടി നൽകും. അന്നേരം ആകാശത്തേക്ക് കണ്ണും കയ്യും ഉയർത്തിക്കൊണ്ട് നബി(സ) "അല്ലാഹുവേ, നീ സാക്ഷ്യം വഹിക്കേണമേ" എന്ന് മൂന്നു പ്രാവശ്യം പ്രാർത്ഥിച്ചു കൊണ്ട് പ്രസംഗം അവസാനിപ്പിച്ചു.', null, '49' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 33, 'paragraph', 'ഈ സമയത്ത് അല്ലാഹുവിൽ നിന്നും മാനവ കുലത്തിനുള്ള അനുഗ്രഹമായ ഇസ്ലാമിനെ പൂർത്തീകരിച്ചതായി അറിയിക്കുന്ന ദൈവിക സന്ദേശം അവതരിച്ചു: "ഈ ദിവസം നിങ്ങളുടെ മതത്തെ നിങ്ങൾക്ക് ഞാൻ പൂർത്തീകരിച്ചു തരികയും എന്റെ അനുഗ്രഹത്തെ നിങ്ങളിൽ പൂർണ്ണമാക്കുകയും ചെയ്തിരിക്കുന്നു. ഇസ്ലാമിനെ നിങ്ങളുടെ മതമായി ഞാൻ തൃപ്തിപ്പെടുകയും ചെയ്തു." (ഖു:15:4)', null, '50' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 34, 'paragraph', 'ഇതോടു കൂടി പ്രവാചകത്വം പൂർത്തിയായി. മാർഗ്ഗദർശക ഗ്രന്ഥമായി ഖുർആൻ ഇന്നും നിലനിൽക്കുന്നു. അത് അല്ലാഹു തന്നെ സംരക്ഷിക്കുമെന്ന് ഖുർആനിൽ പറഞ്ഞിട്ടുണ്ട്. ഇനിയൊരു പ്രവാചകനോ, വേദ ഗ്രന്ഥമോ വരാനില്ല. ലോകാവസാനം വരെയുള്ള മാർഗ്ഗദർശക ഗ്രന്ഥമാണ് ഖുർആൻ.', null, '50' from articles where volume_id=1 and section_no=4;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 35, 'paragraph', 'വിടവാങ്ങൽ പ്രസംഗത്തിനു ശേഷം മൂന്നു മാസമേ നബി(സ) ജീവിച്ചുള്ളൂ. ഹി: 12-ാം വർഷം റബീഉൽ അവ്വലിൽ പ്രവാചകർ(സ) വഫാത്തായി. അവിടത്തെ മാർഗ്ഗദർശനം അനുസരിച്ച് ജീവിക്കാനും, അങ്ങനെ ജീവിതവിജയം നേടുവാനും പരലോകത്ത് അവിടത്തോടൊപ്പം ജീവിക്കാനും അല്ലാഹു നമ്മെ അനുഗ്രഹിക്കട്ടെ. ആമീൻ.', null, '50' from articles where volume_id=1 and section_no=4;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 5, 'ഹദീസുകൾ (നബി വചനങ്ങൾ)', '51', '60');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', 'പ്രപഞ്ചത്തിലെവിടെ നോക്കിയാലും ബുദ്ധിയുടെയും യുക്തിയുടെയും സാന്നിദ്ധ്യം നമുക്ക് ദർശിക്കുവാൻ കഴിയും. ആറ്റത്തിലെ ഇലക്ട്രോൺ, പ്രോട്ടോൺ, ന്യൂട്രോൺ എന്നീ ഘടകങ്ങളുടെ പ്രവർത്തനം ശ്രദ്ധിച്ചാലും, നമ്മുടെ ശരീരാവയവങ്ങളുടെ പ്രവർത്തനം നിരീക്ഷിച്ചാലും, ഗ്രഹങ്ങളുടെയും നക്ഷത്രങ്ങളുടെയും സഞ്ചാര പഥങ്ങളെക്കുറിച്ചു ചിന്തിച്ചാലും, പ്രപഞ്ചോൽപത്തിയെക്കുറിച്ചു പഠിച്ചാലും, ഈ പ്രപഞ്ചത്തിനു പിന്നിൽ ബുദ്ധിയും യുക്തിയും നിലനിൽക്കുന്നുവെന്നു ബോധ്യമാകും. പ്രപഞ്ചത്തിനു പിന്നിൽ ബുദ്ധിയും യുക്തിയും പ്രവർത്തിച്ചിട്ടുണ്ടെന്നു ബോധ്യപ്പെടുന്നതോടെ പ്രപഞ്ച സൃഷ്ടാവും സംവിധായകനുമായ ദൈവത്തിൽ (അല്ലാഹുവിൽ) നാം ചെന്നെത്തുന്നു.', null, '51' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'പ്രപഞ്ചത്തിലെവിടെ നോക്കിയാലും ചിന്തയുടെ സാന്നിദ്ധ്യം കാണാം. അതുകൊണ്ട് പ്രപഞ്ചത്തിനു പിന്നിൽ ഒരു ചിന്തകനുണ്ടായേ പറ്റൂ. പ്രപഞ്ചത്തിലെവിടെ നോക്കിയാലും ഒരു ആസൂത്രണം കാണാം. അതുകൊണ്ട് പ്രപഞ്ചത്തിനു പിന്നിൽ ഒരാസൂത്രകനുണ്ടായേ പറ്റൂ. പ്രപഞ്ചത്തിൽ കലയും സൗന്ദര്യവും പ്രകടമാണ്. അതുകൊണ്ട് പ്രപഞ്ചത്തിനു പിന്നിൽ ഒരു കലാകാരനുണ്ടായേ പറ്റൂ. പ്രപഞ്ചം പണ്ടുണ്ടായിരുന്നില്ലെന്ന് ആധുനിക ശാസ്ത്രം സമ്മതിക്കുന്നു. അപ്പോൾ എല്ലാം ഭംഗിയായി ആസൂത്രണം ചെയ്ത് സൃഷ്ടിച്ച ഒരു പടച്ചവൻ ഉണ്ടെന്നു വരുന്നു.', null, '51' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'പ്രപഞ്ചം സൃഷ്ടിച്ച് സംവിധാനിച്ച ദൈവം മനുഷ്യനാവശ്യമായ എല്ലാം ഇവിടെ തയ്യാറാക്കി വെച്ചതായി നാം കാണുന്നു. മനുഷ്യനാവശ്യമായ വായുവും, വെള്ളവും, മാതൃസ്നേഹവും സംവിധാനിച്ച ദൈവം അവനുവേണ്ട മാർഗ്ഗദർശനം നൽകിയില്ല എന്നു ചിന്തിക്കുന്നത് യുക്തി ഭംഗമാണ്. മനുഷ്യൻ ഈ ഭൂമിയിൽ ജീവിതമാരംഭിച്ച ആദ്യ ദിനം മുതൽ ദൈവം അവനുവേണ്ട മാർഗ്ഗദർശനം നൽകിയിട്ടുണ്ട് എന്ന് ഇസ്‌ലാം സിദ്ധാന്തിക്കുന്നു. ആ മാർഗ്ഗ ദർശനത്തിന്റെ അവസാനത്തെ പതിപ്പാണ് ഖുർആൻ. അത് മുഹമ്മദ് നബി(സ)യുടെ കൃതിയല്ല. നമ്മെയും ലോകത്തെയും സൃഷ്ടിച്ചു സംരക്ഷിക്കുന്ന ദൈവം നമുക്ക് നൽകിയ ജീവിത മാർഗ്ഗദർശന ഗ്രന്ഥമാണ്. അത് ദൈവത്തിൽ നിന്നുള്ളതു തന്നെയാണോ? സംശയം സ്വാഭാവികമാണ്. ഖുർആനെ സംബന്ധിച്ച് പഠിക്കുംതോറും അത് ദൈവ വചനമാണെന്ന് ബോധ്യപ്പെടും. വിശുദ്ധ ഖുർആൻ ദൈവം മനുഷ്യന് നൽകിയ ഒരു മാർഗ്ഗദർശക ഗ്രന്ഥമാണ്. അത് മനുഷ്യനാൽ വിരചിതമായ ഒരു ഗ്രന്ഥമല്ല. മുഹമ്മദ് നബി(സ)ക്ക് ഇരുപത്തി മൂന്ന് വർഷങ്ങളിലായി സന്ദർഭത്തിന്റെ ഔചിത്യമനുസരിച്ച് ലഭിച്ച ദൈവിക നിർദ്ദേശങ്ങളുടെ സമാഹാരമാണത്. എന്നുവെച്ച് അതിലെ വാക്യങ്ങളോ വാക്കുകളോ മുഹമ്മദ് നബിയുടേതല്ല. മാനവ കുലത്തിനുള്ള ദൈവിക നിർദ്ദേശങ്ങളാണവ. ഖുർആനിക നിർദ്ദേശങ്ങൾക്കനുസരിച്ച് ജീവിച്ചു കാണിച്ചു തരികയാണ് മുഹമ്മദ് നബി(സ) ചെയ്തത്. ഖുർആനിന്റെ വിശദാംശങ്ങൾ നമുക്ക് ലഭിക്കുന്നത് മുഹമ്മദ് നബി(സ)യുടെ ജീവിതത്തിൽ നിന്നാണ്.', null, '51' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'കർമ്മത്തിന് ഇസ്‌ലാം വളരെയധികം പ്രാധാന്യം കൽപിക്കുന്നു. വെറും വിശ്വാസ കാര്യങ്ങളിലും സൈദ്ധാന്തിക കാര്യങ്ങളിലും പരിമിതമല്ല ഇസ്‌ലാം. നിത്യ ജീവിതത്തിൽ അനുഷ്ടിക്കേണ്ട കാര്യങ്ങൾക്ക് സ്വന്തം ജീവിതത്തിലൂടെ മാതൃക കാണിക്കുകയാണ് പ്രവാചകൻ(സ) ചെയ്തത്. അല്ലാഹു പറയുന്നു: "തീർച്ചയായും ദൈവത്തിന്റെ ദൂതനിൽ നിങ്ങൾക്ക് ഉത്തമമായ മാതൃകയുണ്ട്. അല്ലാഹുവിനെയും അന്ത്യദിനത്തെയും ആഗ്രഹിക്കുകയും കൂടുതലായി സ്മരിക്കുകയും ചെയ്യുന്നവർക്ക്."(ഖു: 33: 21)', null, '51' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'പ്രവാചകൻ(സ) ഉന്നതനാണ്, അദ്ദേഹത്തിന് ഇസ്‌ലാമിക സിദ്ധാന്തങ്ങൾക്കനുസരിച്ച് ജീവിക്കാൻ കഴിയും. ഞങ്ങൾ സാധാരണ മനുഷ്യരാണ്, ഞങ്ങൾക്കങ്ങനെ ജീവിക്കാനാവില്ല എന്ന ചിന്താഗതിയുടെ നിരർത്ഥകതയും ഖുർആൻ വ്യക്തമാക്കിയിട്ടുണ്ട്. "ഒരു മലക്കിനെ നാം ദൈവദൂതനാക്കിയിരുന്നുവെങ്കിൽ ആ മലക്കിനെയും നാം (രൂപത്തിലും സ്വഭാവത്തിലും) ഒരു മനുഷ്യൻ തന്നെയാക്കുമായിരുന്നു." (ഖു: 6:9) "പറയുക; ശാന്തരായി നടക്കുന്ന മലക്കുകളാണ് ഭൂമിയിൽ ഉണ്ടായിരുന്നതെങ്കിൽ തീർച്ചയായും അവർക്ക് ഒരു ദൂതനായി ആകാശത്തു നിന്ന് ഒരു മലക്കിനെ (തന്നെ) നാം ഇറക്കുമായിരുന്നു." (ഖു: 17: 95)', null, '51' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ഇസ്ലാമിക ജീവിതത്തിന്റെ കർമ്മ മാതൃകയായിരുന്നു പ്രവാചക ജീവിതം. ഇസ്ലാം പ്രവർത്തനമാണ്, എന്ന് നബി(സ) കാണിച്ചുതന്നു. നബി(സ)യുടെ ഭാര്യ ആഇശ(റ)യോട് നബി(സ)യുടെ സ്വഭാവത്തെക്കുറിച്ച് ചോദിച്ചപ്പോൾ ലഭിച്ച മറുപടി ''അത് ഖുർആനാണ്'' എന്നായിരുന്നു. ഖുർആൻ പ്രയോഗവൽക്കരിച്ചു കാണിക്കുകയാണ് നബി(സ) ചെയ്തത്.', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'paragraph', 'നബി(സ)യുടെ ജീവിതം സൂക്ഷ്മമായി വീക്ഷിക്കാനും പകർത്താനും അല്ലാഹു മനുഷ്യരെ ആഹ്വാനം ചെയ്യുന്നു. അല്ലാഹു പറഞ്ഞു: “നിങ്ങൾ അല്ലാഹുവിനെയും റസൂലിനെയും അനുസരിക്കുവിൻ, നിങ്ങൾ കരുണ ചെയ്യപ്പെട്ടേക്കാം.” (ഖു: 3:132) റസൂലിനെ അനുസരിക്കുന്നത് അല്ലാഹുവിനെ അനുസരിക്കൽ തന്നെയാണെന്ന് അല്ലാഹു അറിയിക്കുന്നു: “ആർ റസൂലിനെ അനുസരിക്കുന്നുവോ അവൻ അല്ലാഹുവിനെ അനുസരിച്ചിരിക്കുന്നു.” (ഖു:4:80) “(നബിയെ) പറയുക; നിങ്ങൾ അല്ലാഹുവിനെ സ്നേഹിക്കുന്നുവെങ്കിൽ എന്നെ പിൻപറ്റുവിൻ, അല്ലാഹു നിങ്ങളെ സ്നേഹിക്കുന്നതാണ്. നിങ്ങൾക്കു നിങ്ങളുടെ പാപങ്ങൾ അവൻ പൊറുത്തു തരികയും ചെയ്യും.” (ഖു:3:31)', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'അല്ലാഹു പറയുന്നു: “ഒരു സത്യവിശ്വാസിക്കാകട്ടെ, സത്യവിശ്വാസിനിക്കാകട്ടെ അല്ലാഹുവും അവന്റെ റസൂലും ഒരുകാര്യം തീരുമാനിച്ചാൽ അവർക്ക് തങ്ങളുടെ കാര്യത്തെപ്പറ്റി തെരഞ്ഞെടുക്കാൻ സ്വാതന്ത്ര്യം ഉണ്ടായിരിക്കാൻ പാടില്ല. അല്ലാഹുവിനോടും അവന്റെ റസൂലിനോടും ആർ അനുസരണക്കേടു കാണിക്കുന്നുവോ അവൻ തീർച്ചയായും സ്പഷ്ടമായി വഴി പിഴച്ചുപോയിരിക്കുന്നു.” (33:36) അല്ലാഹു പറയുന്നു: “ഇല്ല, - അങ്ങയുടെ റബ്ബിനെ തന്നെ സത്യം - അവരുടെ ഇടയിൽ ഭിന്നിപ്പുണ്ടാക്കുന്ന വിഷയത്തിൽ അങ്ങയെ അവർ വിധി കർത്താവാക്കുകയും, പിന്നീട് അവരുടെ മനസ്സുകളിൽ അങ്ങ് തീരുമാനിച്ചതിനെപ്പറ്റി യാതൊരു വിഷമവും അവർക്കനുഭവപ്പെടാതിരിക്കുകയും പൂർണ്ണമായി അനുസരണ കാണിക്കുകയും ചെയ്യുന്നതു വരെ അവർ സത്യവിശ്വാസികളാവുകയില്ല.” (3:65) “അങ്ങിലേക്ക് പ്രമാണത്തെ (ഖുർആൻ) നാം അവതരിപ്പിച്ചു തന്നിരിക്കുന്നത് ജനങ്ങൾക്ക് ഇറക്കപ്പെട്ടിട്ടുള്ളത് അവർക്കു അങ്ങ് വിവരിച്ചു കൊടുക്കാൻ വേണ്ടിയാകുന്നു.” (16:44)', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'അല്ലാഹു വീണ്ടും പറയുന്നു: “അവിടുന്ന് (റസൂൽ) അവരോട് സദാചാരം കൽപിക്കുകയും ദുരാചാരത്തിൽ നിന്ന് അവരെ നിരോധിക്കുകയും ചെയ്യും. നല്ല വസ്തുക്കൾ അവർക്ക് അനുവദനീയമാക്കുകയും ചീത്തയായവയെ അവർക്ക് നിഷിദ്ധമാക്കുകയും ചെയ്യുന്നു. അവരുടെ ഭാരങ്ങളും അവരുടെ മേലുണ്ടായിരുന്ന ചങ്ങലകളും ഇറക്കി വെക്കുകയും ചെയ്യുന്നു.” (7:157) “റസൂൽ നിങ്ങൾക്ക് ഏതൊന്നു കൊണ്ടുതന്നുവോ അത് നിങ്ങൾ സ്വീകരിച്ചു കൊള്ളുവിൻ, അവിടുന്ന് നിങ്ങളോടു ഏതൊന്ന് നിരോധിച്ചുവോ (അതിൽനിന്ന്) നിങ്ങൾ വിരമിക്കുകയും ചെയ്യുവിൻ.” (59:7)', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'paragraph', '“അവിടത്തെ (റസൂലിന്റെ) കൽപനക്ക് എതിര് പ്രവർത്തിക്കുന്നവർ തങ്ങൾക്കു വല്ല കുഴപ്പവും ബാധിക്കുകയോ, അല്ലെങ്കിൽ വേദനയേറിയ വല്ല ശിക്ഷയും പിടിപെടുകയോ ചെയ്യുന്നത് സൂക്ഷിച്ചു കൊള്ളട്ടെ.” (24:63)', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', 'നബി വചനങ്ങൾ പ്രചരിപ്പിക്കാൻ പ്രോത്സാഹനം നൽകുന്ന ചില വചനങ്ങൾ നോക്കൂ:', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'നബി(സ) പറഞ്ഞു: “എന്റെ വാക്കു കേൾക്കുകയും എന്നിട്ട് അതു കേട്ടപോലെ (മറ്റുള്ളവർക്ക്) എത്തിച്ചു കൊടുക്കുകയും ചെയ്ത മനുഷ്യന് അല്ലാഹു കാരുണ്യം നൽകട്ടെ. എത്തിച്ചു കൊടുക്കപ്പെടുന്ന എത്രയോ ആളുകളിൽ (നേരിൽ) കേട്ടവരേക്കാൾ പഠിച്ചു മനസ്സിലാക്കുന്നവരുണ്ടായിരിക്കും.” (ദ,തു)', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'paragraph', 'വിടവാങ്ങൽ ഹജ്ജിൽ വെച്ച് നബി(സ) ഇങ്ങനെ പറഞ്ഞു: “നിങ്ങളുടെ ഈ ഭൂമിയിൽ വെച്ച് താൻ ആരാധിക്കപ്പെടുന്നതിനെക്കുറിച്ച് പിശാച് നിരാശനായിരിക്കുന്നു. പക്ഷേ, നിങ്ങൾ നിങ്ങളുടെ പ്രവൃത്തികളിൽ നിസ്സാരമായി ഗണിക്കുന്ന കാര്യത്തിൽ അവനെ അനുസരിക്കുന്നതിൽ അവൻ തൃപ്തിപ്പെട്ടിരിക്കുന്നു. അതിനാൽ നിങ്ങൾ ജാഗ്രത പുലർത്തുവിൻ, നിശ്ചയം നിങ്ങൾ മുറുകെ പിടിച്ചാൽ ഒരിക്കലും നിങ്ങൾ വഴിപിഴച്ചു പോകാത്ത കാര്യം ഞാൻ നിങ്ങളിൽ വിട്ടേച്ചു പോകുന്നു. അല്ലാഹുവിന്റെ കിതാബും, അവന്റെ ദൂതന്റെ സുന്നത്തും.” (ഹാകിം)', null, '52' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'ഖുർആൻ കഴിഞ്ഞാൽ ഇസ്‌ലാമിക നിയമത്തിന്റെ സ്രോതസ്സ് നബിചര്യയാണ്. മുആദുബ്നു ജബലി(റ)നെ യമനിലേക്കയച്ചപ്പോൾ അദ്ദേഹത്തിന് വല്ല തീരുമാനവും എടുക്കേണ്ട പ്രശ്നം നേരിട്ടാൽ എങ്ങനെ വിധിക്കും എന്നു നബി(സ) ചോദിച്ചു. "അല്ലാഹുവിന്റെ കിതാബനുസരിച്ച് വിധിക്കും" എന്ന് അദ്ദേഹം പറഞ്ഞു. അതിൽ കണ്ടെത്തിയില്ലെങ്കിലോ എന്ന് നബി(സ) ചോദിച്ചു. "എന്നാൽ അല്ലാഹുവിന്റെ റസൂലിന്റെ സുന്നത്തനുസരിച്ച്" എന്ന് അദ്ദേഹം മറുപടി പറഞ്ഞു. അവരണ്ടിലും കണ്ടെത്തിയില്ലെങ്കിലോ എന്ന് നബി(സ) ചോദിച്ചപ്പോൾ "ഞാൻ എന്റെ അഭിപ്രായം അനുസരിച്ച് വിധിക്കും" എന്നദ്ദേഹം പറഞ്ഞു. തിരുമേനി(സ) ആ മറുപടിയിൽ സന്തോഷം പ്രകടിപ്പിച്ചു. (ദാ,തി)', null, '53' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'paragraph', 'ഉമർ(റ) ശുറൈഹ്(റ)വിന് എഴുതിയ എഴുത്തിൽ ഇപ്രകാരമുണ്ടായിരുന്നു: ''തനിക്ക് വല്ല കാര്യവും വന്നുപെടുമ്പോൾ താൻ അല്ലാഹുവിന്റെ കിതാബിലുള്ള പ്രകാരം വിധി നടത്തണം. അല്ലാഹുവിന്റെ കിതാബിലില്ലാത്ത (വല്ലതും) വന്നാൽ റസൂൽ സുന്നത്താക്കിയ പ്രകാരം വിധിക്കണം.'' (ഉ.മുസ്തഫാ സബാഇ: നബിചര്യയും, ഇസ്‌ലാം ശരീഅത്തിൽ അതിന്റെ സ്ഥാനവും തർജ്ജമ, അമാനി മൗലവി 1973 പേ:340)', null, '53' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'നബി(സ) എന്തു ചെയ്താലും അത് അനുകരിക്കാൻ സ്വഹാബികൾക്ക് തിടുക്കമായിരുന്നു. രണ്ടു സ്നേഹിതന്മാരുണ്ടെങ്കിൽ അവർ തമ്മിൽ ഒരു ധാരണയിലെത്തും. ഒരാൾ നബി(സ)യുടെ അടുത്ത് എപ്പോഴും ഉണ്ടാവുന്ന വിധത്തിൽ ഊഴമിട്ടേ അവർ മറ്റു ജോലികൾക്കു പോവുകയുള്ളൂ. തന്റെ അഭാവത്തിൽ നബി(സ) പറയുന്ന കാര്യങ്ങൾ തനിക്ക് നഷ്ടപ്പെട്ടു പോവാതിരിക്കാനായിരുന്നു അത്. ഉമർ(റ) പറയുന്നു: ഞാനും ഉമയ്യത്തുബ്നു സൈദിന്റെ സന്തതികളിൽപെട്ട എന്റെ ഒരയൽക്കാരനും - അയാൾ മദീനയിലായിരുന്നു. - റസൂൽ തിരുമേനി(സ)യുടെ അടുക്കൽ ചെല്ലുന്നതിന് ഊഴം നിശ്ചയിച്ചു. ഒരു ദിവസം അദ്ദേഹം ചെല്ലും, ഒരുദിവസം ഞാൻ ചെല്ലും (ബുഖാരി). അത്രമാത്രം ശ്രദ്ധയായിരുന്നു നബി(സ)യുടെ ആദ്യകാല അനുയായികൾക്ക് നബി(സ)യുടെ ജീവിത മാതൃക പകർത്താൻ. നബി(സ)യുടെ നടത്തം, ഇരുത്തം, ഉറക്കം, വസ്ത്രം, തലയിലെ വെളുത്ത മുടിയുടെ എണ്ണം തുടങ്ങി എല്ലാ കാര്യങ്ങളും ശ്രദ്ധിക്കുന്നതിൽ ആദ്യകാല മുസ്‌ലിംകൾ ഉത്സുകരായിരുന്നു. ജാബിറുബ്നു അബ്ദില്ല(റ) അദ്ദേഹത്തിനറിയാത്ത ഒരു ഹദീസ് ഒരാളുടെ അടുത്തുണ്ടെന്നു കേട്ട് ഒരു മാസം യാത്ര ചെയ്ത് സിറിയയിലുള്ള അയാളുടെ അടുത്തുപോയി അത് പഠിച്ചു. അബൂ അയ്യൂബ്(റ) മദീനയിൽ നിന്നും ഒരു ഹദീസ് പഠിക്കാൻ ഈജിപ്തിൽ പോയി, അതുകേട്ട ഉടനെ തിരിച്ചുപോന്നു. മറ്റുദ്ദേശ്യമൊന്നും അദ്ദേഹത്തിനുണ്ടായിരുന്നില്ല (ഉ.മുസ്തഫാ സബാഈ). ബുഖാരി(റ)വും മുസ്‌ലിം(റ)വുമൊക്കെ വളരെയധികം ദൂരയാത്രകൾ ചെയ്തും ത്യാഗങ്ങൾ സഹിച്ചുമാണ് ഹദീസുകൾ ശേഖരിച്ചത്.', null, '53' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'subheading', 'ഹദീസ് ക്രോഡീകരണം:', null, '53' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 18, 'paragraph', 'ഹദീസുകൾ രേഖപ്പെടുത്തി വെക്കുന്നതിൽ ആദ്യകാല മുസ്‌ലിംകൾ ശ്രദ്ധിച്ചിരുന്നു എന്നാണ് മനസ്സിലാകുന്നത്. ഔപചാരികമായി നിർദ്ദിഷ്ട വ്യക്തികൾ ഖുർആൻ എഴുതിയിരുന്നു. നബി(സ) അതിന് ചിലരെ നിയോഗിച്ചിരുന്നു. ഹദീസ് അങ്ങിനെ ഔപചാരികമായി എഴുതിയിരുന്നില്ല. എന്നാലും അനൗപചാരികമായി എഴുതിയിരുന്നു. നബി(സ) ഒരിക്കൽ ഒരു പ്രസംഗം ചെയ്തപ്പോൾ യമൻകാരനായ അബൂശാക്ക് അത് എഴുതിക്കൊടുക്കണം എന്നാവശ്യപ്പെട്ടു. "അബൂശാക്കിന് അത് എഴുതിക്കൊടുക്കുവിൻ." എന്ന് നബി(സ) നിർദ്ദേശിച്ചു. (ഉ.മുസ്തഫാ സിബാഈ: നബിചര്യയും, ഇസ്‌ലാം ശരീഅത്തിൽ അതിന്റെ സ്ഥാനവും തർജമ, അമാനി മൗലവി, മുജാഹിദീൻ ട്രസ്റ്റ്, കൊച്ചിൻ-2 പേ:53.)', null, '53' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 19, 'paragraph', 'നബി(സ) പല ഭരണാധികാരികൾക്കും കത്തുകളയച്ചിരുന്നു എന്നു നമുക്കറിയാമല്ലോ. നബിയുടെ നിർദ്ദേശപ്രകാരം ചില ഉദ്യോഗസ്ഥർക്ക് സക്കാത്തിന്റെ കണക്കുകൾ എഴുതിക്കൊടുത്തിരുന്നു. جامع بيان العلم لابن عبد البر (അമാനി, നബിചര്യയും ...പേ:54) ളഹ്‌ഹാകുബ്നു സുഫ്‌യാൻ(റ) പറയുന്നു: കൊല്ലപ്പെട്ടവന്റെ ബന്ധുക്കൾക്കു നൽകുന്ന നഷ്ടപരിഹാരത്തുകയിൽ നിന്ന് അശ്‌യ മുളബ്ബി(കോല്ലപ്പെട്ടയാൾ)യുടെ ഭാര്യക്ക് അവകാശം നൽകുവാൻ റസൂൽ(സ) തനിക്ക് എഴുതുകയുണ്ടായി. (അ:ദ:തു)', null, '53' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 20, 'paragraph', 'അലി(റ) ''അൽ ഹിദായ'' എന്ന പേരിൽ ഒരു ചെറിയ ഹദീസ് ഗ്രന്ഥം ക്രോഡീകരിച്ചിരുന്നു. മുഹമ്മദുബ്നു ശിഹാബ് അൽ സുഹ്‌രി, അബൂബക്കർ അൽ ഹസം, അബ്ദുല്ലാഹിബ്നു ആസ്, ജാബിറുബ്നു അബ്ദില്ലാഹിൽ അൻസാരി തുടങ്ങിയവരും ആദ്യകാലത്ത് ഹദീസ് ക്രോഡീകരിച്ചിരുന്നു. ഉമറുബ്നു അബ്ദിൽ അസീസ്(റ) ഹദീസുകൾ ക്രോഡീകരിക്കാൻ നിർദ്ദേശിച്ചിരുന്നു. പിൽക്കാലത്ത് ഹദീസ് ക്രോഡീകരിച്ച പ്രാധാനികൾ ഇവരാണ്:', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 21, 'paragraph', 'ഇമാം സുഹ്‌രി (ഹി.124), ഇബ്നു ജുറൈജ് (150), ഇബ്നു ഇസ്ഹാഖ് (151), സഈദുബ്നു അബീ അറൂബ (156), റബീഉബ്നു സ്വബീഹ് (160), ഇമാം മാലിക്(റ).', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 22, 'paragraph', 'പ്രധാന ഹദീസ് ഗ്രന്ഥങ്ങൾ ഇവയാണ്: മുഹമ്മദുബ്നു ഇസ്മാഈലുൽ ബുഖാരി (256) യുടെ ''അൽ ജാമിഉസ്സ്വഹീഹ്'', ഇമാം മുസ്ലിമുബ്നുൽ ഹജ്ജാജിന്റെ (261) സ്വഹീഹു മുസ്ലിം, അബൂ ദാവൂദിന്റെ (275) ''സുനൻ'', നസാഈ (303)യുടെ ''സുനൻ'', തിർമുദിയുടെ (279) ''ജാമിഅ്'', ഇബ്നു മാജയുടെ (273) ''സുനൻ'' തുടങ്ങിയവ.', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 23, 'paragraph', 'നബി(സ)യുടെ കാലത്ത് അനുയായികളുടെ സംശയ നിവാരണത്തിന് അവിടുത്തോട് നേരിട്ട് സംശയങ്ങൾ ചോദിക്കാമായിരുന്നു. അതിനാൽ ഹദീസുകൾ ക്രോഡീകരിക്കേണ്ട ആവശ്യകത ഇല്ലായിരുന്നു. നബി(സ)യുടെ അനുയായികൾക്ക് പരസ്പരം ഒത്തു കൂടാനും സംശയ നിവാരണം നടത്താനും സൗകര്യമുണ്ടായിരുന്നു. പ്രവാചകർ(സ)യുടെ വഫാതോടെ സംശയങ്ങൾ നേരിട്ട് ദൂരീകരിക്കാനുള്ള അവസരങ്ങൾ ഇല്ലാതായി. ഇസ്‌ലാമിക സാമ്രാജ്യം വികസിച്ചപ്പോൾ പല അനുയായികളും പല ഭാഗങ്ങളിലും താമസമാക്കി. പലരും ഇസ്‌ലാമികാദർശത്തിന്റെ പ്രചരണാർത്ഥം ലോകത്തിന്റെ പല ഭാഗങ്ങളിലേക്കും പോയി. ഇസ്‌ലാമിക ജീവിതത്തിനും ഭരണ കാര്യങ്ങൾക്കും ഹദീസ് ക്രോഡീകരണം ആവശ്യമായി.', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 24, 'paragraph', 'ഒരാളിൽ നിന്ന് കേട്ടത് മറ്റൊരാളിലൂടെ മൂന്നാമത്തെ ആളിലേക്കും, അയാളിൽ നിന്ന് നാലാമത്തെ ആളിലേക്കും എത്തുമ്പോൾ ആദ്യത്തെ ആൾ പറഞ്ഞതിൽ നിന്നും വളരെ വ്യത്യാസം വരാറുണ്ട്. ഇത് ഹദീസിനും ബാധകമല്ലേ എന്നാണ് ഒരു സംശയം. എന്നാൽ, ഒരേ ഹദീസ് വിവിധ റിപ്പോർട്ടർമാരിലൂടെ റിപ്പോർട്ടു ചെയ്യുമ്പോഴും അതിന്റെ തനിമ സംരക്ഷിക്കപ്പെടുന്നതായി നാം കാണുന്നു. ആശയമല്ല, വാക്കുകൾ തന്നെയാണ് കൈമാറ്റം ചെയ്യപ്പെടുന്നത് എന്നത് ശ്രദ്ധേയമാണ്. വളരെ സൂക്ഷ്മതയോടെയാണ് ആദ്യകാല മുസ്‌ലിംകൾ നബിവചനങ്ങൾ കൈകാര്യം ചെയ്തത്. "എന്റെ പേരിൽ മനഃപൂർവ്വം വ്യാജ പ്രസ്താവന ചെയ്യുന്നവർ നരകാഗ്നിയിൽ സ്ഥാനം ഉറപ്പിച്ചു കൊള്ളട്ടെ." എന്ന നബി(സ)യുടെ താക്കീതും ഹദീസുകൾ റിപ്പോർട്ടു ചെയ്യുന്നതിൽ സൂക്ഷ്മത പാലിക്കാൻ പ്രേരകമായി.', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 25, 'paragraph', 'ഹദീസുകൾ മറന്നു പോകാൻ ഇടയില്ലേ എന്നാണ് ഒരു സംശയം. അറബികളുടെ ഓർമ്മശക്തി പ്രസിദ്ധമാണ്. തങ്ങളുടെ വംശാവലി അവർ ഹൃദിസ്ഥമാക്കിയിരുന്നു. അബൂതമാം 14000 കവിതകൾ ഹൃദിസ്ഥമാക്കി. ഹമ്മാദ് എന്ന കവി 27000 ഖസീദ (കവിത) മനഃപാഠമാക്കി. അസ്മഈ എന്ന കവി 16000 കവിതകളാണ് ഹൃദിസ്ഥമാക്കിയത്. കവിതാ മത്സരങ്ങളിൽ ഒരേ ഇരുപ്പിൽ ആയിരക്കണക്കിന് കവിതകൾ ചൊല്ലി എതിരാളികളെ തോൽപിച്ച കവികളും ഉണ്ടായിരുന്നു. ഒരു മാസക്കാലം തുടർച്ചയായി കവിതകൾ ചൊല്ലാൻ തനിക്ക് യാതൊരു പ്രയാസവുമില്ലെന്ന് ശഅബി എന്ന കവി അഭിമാനപൂർവ്വം പറയുമായിരുന്നു. മസ്തിഷ്കത്തെക്കുറിച്ചുള്ള ആധുനിക ഗവേഷണ ഫലങ്ങൾ പറയുന്നത് മസ്തിഷ്കത്തിന്റെ ഏതു ഭാഗം നാം എക്സർസൈസ് ചെയ്യുന്നുവോ ആ ഭാഗം കൂടുതൽ പുഷ്ടിപ്പെടുമെന്നാണ്. കുറെ കാര്യങ്ങൾ മനഃപാഠമാക്കിയാൽ മറ്റു കാര്യങ്ങളും മനഃപാഠമാക്കുക എളുപ്പമാകും.', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 26, 'paragraph', 'അറബികൾ ഓർമ്മശക്തി വർദ്ധിപ്പിക്കാൻ പരിശീലിച്ചിരുന്നുവെന്നും ചരിത്രം സാക്ഷി നിൽക്കുന്ന ഒരു വസ്തുതയാണ്. അബൂഹുറൈറ(റ)വിന്റെ തന്നെ ഓർമ്മ ശക്തിയെപ്പറ്റി ചരിത്രത്തിൽ രേഖപ്പെട്ട ഒരു സംഭവം നോക്കൂ!', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 27, 'paragraph', 'അബൂഹുറൈറ(റ)യുടെ മനഃപാഠവും ഓർമ്മശക്തിയും മർവാൻ(റ) പരിശോധിച്ച ഒരു സംഭവം അദ്ദേഹത്തിന്റെ എഴുത്തുകാരനായിരുന്ന അബൂ സുഐസിഅഃയിൽ നിന്ന് ഇബ്നു ഹജർ അൽ ഇസ്വാബയിൽ ഇങ്ങനെ ഉദ്ധരിച്ചിരിക്കുന്നു: മർവാൻ അബൂഹുറൈറ(റ)യെ ആളയച്ചു വരുത്തി. എന്നിട്ട് അദ്ദേഹം മർവാന് ഹദീസ് പറഞ്ഞു കൊടുത്തുകൊണ്ടിരുന്നു. തനിക്ക് പറഞ്ഞുതരുന്ന ഹദീസുകൾ എഴുതാൻ കട്ടിലിനു മറവിൽ അബൂസുഐസിഅയെ ഇരുത്തിയിരുന്നു. അങ്ങനെ കൊല്ലാവസാനം വീണ്ടും അബൂഹുറൈറ(റ)യെ വരുത്തി ഹദീസുകൾ ചോദിച്ചു. അദ്ദേഹം പറഞ്ഞത് മർവാൻ തന്റെ അടുക്കൽ മുമ്പ് എഴുതി വെച്ചിരുന്നതുമായി ഒത്തുനോക്കി. എന്നാൽ പണ്ടു പറഞ്ഞതും ഇപ്പോൾ പറഞ്ഞതും തമ്മിൽ ഒരക്ഷരത്തിനു പോലും മാറ്റമില്ലായിരുന്നു. (ഡോ: മുസ്തഫാ സബാഇയുടെ, നബി ചര്യയും ഇസ്‌ലാം ശരീഅത്തിൽ അതിന്റെ സ്ഥാനവും. തർജ്ജമ 1973 പേ 224)', null, '54' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 28, 'paragraph', 'ബുഖാരി, മുസ്‌ലിം, ഇബ്നു മാജഃ, തുർമുദി, നസാഈ, അബൂ ദാവൂദ്, ഇമാം മാലിക്, അഹമ്മദുബ്‌നു ഹമ്പൽ തുടങ്ങിയവർ ഹദീസുകൾ ശേഖരിക്കുകയും റിപ്പോർട്ടർമാരുടെ പരമ്പരയും, ആധികാരികതയും പരിശോധിച്ച് അവർക്ക് വിശ്വാസയോഗ്യമെന്നു തോന്നിയവ രേഖപ്പെടുത്തുകയും ചെയ്തു.', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 29, 'paragraph', 'നബി(സ) ഹദീസുകൾ എഴുതിവെക്കുന്നത് തടഞ്ഞതായി ഒരു റിപ്പോർട്ടുണ്ട്. അബൂഹുറൈറ(റ) നിവേദനം ചെയ്ത ഒരു ഹദീസിൽ ഇങ്ങനെ പറയുന്നു: ഞങ്ങൾ ഹദീസ് എഴുതിക്കൊണ്ടിരിക്കെ നബി(സ) ഞങ്ങളുടെ അടുത്തുവന്നു ചോദിച്ചു: "നിങ്ങൾ എന്താണ് എഴുതുന്നത്?" ഞങ്ങൾ പറഞ്ഞു: അങ്ങയിൽ നിന്ന് ഞങ്ങൾ കേൾക്കുന്ന വചനങ്ങൾ. നബി(സ) പറഞ്ഞു: "എന്ത്! അല്ലാഹുവിന്റെ ഗ്രന്ഥമൊഴിച്ച് മറ്റൊരു ഗ്രന്ഥമോ?" നബിവചനങ്ങളും ഖുർആൻ വാക്യങ്ങളും ഇടകലർന്നു പോകാതിരിക്കാനും, ഖുർആന്റെ പവിത്രത സംരക്ഷിക്കാനുമായുള്ള ഒരു മുൻകരുതലായിരുന്നു ഇത്. ഹദീസുകൾ ഗ്രന്ഥ രൂപത്തിൽ എഴുതി സൂക്ഷിക്കുന്നത്, ഈ വചനം തടഞ്ഞുവെങ്കിലും അതിനെ നിരുത്സാഹപ്പെടുത്തിയിരുന്നില്ലെന്ന് ഇതിൽ നിന്നു തെളിയുന്നുണ്ട്.', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 30, 'paragraph', 'നബി(സ)യുടെ ജീവിത കാലത്തുതന്നെ അവിടുത്തെ വചനങ്ങളും ചര്യകളും രേഖപ്പെടുത്തിയ സംഭവങ്ങളുണ്ട്. ഹദീസ് പണ്ഡിതനായ ഇമാം ബുഖാരി(ഖ) തന്റെ സുപ്രസിദ്ധമായ ''സ്വഹീഹിൽ'' അതിനെക്കുറിച്ച് പ്രസ്താവിക്കുന്നു. അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) നബി(സ)യുടെ ചര്യകൾ അദ്ദേഹത്തിന്റെ ജീവിത കാലത്തു തന്നെ രേഖപ്പെടുത്തി. അദ്ദേഹം പ്രവാചകർ(സ)യുടെ സമീപം ചെന്ന് ചോദിച്ചു: ദൈവ ദൂതരെ, താങ്കളുടെ ചര്യകളിൽ ചിലത് നിവേദനം ചെയ്യാൻ ഞാൻ ആഗ്രഹിക്കുന്നു. അതിനായി മനഃപാഠമാക്കാനും ഉദ്ദേശിക്കുന്നു. അതിനെക്കുറിച്ച് എന്തു നിർദ്ദേശമാണ് അങ്ങു തരുന്നത്?. പ്രവാചകൻ(സ) പറഞ്ഞു: "അവ എന്റെ വാക്കുകൾ തന്നെയാണെങ്കിൽ എഴുതുകയും മനഃപാഠമാക്കുകയും ചെയ്യുക."', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 31, 'paragraph', 'അബൂഹുറൈറ(റ)യിൽ നിന്ന് നിവേദനം: പ്രവാചകർ(സ)യുടെ ഹദീസുകൾ എന്നെക്കാൾ കൂടുതൽ അറിയുന്നവരായി അബ്ദുല്ലാഹിബ്നു ഉമർ(റ) അല്ലാതെ ആരുമില്ല. അദ്ദേഹം അവ എഴുതി വെക്കുകയും ഞാൻ അപ്രകാരം ചെയ്യാതിരിക്കുകയും ചെയ്തു. ഉമറുബ്നു അബ്ദുൽ അസീസ്(റ) മദീനാ ഗവർണർ ബക്കർ ഇബ്നു ഹസമിക്ക് എഴുതി: പ്രവാചകന്റേതെന്നു വിശ്വാസ യോഗ്യമായ ഹദീസുകളിൽ നിങ്ങൾക്ക് അറിയാവുന്നവ എഴുതി അയച്ചു തരിക.', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 32, 'paragraph', 'സഈദുബ്നു സുബൈർ(റ) നിവേദനം ചെയ്യുന്നു: ''ഞാൻ ഇബ്നു അബ്ബാസ്(റ)വിനൊപ്പം മക്കയിലേക്കു പോയി. അദ്ദേഹം പ്രഭാതം വരെ പ്രവാചകചര്യകൾ പറഞ്ഞു തരികയും ഞാൻ ജീനിയുടെ മുകളിൽ അവ എഴുതുകയും ചെയ്തു''.', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 33, 'paragraph', 'ഖുർആനും ഹദീസും എഴുതി സൂക്ഷിക്കുന്ന കാര്യത്തിൽ സ്വഹാബികൾ പ്രത്യേക ശ്രദ്ധ പുലർത്തി. ഇമാം അലി(റ) ഹുദൈബിയാ ഉടമ്പടി മുഴുവൻ എഴുതിയതായി രേഖയുണ്ട്. ഈജിപ്തിലെ മുഖൗഖിസിന് പ്രവാചകൻ(സ) അയച്ച എഴുത്ത് കണ്ടുകിട്ടിയിട്ടുണ്ട്. അത് ഇന്നും സുരക്ഷിതമാണ്. അതിലെ വാചകങ്ങൾ ഹദീസുകളിൽ വിവരിച്ചവ തന്നെയാണ്.', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 34, 'paragraph', 'എഴുത്തുവിദ്യക്ക് പ്രവാചകർ(സ)യുടെ കാലഘട്ടത്തിൽ വമ്പിച്ച പ്രോത്സാഹനവും പ്രചാരവും ലഭിച്ചു. രേഖകളും പ്രമാണങ്ങളും എഴുതിവെക്കുന്ന പതിവും തുടങ്ങി. തന്റെ വചനങ്ങൾ ഇതര ജനങ്ങളുടെ അറിവിലേക്കായി പ്രചരിപ്പിക്കണമെന്ന് പ്രവാചകൻ(സ) ഉപദേശിച്ചിട്ടുണ്ട്. "എന്റെ വചനം കേൾക്കുകയും അത് ഹൃദിസ്ഥമാക്കുകയും പ്രചരിപ്പിക്കുകയും ചെയ്ത ദാസനിൽ, അല്ലാഹുവിന്റെ സംതൃപ്തിയുണ്ടാവട്ടെ." എന്ന് നബി(സ) പ്രാർത്ഥിച്ചു.', null, '55' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 35, 'paragraph', 'അഹ്മദ് അമീനെപ്പോലുള്ള പാശ്ചാത്യൻ സ്വാധീനത്തിനു വിധേയരായ എഴുത്തുകാർ (വിശദീകരണത്തിന് ഡോ: മുസ്‌തഫാ സബാഇയുടെ, നബി ചര്യയും ഇസ്‌ലാം ശരീഅത്തിൽ അതിന്റെ സ്ഥാനവും തർജമ പേ: 170 മുതൽ 190 വരെ നോക്കുക.) ഭൂരിപക്ഷം ഹദീസുകളും വിശ്വാസ യോഗ്യമല്ല എന്നു വരുത്തിത്തീർക്കാൻ ശ്രമിച്ചതായി കാണാം. (ഉദാ: ഫജ്‌റുൽ ഇസ്‌ലാം എന്ന കൃതി.) ആറു ലക്ഷം ഹദീസിൽ നിന്നാണ് ബുഖാരി തന്റെ കൃതിയിലുള്ളത് തെരഞ്ഞെടുത്തത് എന്നു പറയുമ്പോൾ ഒരു കാര്യം ശ്രദ്ധിക്കേണ്ടതുണ്ട്. ഒരു ഹദീസ് തന്നെ പല റിപ്പോർട്ടർമാരിലൂടെയും ലഭിച്ചാൽ പല ഹദീസായി ഗണിക്കും. ഒരു ഹദീസ് തന്നെ നൂറ് കണക്കിൽ ആളുകൾ റിപ്പോർട്ട് ചെയ്ത സംഭവങ്ങളുമുണ്ട്. അപ്പോൾ അവ 100 ഹദീസായിട്ടാണ് ഗണിക്കുക.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 36, 'paragraph', 'അബൂഹൂറൈറ(റ)യെ പോലുള്ളവർ ധാരാളം ഹദീസുകൾ റിപ്പോർട്ട് ചെയ്തതുകൊണ്ട് അവയിൽ പലതും വ്യാജമായി പിന്നീട് നിർമ്മിക്കപ്പെട്ടതാണ് എന്ന് ഓറിയന്റലിസ്റ്റുകൾ, (ഇസ്‌ലാമിനെക്കുറിച്ചു ഗ്രന്ഥ രചനയിലേർപ്പെട്ട യൂറോപ്യന്മാർ.) അഭിപ്രായപ്പെട്ടിട്ടുണ്ട്. യൂറോപ്പിലെ ക്രിസ്ത്യൻ രാജ്യങ്ങളെല്ലാം കൂടി ഒന്നിച്ചു ശ്രമിച്ചിട്ടും യൂറോപ്യന്മാർ കുരിശു യുദ്ധങ്ങളിൽ മുസ്‌ലിംകളോട് പരാജയപ്പെട്ടു. മുസ്‌ലിംകളുടെ ഇസ്‌ലാമിലുള്ള വിശ്വാസം തകർക്കാൻ കഴിഞ്ഞാലേ മുസ്‌ലിംകളെ തോൽപിക്കാനാവൂ എന്നവർ മനസ്സിലാക്കി. അങ്ങനെ അവർ ഇസ്‌ലാമിനെക്കുറിച്ചു പഠിക്കാനും ഇസ്‌ലാമിനെക്കുറിച്ച് സംശയങ്ങളുണ്ടാക്കുന്ന ഗ്രന്ഥങ്ങൾ രചിക്കാനും അവ പ്രചരിപ്പിക്കാനും ആസൂത്രിതമായി ശ്രമിച്ചുകൊണ്ടിരുന്നു. പല മുസ്‌ലിം എഴുത്തുകാരും ഇവരുടെ സ്വാധീന വലയത്തിൽ പെട്ടിട്ടുണ്ട്. അവർ ഓറിയന്റലിസ്റ്റുകൾ എഴുതി വെച്ചത് പരിശോധിക്കാൻ ശ്രമിക്കാതെ ഓറിയന്റലിസ്റ്റുകളുടെ ആശയങ്ങൾ പ്രചരിപ്പിക്കുന്നതായി കാണാം. ഓറിയന്റലിസ്റ്റുകൾ മനഃപൂർവ്വം ഉദ്ധരണികളിൽ മായം ചേർത്തതും, ഓറിയന്റലിസ്റ്റു സ്വാധീനത്തിൽപ്പെട്ട മുസ്‌ലിംകൾ ഹദീസിനെക്കുറിച്ച് എഴുതി വെച്ചതും അതിലവർക്കു പിണഞ്ഞ അബദ്ധങ്ങളും മറ്റും الحديث ومكانته في التشريع الاسلامي എന്ന തന്റെ പുസ്തകത്തിൽ മുസ്‌തഫാ സബാഈ ഉദാഹരണ സഹിതം വിശദമായി ചർച്ച ചെയ്യുന്നുണ്ട്.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 37, 'subheading', 'ഹദീസ് പരിശോധനക്കുള്ള നിയമങ്ങൾ:-', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 38, 'paragraph', 'അനേകശതം ഹദീസുകളിൽ നിന്നും വിശ്വസ്തമായവയെ തെരഞ്ഞെടുക്കുന്നതിന് പ്രാമാണികമായ ആറ് ഹദീസ് ഗ്രന്ഥങ്ങളുടെ (അസ്സിഹാഹുസ്സിത്തഃ) നിർമ്മാണത്തിന് ഹദീസ് പണ്ഡിതന്മാർ ചില നിബന്ധനകളും, മാനദണ്ഢങ്ങളും സ്വീകരിച്ചിട്ടുണ്ട്:-', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 39, 'list_item', '1. പ്രവാചകൻ(സ) ഇന്നയിന്ന കാര്യം പറഞ്ഞുവെന്നോ, ഇന്നതു ചെയ്തുവെന്നോ വ്യക്തമായി പ്രസ്താവിച്ചിരിക്കണം.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 40, 'list_item', '2. നിവേദകൻ തന്നെ സന്നിഹിതനായിരുന്നുവെന്നോ, പ്രവാചകൻ(സ) പറഞ്ഞതായി കേട്ടുവെന്നോ പ്രസ്താവിച്ചിരിക്കേണ്ടതും നിവേദക പരമ്പര പ്രവാചകനിൽ ചെന്ന് പര്യവസാനിക്കേണ്ടതുമാകുന്നു', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 41, 'list_item', '3. പ്രവാചകർ(സ)യുടെ അനുയായികളുടെമേലോ, കുടുംബത്തിന്റെ (അഹ്‌ലുൽബൈത്ത്) മേലോ കുറ്റാരോപണം ചെയ്യുന്നവരുടെ നിവേദനങ്ങൾ തള്ളപ്പെടേണ്ടതാണ്.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 42, 'list_item', '4. അറബി ഭാഷക്ക് അനുയോജ്യമല്ലാത്തതോ, അന്തസ്സാര വിഹീനമായതോ ആയവ തള്ളപ്പെടും.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 43, 'list_item', '5. നിവേദക പരമ്പരയിൽ ഓരോരുത്തരും പരസ്പരം കണ്ടതായി തെളിഞ്ഞിരിക്കണം.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 44, 'list_item', '6. ഓരോ നിവേദകനും കേൾക്കുന്ന അവസരത്തിൽ, കേട്ടത് യഥാവിധി ഗ്രഹിക്കത്തക്ക വിധത്തിൽ പ്രായം എത്തിയവനാകണം.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 45, 'list_item', '7. സുസ്ഥാപിതമായ ചരിത്ര സംഭവങ്ങൾക്കു വിരുദ്ധമായവ നിരാകരിക്കപ്പെടും.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 46, 'list_item', '8. ലഘുവായ കുറ്റങ്ങൾക്കു ഭയങ്കര ശിക്ഷയും, തുഛമായ ഗുണത്തിനു ഭീമമായ പ്രതിഫലവും വാഗ്ദാനം ചെയ്യുന്നവ തള്ളപ്പെടേണ്ടതാണ്.', null, '56' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 47, 'list_item', '9. നിവേദകരിൽ നബി(സ) വരെയുള്ള ഓരോരുത്തരും സത്യത്തിലും ഭക്തിയിലും സുപ്രസിദ്ധരാകണം.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 48, 'list_item', '10. നിവേദകരിൽ ഓരോരുത്തരും താൻ കേട്ടതിനെ ശരിയായി മനസ്സിലാക്കുന്നതിനും, കേട്ടത് വ്യത്യാസമില്ലാതെ നിവേദനം ചെയ്യുന്നതിനും പ്രാപ്തിയുള്ള പണ്ഡിതരായിരിക്കണം.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 49, 'list_item', '11. മുസ്ലിംകൾ പൊതുവെ അറിഞ്ഞിരിക്കേണ്ടതും, അതനുസരിച്ച് പ്രവർത്തിക്കേണ്ടതുമായ ഒരു കാര്യം ഒരാൾമാത്രം കേട്ടുവെന്ന് അവകാശപ്പെടുകയും നിവേദനം ചെയ്യുകയും ചെയ്യുന്നപക്ഷം അതു തള്ളപ്പെടേണ്ടതാണ്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 50, 'list_item', '12. യുക്തിക്കും, അറിയപ്പെട്ട തത്വവ്യവസ്ഥകൾക്കും വിരുദ്ധമായവ ഉപേക്ഷിക്കേണ്ടതാണ്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 51, 'list_item', '13. ഖുർആനിക സിദ്ധാന്തങ്ങൾക്കു വിരുദ്ധമായവ തള്ളപ്പെടും.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 52, 'list_item', '14. നബി(സ)യുടെ സർവ്വസമ്മതമായ വചനങ്ങൾക്കു വിരുദ്ധമായവ സ്വീകാര്യമല്ല.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 53, 'paragraph', 'ഇവക്കു പുറമെ നിവേദകന്മാർക്കും ചില പ്രത്യേക യോഗ്യതകൾ നിർദ്ദേശിക്കപ്പെട്ടിട്ടുണ്ട്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 54, 'list_item', '1. നിവേദകന്റെ പേര്, അറിയപ്പെടുന്ന പേര്, മാതാപിതാക്കളുടെ പേര്, തൊഴിൽ, സ്ഥാനപ്പേര് ഇവ വ്യക്തമായി അറിഞ്ഞിരിക്കണം.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 55, 'list_item', '2. ഹദീസ് നിവേദനം ചെയ്ത വിഷയത്തിൽ നിവേദകൻ ഒരിക്കലും വ്യാജ പ്രസ്താവനകൾ ചെയ്തിരിക്കരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 56, 'list_item', '3. ഏതെങ്കിലും കുറ്റങ്ങൾക്കു ശിക്ഷിക്കപ്പെട്ടവനോ, അസത്യവാദിയോ ആകരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 57, 'list_item', '4. നിവേദകൻ തുടർച്ചയായി തെറ്റുചെയ്യുകയോ, അബദ്ധങ്ങൾ കാണിക്കുകയോ ചെയ്യാൻ പാടില്ല.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 58, 'list_item', '5. നിവേദനം ചെയ്യുന്ന കാര്യത്തിൽ അശ്രദ്ധനാകരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 59, 'list_item', '6. വാക്കിലോ, പ്രവൃത്തിയിലോ ദുഷ്ടത പാടില്ല.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 60, 'list_item', '7. ഊഹത്തിൽ നിന്നു നിവേദനം ചെയ്യരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 61, 'list_item', '8. വിശ്വാസയോഗ്യരായവരെക്കുറിച്ച് അപവാദം പറയുന്നയാളാവരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 62, 'list_item', '9. മൂഢനായ നിരക്ഷരനാകരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 63, 'list_item', '10. മതപരമായി അസാധാരണമായ അഭിപ്രായ ഗതിയുള്ള ആളാകരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 64, 'list_item', '11. ഓർമ്മശക്തിയിൽ ദുർബ്ബലനാകരുത്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 65, 'list_item', '12. ഖുർആൻ നാൽപത്തി ഒമ്പതാം അദ്ധ്യായം: സൂറത്തു ഹുജുറാത്ത്: ആറാം വചനത്തിലെ നിബന്ധനകളനുസരിച്ച് സസൂക്ഷ്മം ഹദീസുകൾ പരിശോധിച്ച ആളായിരിക്കണം.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 66, 'paragraph', 'മേൽപ്പറഞ്ഞ മാനദണ്ഢങ്ങൾക്കുപുറമെ നിവേദനം ചെയ്യപ്പെട്ട ഹദീസുകൾ പ്രവാചക വചനങ്ങളുടെ സാരം മാത്രമാണോ, അതോ പ്രവാചക വചനം അപ്പടിതന്നെയാണോ എന്നും പരിശോധകർ പരിശോധിക്കും. നിവേദകന്റെ ജ്ഞാനവും, ഭക്തിയും സംശയാസ്പദമാണെങ്കിൽ അവ തള്ളപ്പെടും.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 67, 'paragraph', 'ഇതോടെ നിവേദകരുടെ ജീവിതക്രമവും ജീവചരിത്രവും അറിഞ്ഞിരിക്കൽ ആവശ്യമായിത്തീർന്നു. അങ്ങനെ "അസ്മാഉർറിജാൽ" അഥവാ, നിവേദകരുടെ ചരിത്ര ശേഖരം ആവശ്യമായിത്തീർന്നു. പത്തൊമ്പത് ലക്ഷത്തോളം വരുന്ന നിവേദകരുടെ ജീവചരിത്രം വ്യക്തമായി രേഖപ്പെടുത്തപ്പെട്ടിട്ടുണ്ട്.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 68, 'paragraph', 'ഇമാം ബുഖാരി(റ), ഹ:മുസ്ലിം(റ), അബൂ ദാവൂദ്(റ), തുർമുദി(റ), നസാഈ(റ), ഇബ്നു മാജഃ(റ) തുടങ്ങിയ പണ്ഡിതരുടെ ''അസ്സിഹാഹുസ്സിത്തഃ'' എന്നറിയപ്പെടുന്ന ഗ്രന്ഥങ്ങളിൽ ഉൾക്കൊള്ളുന്ന ഹദീസുകൾ മുൻപറഞ്ഞ മാനദണ്ഢങ്ങൾക്കും പരീക്ഷണങ്ങൾക്കും വിധേയമായി ശേഖരിക്കപ്പെട്ടവയാണ്. ബുഖാരി, മുസ്ലിം ഇവരുടെ ''സ്വഹീഹു''കളിൽ ഉള്ള ഹദീസുകൾ സർവ്വ സ്വീകാര്യങ്ങളായി ഗണിക്കപ്പെടുന്നു.', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 69, 'subheading', 'ഹദീസ് വിഭജനം', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 70, 'paragraph', 'ഹദീസുകളെ പ്രധാനമായും മൂന്നായി തിരിച്ചിരിക്കുന്നു:', null, '57' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 71, 'list_item', '1. ഖൗലിയ്യ് (പ്രവാചകൻ അരുളിയ വചനങ്ങൾ)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 72, 'list_item', '2. ഫിഅ്‌ലിയ്യ് (പ്രവാചകൻ ചെയ്തിട്ടുള്ളതും, അനുയായികൾ അവരുടെ ഭാഷയിൽ നിവേദനം ചെയ്തിട്ടുള്ളതും.)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 73, 'list_item', '3. തശ്‌രീരിയ്യ് (തന്റെ സന്നിധിയിൽ ചെയ്യുകയോ, മറ്റുള്ളവർ ചെയ്തതായി പറഞ്ഞറിയുകയോ ചെയ്ത ഒരു കാര്യം, പ്രവാചകൻ(സ) നിരോധിക്കുകയോ വിസമ്മതം പ്രകടിപ്പിക്കുകയോ ചെയ്യാത്തത്.)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 74, 'paragraph', 'മേൽപറഞ്ഞ മൂന്നു വകുപ്പിൽ പെട്ടതിനും ഹദീസ് (നബിവചനം) എന്നാണ് പറയുന്നത്.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 75, 'paragraph', 'മതപണ്ഡിതർ ഹദീസുകളെ വീണ്ടും രണ്ടായി വിഭജിച്ചിരിക്കുന്നു:', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 76, 'list_item', '1. ഹദീസുന്നബവീ (പ്രവാചകൻ(സ)യുടെ വചനങ്ങൾ)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 77, 'list_item', '2. ഹദീസുൽ ഖുദുസീ (ദിവ്യബോധനം മൂലം ലഭിച്ചവ)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 78, 'paragraph', 'നിവേദകരുടെ സംഖ്യാബലത്തെ ആസ്പദമാക്കി ഹദീസുകൾ രണ്ടു വിധമാണ്:', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 79, 'list_item', '1. മുതവാത്തിർ (അനുസ്യൂതം)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 80, 'list_item', '2. ആഹാദ്.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 81, 'subheading', 'മുതവാത്തിർ: -', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 82, 'paragraph', 'കളവു കടന്നുകൂടാൻ നിവൃത്തിയില്ലാത്ത വിധം ധാരാളം നിവേദകർ ഒരേ വിധത്തിൽ നിവേദനം ചെയ്തിട്ടുള്ളവയാണ് ''മുതവാത്തിർ'' (അനുസ്യൂതം).', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 83, 'subheading', 'ആഹാദ്: -', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 84, 'paragraph', 'നിവേദക പരമ്പരയിൽ എണ്ണക്കുറവുള്ളതാണ് ആഹാദ്. ഇവയുടെ വിശ്വാസ്യത ആപേക്ഷികമാണ്. നിവേദകപരമ്പരിയിള്ളവർ വിശ്വസ്തരും സത്യസന്ധരുമാണെങ്കിൽ അതു സ്വീകരിക്കപ്പെടുകയും, മറിച്ചാണെങ്കിൽ തള്ളപ്പെടുകയും ചെയ്യുന്നു.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 85, 'paragraph', 'ആഹാദിനെ മൂന്നായി തിരിച്ചിരിക്കുന്നു:', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 86, 'list_item', '1. സ്വഹീഹ് (സ്വീകാര്യം)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 87, 'list_item', '2. ഹസൻ (നല്ലത്)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 88, 'list_item', '3. ളഈഫ് (ദുർബ്ബലം)', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 89, 'paragraph', 'ആപേക്ഷികമായി ഒന്നാമത്തേത് സർവ്വസ്വീകാര്യവും, രണ്ടാമത്തേത് അല്പം താഴ്ന്ന പടിയിലും, മൂന്നാമത്തേത് രണ്ടാമത്തേതിനെക്കാൾ താണ പടിയിലുമാണുള്ളത്.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 90, 'subheading', 'സ്വഹീഹ്: -', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 91, 'paragraph', 'വിട്ടുവീഴ്ചയില്ലാത്ത മതനിഷ്ഠ, മനുഷ്യത്വത്തിന് നിരക്കാത്ത് കർമ്മങ്ങൾ ചെയ്യാതിരിക്കൽ ഹദിസ് കൈകാര്യം ചെയ്യുന്ന സകല സന്ദർഭങ്ങളിലും സൂക്ഷ്മത കാണിക്കൽ എന്നീ സദ്ഗുണങ്ങളുടെ ഉമെയായിരിക്കുകയും വൈയക്തികമായും സമൂഹമദ്ധ്യേയും അന്യൂനനായിരിക്കുകയും ചെയ്ത റിപ്പോർട്ടർമാർ ഉദ്ധരിച്ച ഹദീസുകൾ വിശ്വാസയോഗ്യരും പ്രശസ്ഥരുമായ റിപ്പോർട്ടമാർ ഉദ്ധരിച്ച ഹദീസുകൾക്ക് വിരുദ്ധമാവാതെ വന്നാൽ അവയ്ക്ക് സ്വഹീഹ് എന്നു പറയുന്നു.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 92, 'subheading', 'സ്വഹീഹായ ഹദീസുകൾ ഏഴുവിധം: -', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 93, 'list_item', '1. ബുഖാരിയും മുസ്‌ലിമും സ്വീകരിച്ചിട്ടുള്ളവ ഏറ്റവും വിശ്വാസ യോഗ്യമായി കരുതപ്പെടുകയും, അവ "മുത്തഫഖുൻ അലൈഹി" (ബുഖാരിയും മുസ്‌ലിമും ഐക്യകണ്ഠേന സ്വീകരിച്ചവ) എന്നപേരിൽ അറിയപ്പെടുകയും ചെയ്യുന്നു.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 94, 'list_item', '2. ബുഖാരി(റ) മാത്രം നിവേദനം ചെയ്തിട്ടുള്ളത്.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 95, 'list_item', '3. മുസ്‌ലിം(റ) മാത്രം നിവേദനം ചെയ്തിട്ടുള്ളത്.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 96, 'list_item', '4. സ്വഹീഹു ബുഖാരിയിലും, സ്വഹീഹു മുസ്‌ലിമിലും നിർദ്ദേശിക്കപ്പെട്ട നിയമങ്ങൾക്കു വിധേയമായവ.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 97, 'list_item', '5. ബുഖാരി(റ) മാത്രം നിർദ്ദേശിച്ച നിയമങ്ങൾക്കു വിധേയമായവ.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 98, 'list_item', '6. മുസ്‌ലിം(റ) മാത്രം നിർദ്ദേശിച്ച നിയമങ്ങൾക്കു വിധേയമായവ.', null, '58' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 99, 'list_item', '7. ബുഖാരിയും മുസ്‌ലിമും ഒഴികെ മറ്റു പണ്ഡിതന്മാരെല്ലാം സ്വഹീഹാണെന്നു പറഞ്ഞിട്ടുള്ളവ.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 100, 'subheading', 'ഹസൻ (നല്ലത്): -', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 101, 'paragraph', '''സ്വഹീഹ്'' പോലെയാണെങ്കിലും, ചില നിവേദകരിൽ താരതമ്യേന സ്വഹീഹിന്റെ നിവേദകരെക്കാൾ ഓർമ്മശക്തിയിലും, ഗ്രഹണ പാടവത്തിലും അൽപം കുറവുള്ളവരായി കാണപ്പെട്ടവർ നിവേദനം ചെയ്തവയാണ് ഇവ.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 102, 'subheading', 'ളഈഫ് (ദുർബ്ബലം) : -', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 103, 'paragraph', 'നിവേദക പരമ്പരയിൽ ഇടക്കുള്ള കണ്ണി വിട്ടുപോകുകയോ സ്വഹീഹിൽ പറഞ്ഞ നിബന്ധനകൾ പൂർണ്ണമായോ ഭാഗികമായോ ഇല്ലാതാകുകയോ ചെയ്തതുമൂലം വിശ്വാസ്യയോഗ്യത കുറഞ്ഞതോ, അവിശ്വസനീയമായതോ ആയിത്തീരുന്നു.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 104, 'paragraph', 'ആഹാദായ ഹദീസുകളെ പ്രാമാണികതയുടെ അടിസ്ഥാനത്തിൽ വീണ്ടും വിഭജിച്ചിരിക്കുന്നു', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 105, 'list_item', '1. മശ്ഹൂർ (സുപ്രസിദ്ധം) ഭൂരിപക്ഷം ആളുകളും പരസ്യമായി അറിഞ്ഞിട്ടുള്ളതാണെങ്കിലും സാർവ്വലൗകിക സ്വഭാവം ഇവക്കില്ല. ഓരോഘട്ടത്തിലും രണ്ടിൽ കൂടുതൽ കൈവഴികളിലായി അവ നിവേദനം ചെയ്യപ്പെട്ടിട്ടുണ്ട്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 106, 'list_item', '2. അസീസ് (സുശക്തം-സുസമ്മതം) എല്ലാ കാലത്തും രണ്ടു നിവേദകർ നിവേദനം ചെയ്തിട്ടുള്ളത്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 107, 'list_item', '3. ഗരീബ് (അപരിചിതം) ഏതെങ്കിലും ഒരു കാലത്ത് സന്ദർഭത്തിൽ ഒരു നിവേദകനെ മാത്രം അവലംബിച്ചു നിൽക്കുന്നത്. ദീർഘകാലത്തെ ശൃംഖലയിൽ, ഏതെങ്കിലും ഒരു കാലത്തോ, സമയത്തോ ഉള്ള ഒരു നിവേദകൻ മാത്രം നിവേദനം ചെയ്തിട്ടുള്ളത്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 108, 'paragraph', 'മശ്ഹൂർ, അസീസ്, ഗരീബ് ഹദീസുകൾ നിവേദകരുടെ എണ്ണത്തെ മാത്രം ആശ്രയിച്ചുള്ള വിഭജനമാണെന്നു വ്യക്തമാണ്. പ്രവാചകന്റെ സഹചാരികൾ കഴിഞ്ഞ് രണ്ട് തലമുറകൾക്കു മാത്രമേ ഈ ദശ ബാധകമാവുകയുള്ളൂ. അതായത്, സഹചാരികളുടെ അനുചരന്മാരുടെ കാലവും അവരുടെ അനുചരന്മാരുടെ കാലവും (താബിഊൻ, താബിഉത്താബിഈൻ) ആണ് ഇത് ഉൾക്കൊള്ളുന്നത്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 109, 'list_item', '4. മുഅല്ലഖ് (നിരവലംബം) ഒരു ഹദീസിന്റെ അന്ത്യ നിവേദകൻ (ഗ്രന്ഥകാരനോട് സമീപിച്ചയാൾ) അജ്ഞാതനായിട്ടുള്ളത്. കണ്ണികൾ വിട്ടുപോയത്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 110, 'list_item', '5. മുർസൽ (സ്വഹാബിയെ വിട്ടത്) ആദ്യ നിവേദകൻ (പ്രവാചകന്റെ സഹചാരി) അജ്ഞാതനായത്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 111, 'list_item', '6. മുൻഖത്തിഅ് (വിച്ഛിന്നം) ആദ്യാന്ത്യങ്ങളൊഴിച്ചുള്ള നിവേദകരിൽ ഒന്നോ അതിലധികമോ പേർ വിവിധ സ്ഥലങ്ങളിൽ അജ്ഞാതം.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 112, 'list_item', '7. മുഅ്ള്വൽ (പ്രശ്നാർഹം) ഏതെങ്കിലും തുടർച്ചയായ രണ്ടു നിവേദകരുടെ അഭാവം.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 113, 'list_item', '8. മൗള്വൂഅ് (കൽപിതം) കളവുണ്ടാക്കിപ്പറയുന്നയാൾ നിവേദനം ചെയ്തത്. വിശ്വാസ്യതയിൽ ഏറ്റവും താണ പടിയിലാണ് അവ സ്ഥിതിചെയ്യുന്നത്.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 114, 'list_item', '9. മത്റൂക്ക് (ഒഴിവാക്കപ്പെടേണ്ടത്) നിവേദകർ ഇതര കാര്യങ്ങളിൽ അസത്യ വാദികളായി അറിയപ്പെട്ടവർ.', null, '59' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 115, 'list_item', '10. മുൻകർ (അജ്ഞാതം- അസ്വീകാര്യം) നിവേദനം ചെയ്യുന്ന കാര്യത്തിൽ അശ്രദ്ധയോ തെറ്റോ കാണിച്ചിട്ടുള്ളത്.', null, '59' from articles where volume_id=1 and section_no=5;
