insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 119, 'paragraph', 'മറ്റു റിപ്പോർട്ടർമാരുടെ നിവേദനത്തിനു വിരുദ്ധമായി ഒരു റിപ്പോർട്ടർ നിവേദനം ചെയ്തത്.', null, '60' from articles where volume_id=1 and section_no=5;
