insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 121, 'paragraph', 'നിവേദക പരമ്പര അവിച്ഛിന്നമായും ദോഷരഹിതമായും പ്രവാചകൻ വരെ എത്തിയിട്ടുള്ളത്.', null, '60' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 122, 'subheading', '14. മൗഖൂഫ് (സ്തംഭിതം)', null, '60' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 123, 'paragraph', 'നിവേദക പരമ്പര പ്രവാചകന്റെ സ്വഹാബി വരെ മാത്രം എത്തുന്നത്.', null, '60' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 124, 'subheading', '15. മഖ്ത്വൂഅ് (വിച്ഛേദ്യം - പിഴച്ചത്)', null, '60' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 125, 'paragraph', 'ഇത്തരം ഹദീസുകൾ സ്വഹാബികളുടെ പിൻഗാമി (താബിഅ്) വരെ മാത്രമേ എത്തുകയുള്ളൂ.', null, '60' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 126, 'subheading', '16. മുത്തസിൽ (അവിച്ഛിന്നം)', null, '60' from articles where volume_id=1 and section_no=5;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 127, 'paragraph', 'നിവേദക പരമ്പരയിൽ കണ്ണികൾക്കൊന്നിനും തന്നെ കേടുപാടുകൾ കൂടാതെ പ്രവാചകൻ വരെ എത്തുന്നു. അതായത്, അവിച്ഛിന്നമായ സനദുകൾ ഉള്ള ഹദീസുകൾ.', null, '60' from articles where volume_id=1 and section_no=5;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 6, 'പ്രധാന ഹദീസ് ഗ്രന്ഥങ്ങളും കർത്താക്കളും', '61', '62');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'subheading', 'ഇമാം ബുഖാരി(റ)', null, '61' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'മുഹമ്മദുബ്നു ഇസ്മാഈൽ. ഹി: 194 ൽ ബുഖാറയിലാണ് ഇമാം ബുഖാരി(റ) ജനിച്ചത്. ഹദീസുകളിൽ സാമാന്യം പരിജ്ഞാനമുണ്ടായിരുന്ന അദ്ദേഹത്തിന്റെ പിതാവ് ചെറുപ്പത്തിൽ മരണപ്പെട്ടു. ശാരീരികമായി ദുർബ്ബലനായിരുന്ന ഇമാം അപാരമായ ഓർമ്മശക്തിയും ബുദ്ധിയുമുള്ള പ്രതിഭാശാലിയായിരുന്നു. കാര്യങ്ങളെ സൂക്ഷ്മമായി വിശകലനം ചെയ്യാൻ ഇമാം ബുഖാരിക്ക് ചെറുപ്പത്തിലേ കഴിയുമായിരുന്നു. പതിനൊന്നാം വയസ്സിൽ ഹദീസ് പഠനം തുടങ്ങി. ആറുവർഷം കൊണ്ട് കിട്ടാവുന്നിടത്തോളം ഹദീസുകൾ സമാഹരിച്ചു. തുടർന്ന് മക്കയിലേക്ക് ഹജ്ജിനു പുറപ്പെട്ടു. ഹദീസ് അന്വേഷിച്ചുള്ള യാത്രയായിരുന്നു 40 വർഷം. ഹദീസുകൾ തേടിയുള്ള ഈ യാത്രയിൽ അന്നത്തെ മുസ്ലിം ലോകത്തിലെ ഏതാണ്ടെല്ലാ സ്ഥലങ്ങളും അദ്ദേഹം സന്ദർശിച്ചു. വിശ്വസനീയമായ അധരങ്ങളിൽ നിന്നും, ഏടുകളിൽ നിന്നും തിരുവചനങ്ങൾ നേരിട്ട് സമാഹരിക്കുകയായിരുന്നു ഇമാം. ജീവിതാവസാനം നൈസാബൂരിൽ താമസമാക്കാനാഗ്രഹിച്ചെങ്കിലും അവിടത്തെ ഗവർണ്ണറുടെ ഇംഗിതത്തിനു വഴങ്ങാത്തതിനാൽ അവിടം വിടേണ്ടിവന്നു. തുടർന്ന് സമർഖന്തിൽ താമസമാക്കി. 62 ാം വയസ്സിൽ ഹി: 257 ൽ വഫാതായി.', null, '61' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'ഭക്തിയും സത്യസന്ധതയും പാവങ്ങളോടും വിദ്യാർത്ഥികളോടുമുള്ള ഔദാര്യവും ജീവിതത്തിലുടനീളം കാത്തുസൂക്ഷിച്ച ഇമാം ബുഖാരി(റ) ഹദീസ് സമാഹരണത്തിനും സംശോധനയ്ക്കുമാണ് ജീവിതം നീക്കിവെച്ചത്. ഒരു സംഭവം ഹദീസ് അന്വേഷിച്ചു നൂറുകണക്കിനു മൈലുകൾ താണ്ടി അവസാനം ലക്ഷ്യസ്ഥാനത്തെത്തി. ഹദീസ് വക്താവിന്റെ വീട്ടുവാതിൽക്കലെത്തിയപ്പോൾ ഒഴിഞ്ഞ ഭക്ഷണ സഞ്ചി കാണിച്ച് കുറച്ചുദൂരെ മേയുകയായിരുന്ന കുതിരയെ വിളിക്കുന്നതുകണ്ട അയാൾ വിശ്വാസയോഗ്യനല്ല എന്നു മനസ്സിലാക്കി ഒരു നിമിഷം പോലും നിൽക്കാതെ ഇമാം സ്ഥലം വിട്ടു.', null, '61' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'ഏറ്റവും വിശ്വാസയോഗ്യവും ആധികാരികവുമായ ഹദീസ് സമാഹാരമാണ് സ്വഹീഹുൽ ബുഖാരി. തീർച്ചയായും ഏറ്റവും നിശിതമായി ഹദീസ് പരിശോധന നടത്തിയത് ഇമാം ബുഖാരി തന്നെയാണ്. 6,00000 ഹദീസുകളിൽ നിന്നാണ് ഇമാം ബുഖാരി 7275 ഹദീസുകൾ തെരഞ്ഞെടുത്തത്. 22,000 ഹദീസുകൾ അദ്ദേഹത്തിന്റെ ഓർമ്മയിലുണ്ടായിരുന്നു. വുളു ചെയ്ത് നിസ്കരിച്ച ശേഷമാണ് അദ്ദേഹം ഓരോ ഹദീസും എഴുതി വെച്ചത്, കണിശമായ പരിശോധനക്കു ശേഷം മാത്രം. അനിവാര്യമായിടത്ത് ഹദീസിന്റെ വ്യാഖ്യാനവും നൽകി. എല്ലാ നിവേദകരും വിശ്വാസയോഗ്യരും, എല്ലാവരും ഒരറ്റം മുതൽ മറ്റേയറ്റം വരെയുള്ള കണ്ണികളെ നേരിട്ടു കണ്ടതാണെന്നും ഉറപ്പിച്ച ശേഷമേ അദ്ദേഹം ഹദീസ് സ്വീകരിക്കുമായിരുന്നുള്ളൂ. ഖുർആന് വ്യാഖ്യാനമായി വന്ന ഹദീസുകൾക്ക് ആ ഖുർആൻ ഭാഗം ശീർഷകമായി കൊടുത്തത് ഇമാം ബുഖാരിയുടെ പ്രത്യേകതയാണ്.', null, '61' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', '6,00000 ഹദീസുകളിൽ നിന്നാണല്ലോ 7275 ഹദീസുകൾ ബുഖാരി തെരഞ്ഞെടുത്തത്. ഇതിനർത്ഥം 592725 ഹദീസുകൾ രേഖപ്പെടാതെ പോയി എന്നല്ല, ഒരേ ഹദീസ് തന്നെ വ്യത്യസ്തരായ ആറു നിവേദക പരമ്പരയിലൂടെ വന്നാൽ അത് ആറു ഹദീസായാണു പരിഗണിക്കുക. നിവേദകരുടെ എണ്ണത്തിനനുസരിച്ച് ഹദീസിന്റെയും എണ്ണം വർദ്ധിക്കുന്നു. ഒരേ ഹദീസ് തന്നെ വ്യത്യസ്ത വിഷയങ്ങൾക്കായി ഉദ്ധരിച്ചിട്ടുമുണ്ടാവും. അതിനാൽ 6,00000 നിവേദക പരമ്പരയിലൂടെയാണു 7275 ഹദീസുകൾ നമുക്ക് ലഭിച്ചത്. ഇത് ഹദീസിന്റെ വിശ്വാസ്യതയുടെ മാറ്റു വർദ്ധിപ്പിക്കുകയാണു ചെയ്യുന്നത്. ഒരേ ഹദീസ് വിവിധ ശീർഷകങ്ങൾക്കു താഴെ വന്നതും കാണാം. ഇങ്ങനെ നോക്കുമ്പോൾ വ്യതിരിക്തതയുള്ള ഹദീസുകളുടെ എണ്ണം പിന്നെയും ചുരുങ്ങുന്നു. അവ ബുഖാരിയിൽ 2762 ആയി കുറയുന്നു.', null, '61' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'ഖുർആൻ കഴിഞ്ഞാൽ ഏറ്റവും ആധികാരികമായ ഇസ്ലാമിക പ്രമാണം ഹദീസ് ആണെന്നിരിക്കെ അവ ക്രോഡീകരിക്കപ്പെട്ട ഗ്രന്ഥങ്ങളിൽ സ്വഹീഹുൽ ബുഖാരി പ്രഥമ സ്ഥാനത്തായി പരിഗണിക്കപ്പെടുന്നു.', null, '61' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'subheading', 'ഇമാം മുസ്‌ലിം(റ)', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'paragraph', 'അബുൽ ഹസൻ മുസ്‌ലിം ഇബ്‌നുൽ ഹജ്ജാജ് അൽ ഖുറൈശി എന്നാണ് മുഴുവൻ പേര്. ഹി:204 (ക്രി.വ: 817) ൽ ബുഖാറക്കടുത്ത നിശാപൂരിൽ, ഖുറാസാനിലെ കുലീനരായ അറബ് മുസ്‌ലിംകളുടെ കുടുംബത്തിൽ ജനിച്ചു. നാലു ഖലീഫമാരുടെ ഭരണകാലത്ത് അദ്ദേഹത്തിന്റെ പ്രപിതാക്കൾ സുപ്രധാന സ്ഥാനങ്ങൾ വഹിച്ചിരുന്നു. മുഹദ്ദിസ് കൂടിയായിരുന്ന പിതാവിൽ നിന്ന് ഇമാം മുസ്‌ലിമിന് അളവറ്റ ധനം അനന്തരാവകാശമായി ലഭിച്ചു. വിവിധ വിജ്ഞാന കേന്ദ്രങ്ങളിലെ പഠനം പൂർത്തയാക്കിയ ശേഷം ഇമാം മുസ്‌ലിം ഹദീസുകൾ അന്വേഷിച്ചിറങ്ങി. അവസാനം നിശാപൂരിൽ (നൈസാബൂർ) താമസമാക്കി. ശിഷ്ടകാലം ഹദീസ് തരംതിരിക്കുന്നതിനും പഠിപ്പിക്കുന്നതിനും ചെലവഴിച്ചു. ഹി:261 ൽ (ക്രി.വ:874 ൽ) വഫാതായി.', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'paragraph', 'ആധികാരികതയിലും വിശ്വാസ്യതയിലും സ്വഹീഹുൽ ബുഖാരിക്കുശേഷം സ്വഹീഹു മുസ്‌ലിം പരിഗണിക്കപ്പെടുന്നു. ബുഖാരിയും മുസ്‌ലിമും ഒന്നിച്ചു സ്വീകരിച്ച ഹദീസിനെ മുത്തഫഖുൻ അലൈഹി (ബുഖാരിയും മുസ്‌ലിമും യോജിച്ചത്) എന്നു വിളിക്കുന്നു. ഹദീസുകളുടെ ക്രമീകരണത്തിലെ വിശദാംശങ്ങൾ പരിഗണിക്കുമ്പോൾ ബുഖാരിയേക്കാൾ സ്വഹീഹു മുസ്‌ലിം മികച്ചുനിൽക്കുന്നതായി കാണാം. 300,000 ഹദീസുകളിൽ നിന്നും തെരഞ്ഞെടുത്ത 9200 ഹദീസുകളാണു സ്വഹീഹു മുസ്‌ലിമിലുള്ളത്. മുസ്‌നദു കബീർ, ജാമിഉൽ കബീർ, കിതാബുൽ മിലൽ തുടങ്ങിയ മറ്റു കൃതികളും ഇമാം മുസ്‌ലിമിന്റേതായുണ്ട്.', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'subheading', 'അബൂദാവൂദ്(റ)', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'paragraph', '(ജനനം ഹി:203, മരണം 275) അറേബ്യയിലെ ബനൂഅസദ് വംശജൻ. ഖുറാസാനിൽ നിന്നും ഹദീസ് സാഹിത്യത്തിൽ വിദ്യാഭ്യാസം കരസ്ഥമാക്കിയ അബൂദാവൂദ് ഹദീസ് കേന്ദ്രങ്ങളിൽ പോയി അവ പഠിക്കുകയും സമാഹരിക്കുകയും ചെയ്തു. സൻകികൾ ഖുറാസാൻ നഗരം തകർത്തപ്പോൾ ജനം അവിടം വിട്ടുപോയി. ജനങ്ങൾ അങ്ങോട്ടു തിരിച്ചുവരാൻ സേനാനായകനായ അൽ മുവാഫിക് ജനങ്ങളെ ആകർഷിക്കുന്നതിനു വേണ്ടി അദ്ദേഹത്തെ അവിടത്തന്നെ പാർപ്പിക്കുകയുണ്ടായി. അത്രയേറെ പ്രശസ്തനും, സ്വീകാര്യനുമായിരുന്നു അദ്ദേഹം. അബൂദാവൂദ് ആ അഭ്യർത്ഥന സ്വീകരിച്ചു. എന്നാൽ സേനാപതിയുടെ മകനെ സ്വകാര്യമായി പഠിപ്പിക്കാനുള്ള ക്ഷണം നിരസിച്ചു.', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'paragraph', 'രാജകുമാരനും ദരിദ്ര വിദ്യാർത്ഥികൾക്കുമിടയിൽ വിവേചനം കൽപിച്ചുകൊണ്ട് വിജ്ഞാനത്തെ തരംതാഴ്ത്താൻ തയ്യാറില്ലെന്ന് അബ്ബാസി ജനറലും സ്വഫവ്വിദ് സ്ഥാപകനുമായ സേനാധിപതിയോട് പറഞ്ഞു. ധാരാളം ഹദീസ്, ഇസ്‌ലാമിക നിയമകൃതികൾ അബൂദാവൂദിന്റേതായുണ്ട്. അതിൽ ഏറ്റവും പ്രശസ്തമായത് ഹദീസ് സമാഹാരമായ ''സുനൻ'' ആണ്. സ്വഹീഹുൽ ബുഖാരിയും, സ്വഹീഹു മുസ്‌ലിമും കഴിഞ്ഞാൽ ഏറ്റവും ആധികാരികമായി പരിഗണിക്കുന്നത് അബൂദാവൂദിന്റെ ''സുനൻ'' ആണ്. 500,000 ഹദീസുകളിൽ നിന്നും തെരഞ്ഞെടുത്തത് 4,800 ഹദീസുകളാണ‌് ഇതിന് 20 വർഷം വേണ്ടിവന്നു. ''മുസ്‌നദ്'' എന്ന മറ്റൊരു ഹദീസ് സമാഹാരവും അബൂദാവൂദിനുണ്ട്.', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'subheading', 'തുർമുദി(റ)', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'paragraph', 'സ്വിഹാഹുസ്സിത്തയിൽ നാലാമതായി വരുന്ന ഹദീസ് സമാഹാരം തുർമുദി(റ)വിന്റേതാണ്. നിവേദകരുടെ പേരുകളുടെ അടയാളങ്ങൾ നിശ്ചയിക്കുകയും, ഓരോ ഹദീസിനും പ്രത്യേക പേരു നൽകി നിവേദകരുടെ പദവി നിശ്ചയിക്കുകയും ചെയ്ത് ആദ്യമായി ഹദീസ് സമാഹരിച്ചത് തിർമിദി(റ)വാണ്. ഹി:209 ൽ ജനിച്ചു, 274 ൽ വഫാതായി.', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'subheading', 'നസാഈ(റ)', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'paragraph', 'അബു അബ്ദുർറഹ്മാൻ അഹ്‌മദ് അന്നസാഈ എന്നാണ് മുഴുവൻ പേര്. (ജനനം: ഹി: 214, വഫാത്: 303) ഒരു നല്ല ഹദീസ് സമാഹാരമായാണ് നസാഇയുടെ സുനൻ പരിഗണിക്കപ്പെടുന്നത്. സ്വിഹാഹുസ്സിത്തയിൽ അഞ്ചാമത് വരുന്നത് നസാഇയുടെ ''സുനൻ'' ആണ്. തന്റെ സമാഹാരത്തിൽ ധാരാളം ദുർബ്ബലവും, സംശയകരവുമായ ഹദീസുകളുണ്ടെന്ന് അദ്ദേഹം തന്നെ സമ്മതിച്ചിട്ടുണ്ട്.', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'subheading', 'ഇബ്‌നു മാജഃ(റ)', null, '62' from articles where volume_id=1 and section_no=6;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 18, 'paragraph', 'മുഹമ്മദുബ്നു യസീദ് എന്ന് പൂർണ്ണനാമം. സ്വിഹാഹുസ്സിത്തയിൽ ആറാമത്തെ സമാഹാരം ഇബ്‌നു മാജയുടേതാണ്. ഹദീസ് അന്വേഷിച്ച് അദ്ദേഹം അന്നത്തെ വൈജ്ഞാനിക കേന്ദ്രങ്ങളായിരുന്ന ബസ്വറ, കൂഫ, ബഗ്ദാദ്, മക്ക, സിറിയ, ഈജിപ്ത് തുടങ്ങിയ സ്ഥലങ്ങൾ സന്ദർശിച്ചു. ഹി: 209 ൽ ജനിച്ചു, 295 ൽ വഫാതായി.', null, '62' from articles where volume_id=1 and section_no=6;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 7, 'ചില പ്രധാന ഹദീസ് നിവേദകർ', '63', '70');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'list_item', '1. അഖ്റളബ്നു ഹാബിസ്(റ): മക്കാ വിജയ കാലത്ത് ഇസ്ലാം സ്വീകരിച്ചു. നബി(സ)യിൽ നിന്നും, അവിടുത്തെ അനുചരന്മാരിൽ നിന്നും ഹദീസ് ഹൃദിസ്ഥമാക്കി. മക്കാ വിജയ ദിവസം തമീം ഗോത്രത്തിന്റെ പ്രതിനിധിയായി വന്നു. ഗവർണ്ണർ അബ്ദുല്ലാഹിബ്നു ആമിർ ഖുറാസാനിലേക്കയച്ച ഒരു സേനയുടെ നായകത്വം ഇദ്ദേഹത്തിനായിരുന്നു.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'list_item', '2. അദിയ്യുബ്നു ഹാതിം(റ): ലോക പ്രശസ്ത ഔദാര്യവാനായ ഹാതിമുത്വാഇയുടെ പുത്രൻ. ഹാതിം - ത്വയ്യ് ഗോത്രത്തിന്റെ അധിപനായിരുന്നു. ഹാതിമിന്റെ മകൻ അദിയ്യ് അദ്ദേഹത്തിന്റെ പിൻഗാമിയായി വന്നു. അലി(റ)വിന്റെ കീഴിലുള്ള മുസ്ലിം സേന ത്വയ്യുകാരെ തോൽപിച്ചു. അവർ സിറിയയിലേക്ക് പലായനം ചെയ്തു. അദിയ്യിന്റെ സഹോദരി ബന്ധിയായി പ്രവാചക സന്നിധിയിൽ ഹാജരാക്കപ്പെട്ടു. നബി(സ) അവരെ വിശിഷ്ട സമ്മാനങ്ങൾ നൽകി ആദരപൂർവം തിരിച്ചയച്ചു. പ്രവാചകർ(സ)യുടെ ഈ ഉദാര നടപടി അദിയ്യിന്റെ മനംകവർന്നു. അദ്ദേഹം ഇസ്ലാം സ്വീകരിച്ചു. അലി(റ)വിന്റെ പക്ഷക്കാരനായിരുന്ന അദിയ്യ് അദ്ദേഹത്തിനുവേണ്ടി ധീരമായി ഒട്ടേറെ യുദ്ധങ്ങളിൽ പോരാടി. തുടർന്ന് കൂഫയിൽ താമസമാക്കി. ഹി: 68 ൽ 120 ാം വയസ്സിൽ നിര്യാണം.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'list_item', '3. അനസുബ്നു മാലിക്(റ): പ്രശസ്ത ഹദീസ് നിവേദകൻ. ഒട്ടേറെ ഹദീസുകൾ നിവേദനം ചെയ്തു. പ്രവാചകർ(സ)യുടെ പ്രത്യേക പരിചാരകൻ. പ്രവാചകൻ(സ) മദീനയിലേക്ക് ഹിജ്റ പോകുമ്പോൾ പത്ത് വയസ്സു പ്രായം. തുടർന്ന് പത്ത് വർഷം പ്രവാചകർ(സ)ക്ക് സേവനം ചെയ്തു. ഈ കാലയളവിലൊരിക്കലും പ്രവാചകർ(സ) അദ്ദേഹത്തെ ആക്ഷേപിച്ചിട്ടില്ലെന്നു മൊഴിനൽകുന്നു. ജനങ്ങളെ ഹദീസ് പഠിപ്പിക്കുന്നതിനും മറ്റുമായി ബസ്വറയിലേക്ക് താമസം മാറ്റി. ഉമർ(റ)വിന്റെ ഭരണ കാലത്ത് ശിഷ്ടകാലം അവിടെ കഴിച്ചുകൂട്ടി. ഹി: 91 ൽ 103 ാം വയസ്സിൽ നിര്യാണം.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'list_item', '4.അബൂ അയ്യൂബിൽ അൻസ്വാരി (ഖാലിദ് ഇബ്നു സൈദ് അൻസ്വാരി അൽ ഖസ്റജി)(റ): മക്കയിൽ നിന്നു ശത്രുക്കളുടെ ഉപദ്രവം സഹിക്കവയ്യാതെ മദീനയിലേക്കു പലായനം ചെയ്തു. നബി(സ) ഇദ്ദേഹത്തിന്റെ വീട്ടിലാണ് സ്വന്തം വീടു പണിയുന്നതുവരെ താമസിച്ചത്. മറ്റാർക്കും ഈ ബഹുമതി ലഭിച്ചില്ല. പ്രവാചകർ(സ)യുടെ കൂടെ എല്ലാ യുദ്ധങ്ങളിലും പങ്കെടുത്തു. ഹി: 51-ലാണ് അദ്ദേഹം നിര്യാതനായത്. തന്റെ അന്ത്യാഭിലാഷമനുസരിച്ച് കോട്ടയുടെ അടിഭാഗത്തായിരുന്നു അദ്ദേഹത്തിന്റെ മയ്യിത്ത് ഖബറടക്കിയത്. തുർക്കി ഭരണാധികാരി സുൽത്താൻ മുഹമ്മദ് രണ്ടാമൻ കോൺസ്റ്റാന്റിനോപ്പിൾ കീഴടക്കിയപ്പോൾ അൻസ്വാരി(റ)യുടെ മഖ്ബറ കണ്ടെത്തുകയും അദ്ദേഹത്തിന്റെ മഖ്ബറക്കരികെ വലിയൊരു പള്ളി പണിയുകയും ചെയ്തു. ഇത് ''മസ്ജിദ് അബൂ അയ്യൂബ്'' എന്നറിയപ്പെടുന്നു. പ്രവാചകർ(സ)യിൽ നിന്ന് ധാരാളം ഹദീസുകൾ അദ്ദേഹം ഉദ്ധരിച്ചിട്ടുണ്ട്.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'list_item', '5.അബൂ ഉമാമത്തുൽ ബാഹിലി(റ): ഈജിപ്ത് നിവാസിയായിരുന്നു. പിന്നീട് സിറിയയിലെ ഹിംസിലേക്ക് താമസം മാറ്റി. അനേകം ഹദീസുകൾ ഇദ്ദേഹത്തിൽ നിന്ന് ഉദ്ധരിക്കപ്പെട്ടിട്ടുണ്ട്. ഹി: 86 ൽ 91 ാം വയസ്സിൽ നിര്യാതനായി. ഹിംസിലാണ് ഖബറടക്കം. നബി(സ)യുടെ സിറിയയിലെ അനുചരന്മാരിൽ ഏറ്റവും അവസാനം മരിച്ചത് അബൂ ഉമാമ(റ)വാണ്.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'list_item', '6.അബൂ ഉസൈദ് അൻസ്വാരി(റ): നബി(സ)യോടൊപ്പം എല്ലാ യുദ്ധങ്ങളിലും പങ്കെടുത്തു. ഹി: 60ൽ 78 ാം വയസ്സിൽ അന്തരിച്ചു. ബദ്ർ യുദ്ധത്തിൽ പങ്കെടുത്തവരിൽ ഏറ്റവും അവസാനം മരണപ്പെട്ടത് ഇദ്ദേഹമാണ്. വാർദ്ധക്യകാലത്തു കാഴ്ച നഷ്ടപ്പെട്ടു.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 7, 'list_item', '7.അബൂബക്കർ സിദ്ദീഖ് (അബ്ദുല്ലാഹിബ്നു ഉസ്മാൻ അബൂഖുഹാഫ)(റ): നബി(സ)യുടെ പ്രഥമ അനുചരനും, സന്തതസഹചാരിയും, പ്രഥമ ഖലീഫയുമായിരുന്നു. പുരുഷന്മാരിൽ നിന്ന് ആദ്യമായി ഇസ്ലാം സ്വീകരിച്ചത് അബൂബക്കർ(റ)വായിരുന്നു. മക്കയിൽ ജനിച്ചു. മദീനയിൽ അറുപത്തിമൂന്നാം വയസ്സിൽ വഫാതായി. അബൂബക്കർ(റ)വിന് നബി(സ) ''സിദ്ദീഖ്'' (സത്യസന്ധൻ) എന്ന ബഹുമതി നൽകി.', null, '63' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 8, 'list_item', '8. അബൂഥഅ്‌ലബ(റ): ബൈഅതുർറിള്‌വാൻ വേളയിൽ ഇസ്‌ലാം സ്വീകരിച്ചു. തുടർന്ന് സ്വന്തം ഗോത്രത്തിലേക്ക് ഇസ്‌ലാമിക പ്രബോധനത്തിനയക്കപ്പെട്ടു. തത്ഫലമായി ഗോത്രക്കാരെല്ലാം ഇസ്‌ലാം സ്വീകരിച്ചു. എഴുപത്തിഅഞ്ചിൽ നിര്യാണം.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 9, 'list_item', '9. അബൂദർറുൽ ഗിഫാരി/ജുൻദുബുബ്നു ജുനാദ(റ): ''ഖാഇമുൽ ഖുർആൻ'' എന്ന് അപരനാമം. മുഹാജിർ, പ്രമുഖ സ്വഹാബി, അതീവ ഭക്തൻ, പരിത്യാഗി. ഇസ്‌ലാം സ്വീകരിക്കുന്നതിനു മുമ്പുതന്നെ അബൂദർറ്(റ) ഭയ ഭക്തിയിലും, അർപ്പണ ബോധത്തിലും പ്രസിദ്ധനായിരുന്നു. സ്വന്തം ഗോത്രത്തിൽ ഇസ്‌ലാം പ്രബോധനം ചെയ്തു. ദമസ്‌കസിൽ താമസമാക്കി. ഖലീഫ ഉസ്മാൻ(റ)വിന്റെ കാലത്ത് മദീനയിലെ പ്രാന്തപ്രദേശമായ റബ്ദയിൽ ഏകാന്തവാസം വിധിക്കപ്പെട്ടു. അവിടെ നിര്യാണം. ഒട്ടേറെ സ്വഹാബിമാരും താബിഉകളും അബുദർറ്(റ)വിൽ നിന്ന് ഹദീസ് കേട്ടു. ആദ്യമായി ഇസ്‌ലാമിന്റെ അഭിവാദ്യമായ സലാം ഇദ്ദേഹത്തിനാണ് നബി(സ) പറഞ്ഞത്.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 10, 'list_item', '10. അബൂത്വൽഹ(റ): സ്വർഗ്ഗപ്രവേശ സന്തോഷ വാർത്തയറിയിക്കപ്പെട്ട പത്തു സ്വഹാബികളിൽ ഒരാൾ. യുദ്ധ വീരൻ, വില്ലാളി. ഒരുകൂട്ടം പോരാളികളേക്കാൾ ഫലപ്രദമായിരുന്നു അദ്ദേഹത്തിന്റെ സമരഗർജ്ജനമെന്ന് നബി(സ) പറഞ്ഞിട്ടുണ്ട്. അഖബാ ഉടമ്പടിയിൽ പങ്കെടുത്ത പതിനേഴ് മദീനക്കാരിൽ ഒരാൾ. എഴുപത്തിഏഴാം വയസ്സിൽ ഹി: മുപ്പത്തിഒന്നിൽ ബസ്വറയിൽ നിര്യാണം.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 11, 'list_item', '11. അബൂവാഖിദുല്ലൈസി/ഹാരിസ് ഇബ്നു ഔഫുബ്നു അസീദുല്ലൈസി(റ): മദീനയിലെ ആദ്യ വിശ്വാസികളിലൊരാൾ. ഒരു വർഷം മക്കയിൽ താമസിച്ചു. ഹി: അറുപത്തിഎട്ടിൽ എഴുപത്തഞ്ചാം വയസ്സിൽ വഫാത്.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 12, 'list_item', '12. അബൂഹുറൈറ(റ): പൂച്ചയോട് വലിയ ഇഷ്ടമായിരുന്നതിനാൽ ''അബൂഹുറൈറ'' (പൂച്ചക്കാരൻ) എന്ന പേരുകിട്ടി. പേര്, കുടുംബം എന്നിവയെക്കുറിച്ച് ഒട്ടേറെ അഭിപ്രായങ്ങളുണ്ട്. ജാഹിലിയ്യാ കാലത്ത് അബ്ദുശ്ശംസ് എന്നായിരുന്നു പേര്. ഇസ്‌ലാം സ്വീകരിച്ചപ്പോൾ അബ്ദുല്ല എന്നോ, അബ്ദുറഹ്മാൻ എന്നോ പേരു സ്വീകരിച്ചു. ഖൈബർ ഉപരോധ കാലത്ത് ഇസ്‌ലാം സ്വീകരിച്ചു. തുടർന്ന് നബി(സ)യുടെ സന്തത സഹചാരിയായി. ഒരു നിഴൽപോലെ എപ്പോഴും നബി(സ)യോടൊപ്പമുണ്ടാകും. അത്ഭുതാവഹമായ ഓർമ്മശക്തി അബൂഹുറൈറ(റ)യുടെ പ്രത്യേകതയായിരുന്നു. ഏറ്റവും കൂടുതൽ ഹദീസ് നിവേദനം ചെയ്ത സ്വഹാബി ഇദ്ദേഹമാണ്. എണ്ണൂറിലേറെ സ്വഹാബികളും അനുയായികളും അദ്ദേഹത്തിൽ നിന്ന് ഹദീസ് കേട്ടതായി ഇമാം ബുഖാരി പറയുന്നു. തൊട്ടടുത്തു നിന്നിരുന്നത് ഇബ്നു അബ്ബാസ്(റ), ഇബ്നു ഉമർ(റ), ജാബിർ(റ), ആഇശ(റ) എന്നിവരാണ്. 75 ാം വയസ്സിൽ ഹി:59 ൽ വഫാതായി.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 13, 'list_item', '13. അബ്ദുറഹ്മാൻ ഇബ്നു ജാബിർ(റ): ബദ്റിൽ പങ്കെടുത്തു. ഹി:34 ൽ, 70 ാം വയസ്സിൽ വഫാത്. ജന്നതുൽ ബഖീഇൽ ഖബറടക്കി.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 14, 'list_item', '14. അബ്ദുല്ലാഹിബ്നു അബൂബക്കർ സിദ്ദീഖ്(റ): ആദ്യകാല മുസ്ലിംകളിലൊരാൾ. ത്വാഇഫിൽ ഹി:11 ാം വർഷം പിതാവി(അബൂബക്കർ സിദ്ദീഖ്)ന്റെ ഖിലാഫത്തു കാലത്ത് രക്തസാക്ഷിയായി.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 15, 'list_item', '15. അബ്ദുല്ലാഹിബ്നു സുബൈറുബ്നുൽ അവ്വാം(റ): മദീനയിലെ ഖുബാ മസ്ജിദിൽ ജനനം. ഹിജ്റക്കു ശേഷം ആദ്യം ജനിച്ച കുട്ടി. കാരക്ക കൊണ്ട് മധുരം നൽകിയത് നബി(സ)യായിരുന്നു. ഇദ്ദേഹത്തിന്റെ വയറ്റിൽ ആദ്യമായി എത്തിയത് നബി(സ)യുടെ ഉമിനീരാണ്. നബി(സ) അബ്ദുല്ല എന്നു പേരിട്ടു. നബി(സ)യിൽ നിന്നും സ്വഹാബികളിൽ നിന്നും ധാരാളം ഹദീസുകൾ നിവേദനം ചെയ്തു. വൃത്തി വളരെ ഇഷ്ടപ്പെട്ടിരുന്ന അദ്ദേഹം പരിശുദ്ധമായി ജീവിച്ചു. അബൂബക്കർ(റ) മകൾ അസ്മാഅ്(റ)യുടെ പുത്രൻ. ഹസൻ(റ)വിന്ന് ശേഷം ഹി: 64 ാം വർഷം സ്വയം ഖലീഫയായി പ്രഖ്യാപിച്ചു. ഭൂരിഭാഗം മുസ്‌ലിംകളും അദ്ദേഹത്തിനു ബൈഅത്ത് ചെയ്തു. അമവി ഭരണാധികാരികളിൽ ക്രൂരനായിരുന്ന മാലികുബ്നു മർവാന്റെ ഗവർണർ ഹജ്ജാജുബ്നു യൂസുഫ് മക്ക കീഴടക്കി അദ്ദേഹത്തെ വധിച്ചു. ഹി:73 ാം വർഷമാണു സംഭവം.', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 16, 'list_item', '16. അബ്ദുല്ലാഹിബ്നു ഉമറുബ്നുൽ ഖത്വാബ്(റ): നുബുവ്വത്തിന് ഒരു വർഷം മുമ്പ് ജനനം. കുട്ടിയായിരിക്കെ പിതാവിനോടൊപ്പം ഇസ്‌ലാം സ്വീകരിച്ചു. പണ്ഡിതനും, ഭക്തനും, സമർപ്പിതനും, പരിത്യാഗിയും, ഭൗതികൈശ്വര്യങ്ങൾക്കു കീഴ്‌പ്പെടുത്താനാവാത്ത വ്യക്തിത്വത്തിനുടമയുമായിരുന്നു. സ്വജീവിതകാലത്ത് ആയിരത്തോളം ത്തോളം യുദ്ധ തടവുകാരെ മോചിപ്പിച്ചു. നന്നേചെറുപ്പമായിരുന്നതിനാൽ ബദ്ർ', null, '64' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 17, 'paragraph', 'യുദ്ധത്തിൽ പങ്കെടുക്കാൻ നബി(സ) അനുമതി നൽകിയില്ല. എന്നാൽ, ഖൻദഖ് യുദ്ധത്തിലും, ബൈഅത്തുർറിദ്‌വാൻ ഉടമ്പടി വേളയിലും പങ്കെടുത്തു. അമവി ഭീകരനായിരുന്ന ഹജ്ജാജിനാൽ ദാരുണമായി വധിക്കപ്പെട്ടു. നബി(സ)യോടൊപ്പം വളരെക്കാലം സഹവസിച്ച ഒരു സ്വഹാബിയെയാണ് അതുമൂലം സമൂഹത്തിന് നഷ്ടമായത്. ഹി:73 ാം വർഷം 84 ാം വയസ്സിലാണ് രക്തസാക്ഷിയായത്. മുഹസ്സബിൽ ഖബറടക്കി.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 18, 'list_item', '17. അബ്ദുല്ലാഹിബ്നു സലാമുബ്നു ഹാരിസിൽ ഇസ്രാഈലി(റ): യൂസുഫ് നബി(അ)യുടെ സന്തതിയിൽ പെട്ടവർ. ജാഹിലിയ്യാകാലത്ത് ഹുസൈൻ എന്നായിരുന്നു പേര്. മുസ്‌ലിമായപ്പോൾ നബി(സ) അബ്ദുല്ലാ എന്നു പേരിട്ടു. നബി(സ) മദീനയിലേക്ക് ഹിജ്റ പോയപ്പോഴാണ് മുസ്‌ലിമായത്. ഇദ്ദേഹത്തിൽ നിന്ന് മക്കളായ യൂസുഫ്(റ), മുഹമ്മദ്(റ) എന്നിവരും, അനസുബ്നു മാലിക്(റ)വും, സുറാറത്തുബ്നു ഔഫ(റ)വും ഹദീസ് നിവേദനം ചെയ്തിട്ടുണ്ട്. ഹി:43 ൽ വഫാതായി. മദീനയിലെ ജൂതവംശജരിൽ ഇബ്നുസലാമിനോളം പാണ്ഢിത്യമുള്ള മറ്റൊരാളുണ്ടായിരുന്നില്ല.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 19, 'list_item', '18. അബ്ദുല്ലാഹിബ്നു ജഅ്ഫർ(റ): അബൂ ത്വാലിബിന്റെ പൗത്രൻ. അസ്മാഅ് ബിൻതു യമീസിന്റെ മകൻ. അബ്‌സീനിയയിൽ ജനനം. മാന്യനും, ഉദാരനുമായ ഇദ്ദേഹം ബഹ്റുൽ ജൂദ് (ഔദാര്യത്തിന്റെ കടൽ) എന്നറിയപ്പെട്ടു. അഗാധ പണ്ഡിതനും, ഭക്തനും. അക്കാലത്തെ മുസ്‌ലിംകളിൽ ഇദ്ദേഹത്തേക്കാൾ ഉദാരനായി ആരുമുണ്ടായിരുന്നില്ല. 90 ാം വയസ്സിൽ ഹി:80 ൽ മദീനയിൽ നിര്യാണം.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 20, 'list_item', '19. അബ്ദുല്ലാഹിബ്നു അംറുബ്നുൽ ആസ്(റ): പ്രശസ്തനായ സ്വഹാബിയുടെ മകൻ. പിതാവിനും മുമ്പ് 12-13 വയസ്സുള്ളപ്പോൾ ഇസ്‌ലാം സ്വീകരിച്ചു. ഖുറൈശി ഉപഗോത്രമായ സലീം ഗോത്രക്കാരൻ. പ്രവാചക മൊഴികൾ എഴുതിവെക്കുമായിരുന്നു. ഭയഭക്തിയാലുള്ള കരച്ചിൽ കാരണം, ഭക്തനും പരിത്യാഗിയുമായിരുന്ന ഇദ്ദേഹത്തിന്റെ കാഴ്ചപോലും അവസാന കാലമാവുമ്പോഴേക്കും നഷ്ടപ്പെട്ടിരുന്നു, മരണ സമയത്തെക്കുറിച്ചു വ്യത്യസ്താഭിപ്രായമുണ്ട്. മക്കയിൽ ഹി:63 ലോ 73 ലോ വഫാത്.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 21, 'list_item', '20. അബ്ദുല്ലാഹിബ്നു മസ്ഊദ്/അബൂ അബ്ദുർറഹ്മാൻ: ആദ്യ മുസ്‌ലിംകളിൽ ആറാമത്. നബി(സ)യുടെ യാത്രകളിലെ പ്രത്യേക സഹചാരി. നബി(സ) വുളു എടുക്കുന്ന പാത്രം, അറാക്കിന്റെ ബ്രഷ്, നബി(സ)യുടെ വസ്ത്രങ്ങൾ തുടങ്ങിയവയുടെ പ്രത്യേക സൂക്ഷിപ്പുകാരൻ ഇദ്ദേഹമായിരുന്നു. ബദ്‌ർ യുദ്ധത്തിലും തുടർന്നുള്ള 25 യുദ്ധങ്ങളിലും പങ്കെടുത്തു. സ്വർഗ്ഗ പ്രവേശം കൊണ്ട് സുവിശേഷമറിയിക്കപ്പെട്ട പത്ത് പേരിലൊരാൾ ഇദ്ദേഹമായിരുന്നു. "അബ്ദുല്ലാഹിബ്നു മസ്ഊദിനു സ്വീകാര്യമായത് എന്റെ അനുയായികൾക്കും ഞാൻ സ്വീകാര്യമായി കാണുന്നു." എന്ന് നബി(സ) ഇദ്ദേഹത്തെ വാഴ്ത്തി. ആദ്യം അബ്സീനിയയിലേക്കും, പിന്നീടു മദീനയിലേക്കും പലായനം ചെയ്തു. അതിദീർഘകായനായിരുന്ന ഇദ്ദേഹത്തെ ഖലീഫ ഉമർ കൂഫയിലെ ന്യായാധിപനും അവിടുത്തെ പൊതുസ്വത്തിന്റെ സൂക്ഷിപ്പുകാരനുമാക്കി. ഉസ്മാൻ(റ)വിന്റെ കാലത്തും കൂഫയിൽ തന്നെ കഴിഞ്ഞു. പിന്നീട് മദീനയിലേക്കു മാറി. ഹി:32 ൽ 60 ാം വയസ്സിൽ വഫാത്. ജന്നത്തുൽ ബഖീഇലാണ് ഖബർ. ഖുലഫാഉർറാശിദുകളടക്കം ഒട്ടേറെ സ്വഹാബികൾ ഇദ്ദേഹത്തിൽ നിന്ന് ഹദീസ് കേട്ടു. 848 ഹദീസുകൾ ഇദ്ദേഹത്തിൽ നിന്നുദ്ധരിക്കപ്പെടുന്നു. ഇതിൽ 64 എണ്ണം ബുഖാരിയും മുസ്‌ലിമും സ്വീകരിച്ചിട്ടുണ്ട്.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 22, 'list_item', '21. അബ്ദുല്ലാഹിബ്നു മുഗഫ്ഫൽ(റ): മദീനയിൽ താമസം. പിന്നീട് ബസ്വറയിലേക്കു മാറി. ഹി:60 ൽ നിര്യാണം. ഹസനുൽ ബസ്വരി(റ) അടക്കം അനേകം താബിഉകൾ ഇദ്ദേഹത്തിൽ നിന്ന് ഹദീസുകൾ കേട്ടു.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 23, 'list_item', '22. അബ്ദുല്ലാഹിബ്നു ഹുശാമ(റ): ഹിജാസ് സ്വദേശി. ജനിച്ച ദിവസം കുട്ടിയെ നബി(സ)ക്കു കാണിച്ചു കൊടുത്തു.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 24, 'list_item', '23. അബ്ദുല്ലാഹിബ്നു യസീദ്(റ): 17 ാം വയസ്സിൽ ഹുദൈബിയയിൽ പങ്കെടുത്തു. അബ്ദുല്ലാഹിബ്നു ജാബിർ(റ)വിന്റെ കാലത്തു കൂഫാ ഗവർണ്ണറായിരുന്നു. കൂഫയിൽ വഫാതായി.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 25, 'list_item', '24. അബ്ദുല്ലാഹിബ്നു മാലിക്(റ): ഈജിപ്തിലെ താബിഅ്. ധാരാളം ഹദീസുകൾ നിവേദനം ചെയ്തു.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 26, 'list_item', '25. അബ്ദുല്ലാഹിബ്നു സൈദ്(റ): മദീനാ നിവാസി. ബദ്‌റിൽ പങ്കെടുത്തു. 64 ാം വയസ്സിൽ ഹി:32 ൽ വഫാത്.', null, '65' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 27, 'list_item', '26. അബ്ദുല്ലാഹിബ്നു അബ്ബാസ്(റ): നബി(സ)യുടെ പിതൃവ്യ പുത്രൻ. ഇദ്ദേഹത്തിന്റെ സഹോദരി മൈമൂന(റ)യെ പ്രവാചകൻ(സ) വിവാഹം ചെയ്തു. ഹിജ്റക്കു മൂന്ന് വർഷം മുമ്പു ജനിച്ചു. അതീവ പണ്ഡിതനും വാഗ്മിയുമായിരുന്ന ഇദ്ദേഹം നബി(സ)യുടെ പ്രശസ്ത സഹചാരിയും കൂടിയായിരുന്നു. ഉമർ(റ) ഇദ്ദേഹത്തോട് കൂടിയാലോചന നടത്താറുണ്ടായിരുന്നു. അലി(റ)യുടെ വലംകൈ ആയിരുന്നു ഈ മഹാൻ. 71 ാം വയസ്സിൽ ഹി:68 ൽ ത്വാഇഫിൽ വഫാതായി. ദീർഘകായനും സുന്ദരനുമായിരുന്നു. അവസാന കാലത്ത് കാഴ്ച നഷ്ടപ്പെട്ടു. കുറച്ചുകാലം കൂഫയിൽ ഗവർണ്ണറായി. അഭിപ്രായ വ്യത്യാസം കാരണം പിന്നീട് രാജി വെച്ചു.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 28, 'list_item', '27. അബ്ബാസ് ഇബ്നു അബ്ദിൽ മുത്ത്വലിബ്(റ): നബി(സ)യുടെ പിതൃവ്യൻ. ആനക്കലഹത്തിന് ഒരു വർഷം മുമ്പ് ജനനം. 88 ാം വയസ്സിൽ ഹി:32 ൽ മരണം. രണ്ടു വയസ്സിന് നബി(സ)യെക്കാൾ മുതിർന്നവൻ. ഇസ്ലാമിനു മുമ്പ് കഅ്ബയുടെ അറ്റകുറ്റപ്പണികൾ തീർക്കുക, വെള്ളം കൊടുക്കുക തുടങ്ങിയ ചുമതലകളുണ്ടായിരുന്നു. എഴുപതോളം അടിമകളെ മോചിപ്പിച്ചു. മക്കം ഫത്ഹിൽ ഇസ്‌ലാം സ്വീകരിച്ചു. ബദ്റിൽ ഖുറൈശികളോടൊപ്പമായിരുന്നു. ബന്ധിയാക്കപ്പെട്ടപ്പോൾ അദ്ദേഹത്തെ കൊല്ലരുതെന്ന് നബി(സ) ഉത്തരവു നൽകി. മോചനദ്രവ്യം നൽകി മക്കയിലേക്കു തിരിച്ചുപോയി. മക്ക കീഴടക്കുന്നതുവരെ പിന്നീടു പ്രവാചകൻ(സ)യുമായി കണ്ടുമുട്ടിയില്ല. മദീനയിലെ ജന്നത്തുൽ ബഖീഇലാണ് ഖബറടക്കിയത്.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 29, 'list_item', '28. അമ്മാറുബ്നു യാസിർ(റ): ബനൂ മഖ്സൂമിന്റെ അടിമയായിരുന്നു. പിന്നീട് സ്വതന്ത്രനാക്കപ്പെട്ടു. ഹി:37 ൽ 93 ാം വയസ്സിൽ സ്വിഫ്ഫീൻ യുദ്ധത്തിൽ വെച്ച് വഫാതായി. ഇദ്ദേഹത്തിന്റെ മയ്യിത്തു നിസ്കാരത്തിന് അലി(റ)യാണ് ഇമാമത്തു നിർവ്വഹിച്ചത്.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 30, 'list_item', '29. അസ്മാഅ്(റ): അബൂബക്കർ(റ)ന്റെ മകൾ. ''ദാത്തുന്നിത്വാഖൈൻ'' (ഇരട്ടപ്പട്ടക്കാരി) എന്നറിയപ്പെട്ടു. സ്വർഗ്ഗപ്രവേശം കൊണ്ട് സുവിശേഷമറിയിക്കപ്പെട്ട പ്രമുഖ സഹാബിയായിരുന്ന സുബൈർ(റ)വിന്റെ ഭാര്യ. അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ) ഇവരുടെ മകൻ. ആദ്യകാല മുസ്ലിം. അവർക്കു മുമ്പ് എഴുപത് വിശ്വാസികളേ ഉണ്ടായിരുന്നുള്ളൂ. മഹതി പ്രവാചക പത്നി ആഇശ(റ)യെക്കാൾ മുതിർന്നവരായിരുന്നു. നൂറാം വയസ്സിൽ മകൻ അബ്ദുല്ല(റ)വിന്റെ രക്തസാക്ഷിത്വത്തിനു പത്തോ പന്ത്രണ്ടോ ദിവസങ്ങൾക്കു ശേഷം വഫാതായി.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 31, 'list_item', '30. അലിയ്യുബ്നു അബീ ത്വാലിബ്(റ): യുവാക്കളിലെ ആദ്യ മുസ്ലിം. നാലാം ഖലീഫ. പ്രവാചകർ(സ)യുടെ പിതൃവ്യപുത്രൻ. തബൂക്കിലൊഴികെ എല്ലാ യുദ്ധങ്ങളിലും പങ്കെടുത്തു. "മൂസാ നബിക്ക് ഹാറൂൻ എന്നതുപോലെ നീയെനിക്ക് ഏറ്റവും അടുത്ത സുഹൃത്താവുന്നതിൽ സംതൃപ്തനല്ലേ?" എന്നു പ്രവാചകർ(സ) ഒരിക്കൽ ചോദിച്ചു. കുടുംബത്തെ ചികിത്സിക്കാനാണ് അലി(റ)വിനോടു തബൂക്കിൽ നിന്ന് വിട്ടുനിൽക്കാൻ കൽപിച്ചത്. ഹി: മുപ്പത്തിഅഞ്ചിൽ ഖലീഫയായി. നാല് വർഷവും ഒമ്പത് മാസവും ഖലീഫയായി തുടർന്നു. ഒരു വെള്ളിയാഴ്ച അദ്ദേഹത്തെ അബ്ദുറഹ്മാൻ എന്ന ഖാരിജി കൊലപ്പെടുത്തി. കുറിയവനായിരുന്ന അലി(റ)വിന് ഭാരിച്ച ശരീരവും സമൃദ്ധമായ താടിയുമുണ്ടായിരുന്നു. അല്ലാഹുവിന്റെ സിംഹം (അസദുല്ലാഹ്) എന്നറിയപ്പെട്ടു. ഭാര്യ ഫാത്വിമ(റ). ഹസൻ(റ), ഹുസൈൻ(റ) എന്നിവർ മക്കൾ.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 32, 'list_item', '31. അംറുബ്നുൽ ഹാരിസ്(റ): പ്രവാചക പത്നി ജുവൈരിയ(റ)യുടെ സഹോദരൻ. കൂഫാ നിവാസി.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 33, 'list_item', '32 അംറുബ്നു അബീ സൽമ(റ): ഉമ്മുസലമ(റ)യുടെ (ആദ്യ ഭർത്താവിലെ) മകൻ. ഹി: രണ്ട് അബ്സീനിയയിൽ ജനനം. പ്രവാചകർ(സ) വഫാതാകുമ്പോൾ ഒമ്പത് വയസ്സു പ്രായം. ഹി:83 ൽ വഫാത്.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 34, 'list_item', '33. അംറുബ്നുൽ ആസ്(റ): പ്രവാചകർ(സ) മുഖേന ഹിജ്റ അഞ്ചാം വർഷം ഇസ്ലാം സ്വീകരിച്ചു. തുടർന്ന് ഒമാനിലെ ഗവർണ്ണറായി. പ്രവാചകർ(സ)യുടെ വഫാത് വരെ ഈ നിലയിൽ തുടർന്നു. ഉമർ(റ)വിന്റെ കാലത്തെ പ്രഥമ ഈജിപ്ത് ജേതാവ്. തുടർന്ന് ഈജിപ്തിലെ ഗവർണ്ണറായി. പക്ഷേ, ഉസ്മാൻ(റ) തിരിച്ചുവിളിച്ചു. മുആവിയ(റ)വിന്റെ പ്രധാനമന്ത്രിയായി. പിന്നീട് ഈജിപ്തിലെ ഗവർണ്ണർ സ്ഥാനം തിരിച്ചുനൽകി. ഹി:34 ൽ 90 ാം വയസ്സിൽ വഫാത്.', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 35, 'list_item', '34. ആഇശ(റ): പ്രവാചക പത്നി. അബൂബക്കർ(റ)വിന്റെ പുത്രി. ഖദീജ(റ)യുടെ വഫാതിനെ തുടർന്നാണ് പ്രവാചകർ(സ) അവരെ വിവാഹം ചെയ്തത്. ആഇശ(റ)ക്ക് ഏഴു വയസ്സു പ്രായമായിരുന്നു. ഹി: രണ്ടാം വർഷം ഒമ്പതാം വയസ്സിൽ ദാമ്പത്യ ജീവിതം തുടങ്ങി. ഒമ്പത് വർഷം പ്രവാചകർ(സ)യോടൊപ്പം ജീവിച്ചു. നബി(സ) വഫാതാകുമ്പോൾ പതിനെട്ട് വയസ്സു പ്രായം. അറബികളുടെ ചരിത്രവും കവിതയും', null, '66' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 36, 'paragraph', 'അവർക്ക് നന്നായറിയാമായിരുന്നു. വനിതാ നിവേദകരിൽ ഏറ്റവും മുന്നിൽ ആഇശ(റ)യാണ്. 1210 ഹദീസുകൾ അവരിൽനിന്ന് നിവേദനം ചെയ്യപ്പെട്ടിരിക്കുന്നു. 174 എണ്ണം ബുഖാരിയും മുസ്‌ലിമും സ്വീകരിച്ചു. ഹി:52 ലോ, 58 ലോ മദീനയിൽ റമദാനിൽ വഫാത്. ജന്നത്തുൽ ബഖീഇൽ ഖബറടക്കി. ത്യാഗപൂർണ്ണമായ ജീവിതമായിരുന്നു അവരുടേത്. കഠിനമായ പരീക്ഷണങ്ങൾക്ക് വിധേയമാക്കപ്പെട്ട പ്രവാചക പത്നിമാരിലൊരാളായിരുന്നു ആഇശ(റ).', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 37, 'list_item', '35. ഉബാദത്തുബ്നു സ്വാമിത്(റ): നബി(സ)യുമായുണ്ടായ രണ്ടാം ഉടമ്പടിയിലും, യുദ്ധങ്ങളിലും പങ്കെടുത്തു. ഉമർ(റ)വിന്റെ കാലത്ത് ഇദ്ദേഹം പലയിടങ്ങളിലും ഖാദിയായും, മതാദ്ധ്യാപകനായും നിയമിതനായിട്ടുണ്ട്. ഹി:34 ൽ ജറൂസലേമിൽ വഫാത്.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 38, 'list_item', '36. ഉബയ്യുബ്നു കഅ്ബ്(റ): നബി(സ)യുടെ ദിവ്യബോധനങ്ങൾ എഴുതി സൂക്ഷിക്കുന്നതിന് ഇദ്ദേഹം നിയുക്തനായിരുന്നു. അൻസ്വാരികളുടെ നേതാവായി അറിയപ്പെട്ടു. ഖുർആൻ പാരായണത്തിൽ നിപുണനായിരുന്നു. ഹി:16 ൽ മദീനയിൽ വഫാത്. പല സ്വഹാബികളും ഇദ്ദേഹത്തിൽ നിന്ന് ഹദീസ് കേട്ടിട്ടുണ്ട്.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 39, 'list_item', '37. ഉമറുബ്നുൽ ഖത്വാബ്(റ): നബി(സ)യുടെ നുബുവ്വത്തിന്റെ ആറാം വർഷം ഇസ്‌ലാം സ്വീകരിച്ചു. നബി(സ)യെ വധിക്കുക എന്ന ഉദ്ദേശ്യത്തോടെ പുറപ്പെട്ട അവസരത്തിൽ ഖുർആൻ പാരായണത്തിൽ ആകൃഷ്ടനായി അദ്ദേഹം മുസ്‌ലിമായി. രണ്ടാം ഖലീഫ. അമീറുൽ മുഅ്മിനീൻ എന്ന സ്ഥാനപ്പേര് ആദ്യം വഹിച്ച മഹാൻ. പത്തര വർഷം ഖിലാഫത്ത് നടത്തി. ഹി:24 ൽ 63 ാം വയസ്സിൽ വഫാത്.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 40, 'list_item', '38. ഉമ്മു സലമ(റ): ആദ്യ ഭർത്താവ് അബൂ സലമ(റ)വിന്റെ മരണാനന്തരം ഹിജ്റ നാലിൽ നബി(സ) വിവാഹം ചെയ്തു. ഹി:59 ൽ 84 ാം വയസ്സിൽ മരണം. ജന്നതുൽ ബഖീഇൽ മറവു ചെയ്യപ്പെട്ടു. ഇബ്നു അബ്ബാസ്(റ), ആഇശ(റ), സൈനബ്(റ), തുടങ്ങിയവർ ഈ മഹതിയിൽ നിന്ന് ഹദീസുകൾ നിവേദനം ചെയ്തിട്ടുണ്ട്.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 41, 'list_item', '39. ഉമ്മു ഹബീബ(റ): പ്രവാചക പത്നി. അബൂ സുഫ്യാന്റെ മകളായിരുന്നു. ഹി:41 ൽ മദീനയിൽ വഫാത്. നിരവധി ഹദീസുകൾ നിവേദനം ചെയ്തിട്ടുണ്ട്.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 42, 'list_item', '40. ഉസൈദുബ്നു ഹുദൈർ(റ): അഖബയിലെ രണ്ടാം ഉടമ്പടിയിൽ പങ്കെടുത്തു. നബി(സ)യോടൊപ്പം യുദ്ധങ്ങളിലും പങ്കെടുത്തു. ഹി:30 ൽ മദീനയിൽ വഫാത്. ജന്നതുൽ ബഖീഇൽ ഖബറടക്കി.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 43, 'list_item', '41. ഔഫ് ഇബ്നു മാലിക്(റ): ഖൈബർ യുദ്ധത്തിൽ പങ്കെടുത്തു. മക്കാ വിജയ ദിനത്തിൽ അശ്ജഈ ഗോത്രത്തിന്റെ പതാകയേന്തി. പിന്നീട് സിറിയയിൽ താമസമാക്കി. ഹി:73 ൽ നിര്യാണം. ധാരാളം സ്വഹാബികളും താബിഉകളും ഇദ്ദേഹത്തിൽനിന്ന് ഹദീസുകൾ സ്വീകരിച്ചു.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 44, 'list_item', '42. കഅ്ബുബ്നു മാലികുൽ അൻസ്വാരി(റ): ബദ്റിനു ശേഷമുള്ള എല്ലാ യുദ്ധങ്ങളിലും പങ്കെടുത്തു. ഹുദൈബിയ സന്ധിയിൽ പങ്കെടുത്തവരിലൊരാൾ. തബൂക്ക് യുദ്ധത്തിൽ നിന്ന് മാറിനിന്ന കാരണത്താൽ നബി(സ)യും സ്വഹാബികളും ഇദ്ദേഹത്തോട് വെറുപ്പ് പ്രകടിപ്പിച്ചു. എന്നാൽ ഇദ്ദേഹം പിന്നീട് പശ്ചാത്തപിക്കുകയും, അല്ലാഹു അത് സ്വീകരിക്കുകയും ചെയ്തു.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 45, 'list_item', '43. ഖദീജ ബിൻത് ഖുവൈലിദ്(റ): കച്ചവട പ്രമുഖ, വിധവയായിരിക്കെ 40 ാം വയസ്സിൽ നബി(സ) വിവാഹം ചെയ്തു. നബി(സ)യുടെ ആദ്യ പത്നിയും, ഇസ്‌ലാം സ്വീകരിച്ച ആദ്യ വ്യക്തിയും ഈ മഹതി തന്നെ. ഹിജ്റക്ക് മൂന്നു വർഷം മുമ്പ് 65 ാം വയസ്സിൽ വഫാതായി. നബി(സ)യുടെ മക്കളിൽ ഇബ്രാഹീം ഒഴികെയുള്ളവരുടെയെല്ലാം മാതാവാണിവർ.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 46, 'list_item', '44. ഖബ്ബാബുബ്നുൽ അറത്(റ): ഖബ്ബാബുബ്നു അറതുബ്നു ജന്തല(റ) ഇസ്‌ലാമിനു മുമ്പ് ഒരു അടിമയായിരുന്നുവെങ്കിലും ദയാലുവായ ഒരു മഹതി ഇദ്ദേഹത്തെ വിലക്കു വാങ്ങുകയും, സ്വതന്ത്രനാക്കുകയും ചെയ്തു. ഇസ്‌ലാം സ്വീകരിച്ചതിനാൽ ശത്രുക്കളുടെ ക്രൂരമായ മർദ്ദനങ്ങൾക്കിരയായി. കൂഫയിൽ താമസിച്ച് അവിടെ വെച്ച് ഹി:73 ൽ നിര്യാതനാവുകയും ചെയ്തു.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 47, 'list_item', '45. ഖാലിദുബ്നുൽ വലീദ്(റ): യുദ്ധത്തിൽ വളരെ കഴിവ് പ്രകടിപ്പിച്ച സ്വഹാബി. ''അല്ലാഹുവിന്റെ വാൾ'' എന്ന് നബി(സ) ഇദ്ദേഹത്തിന് പേരു നൽകി. ഹി:21 ൽ വഫാതായി. ഇബ്നു അബ്ബാസ്(റ), അൽഖമ(റ), സുബൈർ(റ) തുടങ്ങിയവർ ഇദ്ദേഹത്തിൽ നിന്ന് ഹദീസ് നിവേദനം ചെയ്തിട്ടുണ്ട്.', null, '67' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 48, 'list_item', '46. ജരീറുബ്നു അബ്ദില്ല(റ): അബൂ അഅ്മർ എന്നും അറിയപ്പെടുന്നു. നബി(സ)യുടെ വഫാതിന് നാൽപതു ദിവസം മുമ്പ് ഇസ്‌ലാം സ്വീകരിച്ചു. ഹി:51 ൽ നിര്യാതനായി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 49, 'list_item', '47. തമീമുദ്ദാരി(റ): ഒരു ക്രിസ്ത്യാനിയായിരുന്ന ഇദ്ദേഹം കടൽ യാത്രക്കിടെ കപ്പൽ തകർന്ന് ഒരു ദ്വീപിലെത്തിപ്പെടുകയും നബി(സ)യുടെ പ്രവാചകത്വത്തെ സത്യപ്പെടുത്തുന്ന പല അത്ഭുതങ്ങൾക്കും സാക്ഷിയാവുകയും തുടർന്ന് പ്രവാചക സന്നിധിയിൽ വന്ന് മുസ്‌ലിമാവുകയും ചെയ്തു. ഈ ഭക്തൻ മദീനയിൽ നിന്നും ബസ്വറയിലേക്കു മാറിത്താമസിക്കുകയും, അവിടെ വെച്ച് വഫാതാവുകയും ചെയ്തു.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 50, 'list_item', '48. ദാവൂദുബ്നു സ്വാലിഹ്(റ): താബിഅ്; മദീനയിലെ അൻസ്വാരികളിലൊരാളുടെ അടിമയായിരുന്നു. മാതാപിതാക്കളിൽ നിന്നും ഹദീസുകൾ നിവേദനം ചെയ്തു.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 51, 'list_item', '49. ദാവൂദുബ്നു ഹുസൈൻ(റ): താബിഅ്. അംറുബ്നു ഉസ്മാനുബ്നു അഫ്ഫാന്റെ വിമുക്ത അടിമ. ഇക്‌രിമ(റ)ൽ നിന്നും മറ്റും ഹദീസ് നിവേദനം ചെയ്തു. 72 വർഷത്തെ ജീവിതത്തിനു ശേഷം ഹി:135 ൽ നിര്യാണം.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 52, 'list_item', '50. ഫള്‌ലുബ്നു അബ്ബാസ്(റ): ഹുനൈൻ യുദ്ധത്തിൽ നബി(സ)യോടൊപ്പം പോരാടി. ഫത്‌ഹു മക്കയിലും ഇദ്ദേഹം സന്നിഹിതനായിരുന്നു. 21 ാം വയസ്സിൽ സിറിയയിൽ പ്ലേഗു ബാധിച്ചു വഫാതായി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 53, 'list_item', '51. ഫള്‌ലുബ്നു ഉബൈദ്(റ): ഔസ് ഗോത്രക്കാരനായ അൻസ്വാരി. അനേകം വിശുദ്ധ യുദ്ധങ്ങളിലെ പോരാളി. ദമസ്കസിൽ താമസമാക്കി. സ്വിഫ്ഫീൻ യുദ്ധത്തിൽ പങ്കെടുത്തു.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 54, 'list_item', '52. ഫാത്വിമ(റ): പ്രവാചകർ(സ)യുടെ പ്രിയ പുത്രി, അലി(റ)യുടെ പത്നി, ഇമാം ഹസൻ(റ), ഹുസൈൻ(റ), മുഹ്‌സിൻ(റ) എന്നിവരുടെ മാതാവ്. മുസ്‌ലിം വനിതകളുടെ നായികയായി ഇവരെയാണ് തെരഞ്ഞെടുക്കപ്പെട്ടത്. നബി(സ)യുടെ വിയോഗത്തിൽ അതീവ ദു:ഖിതയായ ഫാത്വിമ(റ) തന്റെ 28 ാം വയസ്സിൽ വഫാതായി. അബ്ബാസ്(റ) ഇവരുടെ ജനാസ നിസ്കാരത്തിനു നേതൃത്വം നൽകി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 55, 'list_item', '53. ഫാത്വിമബിൻത് ഖൈസ്(റ): ഖുറൈശി ഗോത്രക്കാരി. നബി(സ)യോടൊപ്പം മദീനയിലേക്ക് പാലായനം ചെയ്തു. സൗന്ദര്യവും, ബുദ്ധിയും ഒത്തിണങ്ങിയ അവർ അംറുബ്നു ഹഫ്സിന്റെ പത്നിയായിരുന്നു. അദ്ദേഹം അവരെ വിവാഹമോചനം ചെയ്തപ്പോൾ നബി(സ) അവരെ ഉസാമാതുബ്നു സൈദ്(റ)വിനു വിവാഹം ചെയ്തു കൊടുത്തു.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 56, 'list_item', '54. ബറാഉബ്നു ആസിബ്(റ): കൂഫാ നിവാസി. ഹി:14 ൽ കൂഫ കീഴടക്കി. ജമൽ, സ്വിഫ്ഫീൻ, നഹ്റുവാൻ യുദ്ധങ്ങളിൽ അലി(റ)വിനോടൊപ്പം പങ്കെടുത്തു. കൂഫയിൽ വെച്ച് വഫാതായി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 57, 'list_item', '55. ബിലാലുബ്നു റബാഹ്(റ): പ്രസിദ്ധ സ്വഹാബി. ഉമയ്യതുബ്നു ഖലഫിന്റെ അടിമയായിരുന്ന ബിലാലിനെ ഇസ്‌ലാം സ്വീകരിച്ചതിന് അതികഠിനമായി പീഡിപ്പിച്ചു. നെഞ്ചിൽ ഭാരമേറിയ പാറക്കല്ല് വെച്ചു. ചുട്ടുപഴുത്ത മരുഭൂമിയിലൂടെ വലിച്ചിഴച്ചു. അപ്പോഴും അദ്ദേഹം ''അഹദ്, അഹദ്'' എന്നു വിളിച്ചുപറഞ്ഞു. ബിലാൽ(റ)വിനെ അബൂബക്കർ(റ) മോചനദ്രവ്യം നൽകി സ്വതന്ത്രനാക്കി. ഇസ്‌ലാമിലെ ആദ്യത്തെ മുഅദ്ദിനായിരുന്നു. സിറിയയിൽ താമസമാക്കിയ ബിലാൽ(റ) ഹി:20 ൽ 63 ാം വയസ്സിൽ വഫാതായി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 58, 'list_item', '56. ബുസ്ർ ഇബ്നു അബീഅർതഹ്(റ): ഖുറൈശ് വംശജൻ. മുആവിയ(റ)വിന്റെ ഭരണ കാലത്തു വഫാത്.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 59, 'list_item', '57. മിസ്‌വറുബ്നു മഖ്റുമ(റ): ഹിജ്റ രണ്ടാം വർഷം മക്കയിൽ ജനനം. നബി(സ)യിൽ നിന്നുതന്നെ ഖുർആൻ പഠിച്ചു. യസീദുബ്നു മുആവിയയുടെ ഖിലാഫത്തിനെ അനുകൂലിക്കാത്തതിനാൽ യസീദിന്റെ പട്ടാളക്കാർ ഇദ്ദേഹത്തെ ഹി:54 ൽ കല്ലെറിഞ്ഞു കൊന്നു.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 60, 'list_item', '58. മുസ്അബുബ്നു ഉമൈർ(റ): നബി(സ)യുടെ അടുത്ത സ്വഹാബി. ശത്രു പീഢനത്താൽ ആദ്യം അബ്സീനിയയിലേക്ക് പലായനം ചെയ്തു. ഹിജ്റക്കു മുമ്പ് മദീനാ വാസികളെ ഖുർആൻ പഠിപ്പിക്കാൻ നിയുക്തനായി. ഉഹ്ദ് യുദ്ധത്തിൽ 40 ാം വയസ്സിൽ രക്തസാക്ഷിയായി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 61, 'list_item', '59. മുആദുബ്നു ജബൽ(റ): അഖബയിലെ രണ്ടാം ഉടമ്പടിയിൽ പങ്കെടുത്ത എഴുപതു പേരിലൊരാൾ. നബി(സ)യോടൊപ്പം യുദ്ധങ്ങളിൽ പങ്കെടുത്തു. യമനിലെ മതാദ്ധ്യാപകനായും, വിധികർത്താവായും നബി(സ) ഇദ്ദേഹത്തെ നിയമിച്ചു. ഉമർ(റ)വിന്റെ കാലത്ത് സിറിയൻ ഗവർണ്ണറായി. ഹി: 18 ൽ, 68 ാം വയസ്സിൽ പ്ലേഗ് ബാധിച്ചു വഫാതായി.', null, '68' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 62, 'list_item', '60. മുആവിയത്തുബ്നു അബീ സുഫ്‌യാൻ(റ): മക്കാ വിജയകാലത്ത് ഇദ്ദേഹവും പിതാവും ഇസ്‌ലാം സ്വീകരിച്ചു. നബി(സ)യുടെ വഹ്‌യ് എഴുതി വെക്കുന്നവരിൽ ഒരാളായിരുന്നു. അലി(റ)ക്കു ശേഷം 20 വർഷം ഭരണം നടത്തി. ഹി:60 ൽ ഡമാസ്കസിൽ വെച്ച് വഫാതായി.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 63, 'list_item', '61. ലബീദുബ്നു റബീഅ(റ): ''സബ്‌ഉൽ മുഅല്ലഖാത്ത്'' (സപ്ത മഹാകാവ്യങ്ങൾ)ൽ ഒന്നിന്റെ രചയിതാവ്. ഇസ്‌ലാമിനു മുമ്പും ശേഷവും സമൂഹത്തിൽ പ്രമുഖ സ്ഥാനം അലങ്കരിച്ചിരുന്നു. ഹി:40 ൽ, 140 ാം വയസ്സിൽ വഫാത്.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 64, 'list_item', '62. വലീദുബ്നുൽ വലീദ്(റ): ഖാലിദുബ്നുൽ വലീദ്(റ)വിന്റെ സഹോദരൻ, സേനാനായകൻ. ബദ്ർ യുദ്ധ കാലത്ത് മുസ്‌ലിമായിരുന്നില്ല. ഖുറൈശികൾ ഇദ്ദേഹത്തെ മക്കയിൽ വെച്ച് തടവുകാരനായി പിടിക്കുകയും, പിന്നീട് വിട്ടയക്കുകയും ചെയ്തു.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 65, 'list_item', '63. സഈദുബ്നു സൈദ്(റ): സ്വർഗ്ഗം കൊണ്ട് സന്തോഷവാർത്ത അറിയിക്കപ്പെട്ടവരിലൊരാൾ. ബദ്ർ യുദ്ധമൊഴികെ മറ്റെല്ലാ യുദ്ധങ്ങളിലും പങ്കെടുത്തു. ഉമർ(റ)വിന്റെ സഹോദരി ഫാത്വിമ(റ)യെ വിവാഹം ചെയ്യുകയും, ആ മഹതിയുടെ പ്രചോദനംമൂലം ഇസ്‌ലാം മതം സ്വീകരിക്കുകയും ചെയ്തു. ഹി;51 ൽ, 70 ാം വയസ്സിൽ നിര്യാതനായി.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 66, 'list_item', '64. സൽമാനുൽ ഫാരിസി(റ): പേർഷ്യയിൽ ജനനം. ബാല്യത്തിലേ മതപരമായ തൃഷ്ണയുള്ളതിനാൽ സത്യമതം അന്വേഷിച്ചുനടന്ന് പല ദുരിതങ്ങളും അനുഭവിക്കേണ്ടി വന്നു. ഹിജ്റ കഴിഞ്ഞയുടൻ ഇസ്‌ലാം സ്വീകരിച്ചു. "സൽമാൻ എന്റെ കുടുംബത്തിലെ ഒരംഗമാണ്" എന്ന് നബി(സ) പറഞ്ഞിട്ടുണ്ട്. ഖൻദഖ് യുദ്ധത്തിൽ മദീനക്കു ചുറ്റും കിടങ്ങുകൾ കുഴിച്ചത് ഇദ്ദേഹത്തിന്റെ നിർദ്ദേശ പ്രകാരമായിരുന്നു. ഹി:35 ൽ വഫാതായി.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 67, 'list_item', '65. സുബൈറുബ്നുൽ അവ്വാം(റ): ആദ്യ മുസ്‌ലിം സംഘത്തിൽപ്പെട്ട, സ്വർഗ്ഗം കൊണ്ട് സന്തോഷവാർത്ത അറിയിക്കപ്പെട്ട സ്വഹാബി. ഹി:39 ൽ നടന്ന ജമൽ യുദ്ധത്തിൽ വഫാതായി. പുത്രന്മാരായ അബ്ദുല്ല(റ), ഉർവ്വ(റ) എന്നിവർ പിതാവിൽ നിന്ന് ലഭിച്ച ഹദീസുകൾ നിവേദനം ചെയ്തിട്ടുണ്ട്.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 68, 'list_item', '66. സ്വഫിയ്യ(റ): ഇസ്രാഈൽ സന്തതികളിൽ പെട്ടവർ, പ്രവാചക പത്നി. ഖൈബർ യുദ്ധത്തിൽ ആദ്യ ഭർത്താവ് മരണപ്പെട്ടപ്പോൾ നബി(സ) വിവാഹം ചെയ്തു. ഹി:50 ൽ വഫാതായി.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 69, 'list_item', '67. സൈദുബ്നു സാബിത്(റ): നബി(സ)ക്ക് ലഭിക്കുന്ന വഹ്യുകൾ അപ്പപ്പോൾ എഴുതി വെക്കുന്നവരിൽ പ്രസിദ്ധൻ. അബൂബക്കർ(റ), ഉസ്മാൻ(റ) എന്നിവർ ഖുർആൻ ക്രോഡീകരണം ഇദ്ദേഹത്തെയാണ് ഏൽപിച്ചിരുന്നത്. ഹി:40 ൽ മദീനയിൽ വഫാത്.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 70, 'list_item', '68. സൈദുബ്നു ഹാരിസ(റ): ഒരു അടിമയായിരുന്നു. നബി(സ) മോചിപ്പിച്ചു. ജീവിതത്തിന്റെ മുഖ്യഭാഗം പ്രവാചക സേവനത്തിനായി ചിലവഴിച്ചു. മുഅ്തഃ യുദ്ധത്തിന്റെ നേതൃത്വം നബി(സ) ഇദ്ദേഹത്തെയായിരുന്നു ഏൽപിച്ചിരുന്നത്.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 71, 'list_item', '69. സൈനബ് ബിൻത് ജഹ്ശ്(റ): പ്രവാചക പത്നി. വിമുക്ത അടിമയായിരുന്ന സൈദുബ്നു ഹാരിസ(റ)വായിരുന്നു ഇവരെ ആദ്യം വിവാഹം ചെയ്തിരുന്നത്. വിവാഹ മോചനാനന്തരം പ്രവാചക പത്നി പദം സ്വീകരിച്ചു. ആഇശ(റ), ഉമ്മു ഹബീബ(റ) തുടങ്ങിയവർക്ക് ഇവരിൽ നിന്നും ഹീസുകൾ ലഭിച്ചിട്ടുണ്ട്.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 72, 'list_item', '70. ഹകീമുബ്നു ഹിസാം(റ): ഹകീമുബ്നു ഹിസാമുബ്നു ഖുവൈലിദുബ്നു അസദ് എന്നാണ് മുഴുവൻ പേര്. ഖുവൈലിദിന്റെ മകൾ ഖദീജ(പ്രവാചക പത്നി)യുടെ സഹോദര പുത്രൻ. ഗർഭിണിയായിരിക്കെ തന്റെ മാതാവ് ഖുറൈശി വനിതകളോടൊപ്പം കഅ്ബയിൽ പ്രവേശിക്കുകയും, പ്രസവ വേദന അനുഭവപ്പെടുകയും, അവിടെവെച്ച് പ്രസവിക്കുകയും ചെയ്തു. 60 വർഷം ഇസ്‌ലാമിലും, 60 വർഷം ജാഹിലിയ്യത്തിലുമായി 120 വയസ്സുവരെ ജീവിച്ചു. ആനക്കലഹ സംഭവത്തിന്റെ 10 വർഷം മുമ്പാണ് അദ്ദേഹം ജനിച്ചതെന്ന അഭിപ്രായമുണ്ട്. മക്കാ വിജയത്തിനുശേഷം ഇസ്‌ലാം സ്വീകരിച്ചു. ഇസ്‌ലാമിനു മുമ്പും ശേഷവും സമൂഹത്തിൽ സ്ഥാനമുണ്ടായിരുന്നു.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 73, 'list_item', '71. ഹൻളലതുബ്നുറബീഅ്(റ): അബൂ റബീഅ് എന്ന് സ്ഥാനപ്പേര്. നബി(സ)യുടെ ദിവ്യബോധനങ്ങൾ എഴുതി വെച്ചിരുന്നതിനാൽ ''എഴുത്തുകാരൻ'' (കാതിബ്) എന്നപേരിൽ പ്രസിദ്ധനായി.', null, '69' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 74, 'list_item', '72. ഹഫ്സ്വ ബിൻത് ഉമർ(റ): പ്രവാചക പത്നി. ആദ്യം ഖനിസുബ്നു ഹുദൈഫ(റ)വിന്റെ ഭാര്യയായിരുന്നു. നബി(സ)യിൽ നിന്ന് ധാരാളം ഹദീസുകൾ നിവേദനം ചെയ്തു.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 75, 'list_item', '73. ഹസൻ ബസ്വരി(റ): ഖലീഫ ഉമർ(റ)വിന്റെ കാലത്ത് മദീനയിൽ ജനനം. ഉമർ(റ)വാണ് കുട്ടിക്ക് മധുരം കൊടുത്തത്. പ്രവാചക പത്നി ഉമ്മുസൽമ(റ)യുടെ പരിചാരികയായിരുന്നു മാതാവ്. ബസ്വറയിൽ താമസമാക്കി. അനസ്ബ്നു മാലിക്(റ), അബൂമൂസാ(റ), ഇബ്നു അബ്ബാസ്(റ) തുടങ്ങിയവരിൽ നിന്നു ഹദീസ് നിവേദനം ചെയ്തു. ഭക്തനും, സൂഫിയുമായിരുന്ന ഹസൻ(റ) ഹി:120 ൽ വഫാതായി.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 76, 'list_item', '74. ഹസ്സാനുബ്നു സാബിത്(റ): യഥാർത്ഥ പേര് തൈമുല്ലാഹിബ്നു സഅ്‌ലബൽ അൻസ്വാരിൽ ഖസ്റജി. അബ്ദുൽ വലീദ് എന്ന് സ്ഥാനപ്പേരുണ്ട്. മാതാവ് ഖുറൈഅ ബിൻത് ഖാലിദ്. നബി(സ)യുടെ കവിയായിരുന്നു. ആഇശ(റ)യെ കുറിച്ച് കവിത ചൊല്ലിയിട്ടുണ്ട്. നബി(സ)യെ പ്രകീർത്തിച്ച് കവിത ചൊല്ലാൻ നബി(സ) അദ്ദേഹത്തിന് വേദിയൊരുക്കിക്കൊടുക്കാറുണ്ട്. ധൈര്യം കുറഞ്ഞ വ്യക്തിയായിരുന്നു, അതിനാൽ നബി(സ)യോടൊപ്പം യുദ്ധങ്ങളിലൊന്നും പങ്കെടുത്തിട്ടില്ല. അലി(റ)യുടെ ഭരണ കാലത്താണ് ഇദ്ദേഹം വഫാതായത്. 60 വർഷം ഇസ്‌ലാമിലും, 60 വർഷം ജാഹിലിയ്യത്തിലുമായി 120 വയസ്സു വരെ ജീവിച്ചു.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 77, 'list_item', '75. ഹാത്വിബുബ്നു അബീ ബൽതഅ(റ): ബദ്ർ, ഖൻദഖ് യുദ്ധങ്ങളിൽ പങ്കെടുത്തു. ഹി:30 ൽ, 65 ാം വയസ്സിൽ വഫാതായി.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 78, 'list_item', '76. ഹാരിസതുബ്നു നുഅ്‌മാൻ(റ): ബദ്റിലും, ഉഹ്ദിലും പങ്കെടുത്ത പ്രസിദ്ധ സ്വഹാബി. ജിബ്‌രീൽ ഒരിക്കലിദ്ദേഹത്തിനു സലാം പറഞ്ഞു.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 79, 'list_item', '77. ഹാരിസുബ്നു ഹിശാം(റ): അബൂ ജഹലിന്റെ സഹോദരൻ. മക്കാ വിജയദിനം ഇസ്ലാം സ്വീകരിച്ചു. ഉമർ(റ)വിന്റെ കാലത്തു സിറിയയിലേക്ക് താമസം മാറ്റി. ഹി:15 ൽ യർമൂക് യുദ്ധത്തിൽ വധിക്കപ്പെട്ടു. നബി(സ) ഒരിക്കലിദ്ദേഹത്തിന് നൂറ് ഒട്ടകങ്ങൾ സമ്മാനം നൽകി.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 80, 'list_item', '78. ഹിന്ദ് ബിൻത് ഉത്ബ(റ): അബൂസുഫ്‌യാൻ(റ)വിന്റെ ഭാര്യ. മുആവിയ(റ)വിന്റെ ഉമ്മ. മക്കാ ഫത്ഹിൽ ഇസ്‌ലാം സ്വീകരിച്ചു. ഉഹ്ദിൽ വധിക്കപ്പെട്ട ഹംസ(റ)യുടെ കരൾ മാന്തിയെടുത്തു ചവച്ചരച്ചു തുപ്പി പ്രതികാരം തീർത്തു. ഉമർ(റ)വിന്റെ ഭരണകാലത്തു വഫാത്.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 81, 'list_item', '79. ഹിശാമുബ്നു ഉർവ(റ): സുബൈർ(റ)വിന്റെ പൗത്രൻ. അതീവ ഭക്തനും, പണ്ഡിതനും. അബ്ദുല്ലാഹിബ്നു സുബൈർ(റ), ഇബ്നു ഉമർ(റ) എന്നിവരിൽ നിന്ന് ഹദീസുകൾ പഠിച്ചു. ബഗ്ദാദിൽ ചെന്നു ഖലീഫാ മൻസൂറിനെ കണ്ടു. ഹി:61 ൽ ജനനം. ഹി:146 ൽ വഫാത്.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 82, 'list_item', '80. ഹുദൈഫതുബ്നുൽയമാൻ(റ): ചില ഹദീസുകൾ റിപ്പോർട്ടു ചെയ്തിട്ടുണ്ട്. പേർഷ്യൻ തലസ്ഥാനമായ മദാഇനിൽ ഹി:35 ലോ, 36 ലോ വഫാതായി.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 83, 'list_item', '81. ഹുസൈൻ ഇബ്നു അലി(റ): പ്രവാചക പൗത്രൻ. മാതാവ് ഫാത്വിമ(റ). പിതാവ് അലി(റ). ഹി:4 ൽ ജനനം. ഹി:61, മുഹർറം 10 ന് അമവീ ഭീകരന്മാരാൽ വധിക്കപ്പെട്ടു.', null, '70' from articles where volume_id=1 and section_no=7;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 84, 'list_item', '82. ഹംസത്തുബ്നു അബ്ദുൽ മുത്ത്വലിബ്(റ): നബി(സ)യുടെ പ്രസിദ്ധ പിതൃവ്യനും, ധീര സേനാനിയും. ഉഹ്ദിൽ രക്തസാക്ഷിയായി. ഹംസ(റ) പ്രവാചകർ(സ)യുടെ മുലകുടി ബന്ധത്തിലെ സഹോദരനുമാണ്. പ്രവാചകത്വ ലബ്ധിയുടെ രണ്ടാം വർഷം ഇസ്‌ലാം സ്വീകരിച്ചു. ഉഹ്ദ് യുദ്ധത്തിൽ വഹ്ശി ഇബ്നു ഹർബ് ആണ് ഹംസ(റ)വിനെ വധിച്ചത്. വഹ്ശി പിന്നീട് ഇസ്‌ലാം സ്വീകരിച്ചു. പ്രവാചകനെക്കാൾ നാലു വയസ്സിനു മുതിർന്നവരായിരുന്നു ഹംസ(റ). അലി(റ), അബ്ബാസ്(റ), സൈദ്(റ) തുടങ്ങിയവർ ഹംസ(റ)വിൽ നിന്നു ഹദീസ് നിവേദനം ചെയ്തു. ഉഹ്ദ് പർവ്വതത്തിനടുത്താണു അദ്ദേഹത്തിന്റെ ഖബർ.', null, '70' from articles where volume_id=1 and section_no=7;
insert into articles (volume_id, section_no, title_ml, start_page, end_page) values (1, 32, 'ഗ്രന്ഥകർത്താവിനെക്കുറിച്ച്', '899', '900');
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 1, 'paragraph', '1946 ജൂൺ ഇരുപത്തി അഞ്ചിന് ചെർപ്പുളശ്ശേരിയിൽ ജനിച്ചു. പിതാവ് നെല്ലിക്കുറുശ്ശി മുഹമ്മദ്. മാതാവ് മത്തിൽ തിത്തിക്കുട്ടി ആലിപ്പറമ്പ്.', null, '899' from articles where volume_id=1 and section_no=32;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 2, 'paragraph', 'ചെർപ്പുളശ്ശേരി ഗവ. ഹൈസ്ക്കൂളിൽനിന്നും 1962ൽ എസ്.എസ്.എൽ.സി. പാസായി.1966 ൽ ഫാറൂഖ് കോളേജിൽനിന്നു ബി.എ. എക്കണോമിക്സ് പാസായി. 1968ൽ അലിഗർ മുസ്ലിം യൂണിവേഴ്സിറ്റിയിൽനിന്ന് ഹിസ്റ്റ്റിയിൽ ബിരുദാനന്തര ബിരുദം നേടി. കാലിക്കറ്റ് യൂണിവേഴ്സിറ്റിയിൽനിന്നും മുൻ വൈസ്ചാൻസലർ ഡോ. ടി.കെ. രവീന്ദ്രന്റെ കീഴിൽ പി.എച്ച്.ഡി ബിരുദം നേടി. 1968 മുതൽ 2001 വരെ പോക്കർ സാഹിബ് മെമ്മേറിയൽ ഓർഫനേജ് കോളേജ് (തുരൂരങ്ങാടി) ചരിത്രവിഭാഗം തലവനായി സേവനമനുഷ്ഠിച്ചു. 2002 മുതൽ 2005 വരെ കാലിക്കറ്റ് സർവകലാശാലയിൽ ചെയർഫോർ ഇസ്ലാമിക് സ്റ്റഡീസ് ആന്റ് റിസർച്ചിന്റെ പ്രൊഫസറായി സേവനമനുഷ്ഠിച്ചു. അതിനു മുമ്പ് കാലിക്കറ്റ് യൂനിവേഴ്സിറ്റി ബോർഡ് ഓഫ് സ്റ്റഡീസ് ഇൻ ഇസ്ലാമിക് ചെയർമാനായിരുന്നു.', null, '899' from articles where volume_id=1 and section_no=32;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 3, 'paragraph', 'ഇന്ത്യൻ ഹിസ്റ്റ്റി കോൺഗ്രസ്സ്, സൗത്ത് ഇന്ത്യൻ ഹിസ്റ്റ്റി കോൺഗ്രസ് എന്നിവയിൽ ഗവേഷണ പ്രബന്ധങ്ങൾ അവതരിപ്പിച്ചു. പി.എസ്.എം.ഒ. കോളേജിലെ അഡൽറ്റ് എഡുക്കേഷൻ ഡയരക്ടർ, ഇൻസിറ്റ്യൂറ്റ് ഓഫ് ഫണ്ടമെന്റൽ റിസർച്ച് (കോഴിക്കോട്) ഡയറക്ടർ, കേരള ഇസ്ലാമിക് മിഷന്റെ സ്ഥാപക പ്രസിഡന്റ്, തിരൂരങ്ങാടിയിലെ മലബാർ സെൻട്രൽ സ്കൂൾ ട്രസ്റ്റിന്റെ സ്ഥാപക ചെയർമാൻ, എടയൂരിലെ ജംഇയ്യത്തുൽ മുസ്തർശിദീൻ ചെയർമാൻ, കാലിക്കറ്റ് യൂനിവേഴ്സിറ്റി ഫാക്കൽറ്റി ഓഫ് ഹ്യൂമാനിറ്റീസ് മെമ്പർ, ബോർഡ് ഓഫ് സ്റ്റഡീസ് ഇൻ ഹിസ്റ്റ്റി മെമ്പർ, സൗത്ത് ഇന്ത്യൻ ഹിസ്റ്റ്റി കോൺഗ്രസ്സ് എക്സിക്യൂട്ടീവ് അംഗം, മഹാത്മാഗാന്ധി യൂനിവേഴ്സിറ്റിയുടെ ബോർഡ് ഓഫ് സ്റ്റഡീസ് ഇൻ ഇസ്ലാമിക് ഹിസ്റ്റ്റി മെമ്പർ തുടങ്ങിയ സ്ഥാനങ്ങൾ വഹിച്ചിട്ടുണ്ട്.', null, '899' from articles where volume_id=1 and section_no=32;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 4, 'paragraph', 'ഭാര്യമാർ: കെ. ഹബീബ, വി.പി. ഹഫ്സ', null, '899' from articles where volume_id=1 and section_no=32;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 5, 'paragraph', 'മക്കൾ: മുഹമ്മദ് അമീൻ പാഷ, സുമയ്യ, മാജിദ (late), ശമീമ, സാജിദ്, സുലാല (late), നാജിദ്, തസ്നീം ഫാത്തിമ, സാജിദ, നാജിദ, ഷാക്കിറ, താഹിറ, സയ്യിദ, ഹിഷാം പാഷ, ആയിശാ നശാത്ത് പാഷ.', null, '899' from articles where volume_id=1 and section_no=32;
insert into article_blocks (article_id, seq, kind, text_ml, rows, page) select id, 6, 'paragraph', 'മരുമക്കൾ: എം.എ. ബാബു, എം.സി.എ. നാസർ, ബദീഉസ്സമാൻ, ഈസാ അനീസ്, ഷറഫുദ്ദീൻ, അഹമ്മദ് ഷമീം, അബ്ദുറഫീഖ്, അലി കണ്ടാനത്ത്, ഫാത്തിമ ഫെബിന, സറീന, സലീന.', null, '899' from articles where volume_id=1 and section_no=32;
